INSERT INTO `announcements` VALUES (3,'欢迎来到墨香阁','欢迎大家来到墨香阁博客系统！这里是一个分享技术与生活的平台，希望大家能够在这里找到有价值的内容。\r\n\r\n我们致力于为用户提供优质的阅读和交流体验，包括：\r\n- 文章发布与阅读\r\n- 评论互动\r\n- 私信聊天\r\n- 相册分享\r\n- 刷题练习\r\n\r\n感谢您的支持！','info',1,1,0,1,'2026-01-07 22:00:33','2026-01-07 22:00:33',NULL,NULL),(4,'网站功能介绍','本站主要功能包括：\r\n\r\n📝 文章系统\r\n- 支持Markdown编辑\r\n- 分类标签管理\r\n- 文章收藏点赞\r\n\r\n💬 社交功能\r\n- 评论互动\r\n- 私信聊天\r\n- 用户关注\r\n\r\n📚 学习工具\r\n- 在线刷题\r\n- 知识问答\r\n\r\n🎨 个性化\r\n- 个人相册\r\n- 主题切换\r\n- 个性签名\r\n\r\n欢迎大家积极参与，共同建设我们的技术社区！','success',0,1,0,1,'2026-01-07 22:00:33','2026-01-07 22:00:33',NULL,NULL),(5,'使用须知','为了维护良好的社区环境，请大家遵守以下规则：\r\n\r\n1. 发布内容应积极向上，不得包含违法违规信息\r\n2. 尊重他人，文明交流，禁止恶意攻击\r\n3. 原创内容请标明出处，尊重知识产权\r\n4. 合理使用系统资源，不得恶意刷屏\r\n\r\n违反规则的用户将面临警告或封禁处理。\r\n\r\n如有问题请联系管理员，感谢配合！','warning',0,1,0,1,'2026-01-07 22:00:33','2026-01-07 22:00:33',NULL,NULL),(6,'大家好','欢迎来到哈基聪的小站\n本站主要功能包括：\n\n📝 文章系统\n- 支持Markdown编辑\n- 分类标签管理\n- 文章收藏点赞\n\n💬 社交功能\n- 评论互动\n- 私信聊天\n- 用户关注\n\n📚 学习工具\n- 在线刷题\n- 知识问答\n\n🎨 个性化\n- 个人相册\n- 主题切换\n- 个性签名\n\n欢迎大家积极参与，共同建设我们的技术社区！','info',1,1,0,1,'2026-03-12 21:48:48','2026-03-13 20:02:28','2026-03-12 00:00:00','2026-03-14 00:00:00');
