INSERT INTO `articles` VALUES (1,2,'你好世界','哈喽哈喽',2,'published',58,'2026-01-03 19:12:51','2026-01-03 19:12:51'),(2,2,'Vue3 组合式API完全指南','## 前言\n\nVue3的组合式API是一个重大更新，让我们来深入了解它的使用方法。\n\n## setup函数\n\n```javascript\nimport { ref, reactive, computed } from \'vue\'\n\nexport default {\n  setup() {\n    const count = ref(0)\n    const state = reactive({ name: \'Vue3\' })\n    \n    const double = computed(() => count.value * 2)\n    \n    return { count, state, double }\n  }\n}\n```\n\n## ref vs reactive\n\n- `ref` 用于基本类型\n- `reactive` 用于对象类型\n\n## 生命周期钩子\n\n在setup中使用 `onMounted`、`onUpdated` 等钩子函数。',1,'published',156,'2025-12-10 09:30:00','2025-12-10 09:30:00'),(3,2,'Tailwind CSS 实战技巧','## 为什么选择Tailwind\n\nTailwind CSS是一个功能类优先的CSS框架，让你无需离开HTML就能构建现代网站。\n\n## 常用类名\n\n```html\n<div class=\"flex items-center justify-between p-4 bg-white rounded-lg shadow\">\n  <span class=\"text-lg font-semibold text-gray-800\">标题</span>\n  <button class=\"px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600\">\n    按钮\n  </button>\n</div>\n```\n\n## 响应式设计\n\n使用 `sm:` `md:` `lg:` `xl:` 前缀实现响应式。',1,'published',90,'2025-12-12 14:20:00','2025-12-12 14:20:00'),(4,3,'Spring Boot 3.0 新特性详解','## Spring Boot 3.0 来了\n\n基于Spring Framework 6，要求Java 17+。\n\n## 主要变化\n\n1. **Jakarta EE 9+** - javax包名改为jakarta\n2. **原生镜像支持** - GraalVM原生编译\n3. **可观测性增强** - Micrometer集成\n\n## 代码示例\n\n```java\n@RestController\n@RequestMapping(\"/api\")\npublic class UserController {\n    \n    @GetMapping(\"/users\")\n    public List<User> getUsers() {\n        return userService.findAll();\n    }\n}\n```\n\n## 迁移建议\n\n逐步升级，先升级到2.7再到3.0。',2,'published',234,'2025-12-08 10:00:00','2025-12-08 10:00:00'),(5,3,'MyBatis-Plus 高效开发指南','## 简介\n\nMyBatis-Plus是MyBatis的增强工具，简化开发。\n\n## 快速开始\n\n```java\n@Data\n@TableName(\"user\")\npublic class User {\n    @TableId(type = IdType.AUTO)\n    private Long id;\n    private String name;\n    private Integer age;\n}\n```\n\n## 常用查询\n\n```java\n// Lambda查询\nList<User> users = userMapper.selectList(\n    new LambdaQueryWrapper<User>()\n        .eq(User::getAge, 18)\n        .like(User::getName, \"张\")\n        .orderByDesc(User::getId)\n);\n```\n\n## 分页插件\n\n配置分页拦截器即可使用Page对象。',2,'published',178,'2025-12-15 11:30:00','2025-12-15 11:30:00'),(6,4,'MySQL索引优化实战','## 索引的重要性\n\n合理的索引可以让查询速度提升100倍！\n\n## 索引类型\n\n- 主键索引\n- 唯一索引\n- 普通索引\n- 联合索引\n\n## 最左前缀原则\n\n```sql\n-- 联合索引 (a, b, c)\nSELECT * FROM t WHERE a = 1;           -- 走索引\nSELECT * FROM t WHERE a = 1 AND b = 2; -- 走索引\nSELECT * FROM t WHERE b = 2;           -- 不走索引\n```\n\n## EXPLAIN分析\n\n使用EXPLAIN查看执行计划，关注type、key、rows字段。',3,'published',312,'2025-12-11 16:00:00','2025-12-11 16:00:00'),(7,4,'Redis缓存设计与实践','## 为什么用Redis\n\n- 高性能：10万+ QPS\n- 丰富的数据结构\n- 持久化支持\n\n## 常见使用场景\n\n1. **缓存** - 减轻数据库压力\n2. **分布式锁** - 保证并发安全\n3. **排行榜** - 使用ZSet\n\n## 缓存穿透解决方案\n\n```java\npublic User getUser(Long id) {\n    String key = \"user:\" + id;\n    String cache = redis.get(key);\n    if (cache != null) {\n        return JSON.parseObject(cache, User.class);\n    }\n    User user = userMapper.selectById(id);\n    redis.setex(key, 3600, JSON.toJSONString(user));\n    return user;\n}\n```',3,'published',268,'2025-12-14 09:45:00','2025-12-14 09:45:00'),(8,5,'Docker入门到实践','## 什么是Docker\n\n容器化技术，让应用部署更简单。\n\n## 基本命令\n\n```bash\n# 拉取镜像\ndocker pull nginx\n\n# 运行容器\ndocker run -d -p 80:80 nginx\n\n# 查看容器\ndocker ps\n```\n\n## Dockerfile示例\n\n```dockerfile\nFROM openjdk:17-slim\nWORKDIR /app\nCOPY target/*.jar app.jar\nEXPOSE 8080\nENTRYPOINT [\"java\", \"-jar\", \"app.jar\"]\n```\n\n## Docker Compose\n\n多容器编排利器！',4,'published',198,'2025-12-13 15:00:00','2025-12-13 15:00:00'),(9,6,'Python数据分析入门','## 数据分析三剑客\n\n- NumPy：数值计算\n- Pandas：数据处理\n- Matplotlib：数据可视化\n\n## Pandas基础\n\n```python\nimport pandas as pd\n\n# 读取数据\ndf = pd.read_csv(\'data.csv\')\n\n# 数据清洗\ndf.dropna(inplace=True)\ndf[\'age\'] = df[\'age\'].astype(int)\n\n# 数据分析\nprint(df.describe())\nprint(df.groupby(\'city\')[\'salary\'].mean())\n```\n\n## 可视化\n\n```python\nimport matplotlib.pyplot as plt\n\ndf[\'salary\'].hist(bins=20)\nplt.show()\n```',5,'published',145,'2025-12-16 10:30:00','2025-12-16 10:30:00'),(10,6,'ChatGPT API 开发实战','## 接入OpenAI API\n\n```python\nimport openai\n\nopenai.api_key = \"your-api-key\"\n\nresponse = openai.ChatCompletion.create(\n    model=\"gpt-3.5-turbo\",\n    messages=[\n        {\"role\": \"user\", \"content\": \"你好\"}\n    ]\n)\n\nprint(response.choices[0].message.content)\n```\n\n## 流式输出\n\n使用 `stream=True` 参数实现打字机效果。\n\n## 注意事项\n\n- 控制token数量\n- 处理API限流\n- 敏感内容过滤',5,'published',424,'2025-12-17 14:00:00','2025-12-17 14:00:00'),(11,2,'程序员如何准备技术面试','## 面试准备\n\n### 1. 基础知识\n\n- 数据结构与算法\n- 计算机网络\n- 操作系统\n- 数据库\n\n### 2. 项目经验\n\n准备2-3个有亮点的项目，能够深入讲解。\n\n### 3. 刷题\n\n推荐LeetCode热题100，重点掌握：\n- 数组/字符串\n- 链表\n- 二叉树\n- 动态规划\n\n## 面试技巧\n\n1. STAR法则描述项目\n2. 不会的问题诚实说\n3. 展示学习能力',6,'published',568,'2025-12-18 09:00:00','2025-12-18 09:00:00'),(12,3,'我的2025年终总结','## 回顾这一年\n\n### 技术成长\n\n- 深入学习了Spring Cloud微服务\n- 掌握了K8s容器编排\n- 开始接触AI大模型开发\n\n### 项目经历\n\n完成了3个重要项目的开发和上线。\n\n### 读书清单\n\n- 《深入理解Java虚拟机》\n- 《高性能MySQL》\n- 《凤凰架构》\n\n## 2026展望\n\n继续深耕技术，争取成为架构师！',6,'published',238,'2025-12-28 20:00:00','2025-12-28 20:00:00'),(13,5,'Kubernetes入门指南','## K8s核心概念\n\n- Pod：最小部署单元\n- Service：服务发现\n- Deployment：部署管理\n- ConfigMap/Secret：配置管理\n\n## 常用命令\n\n```bash\nkubectl get pods\nkubectl apply -f deployment.yaml\nkubectl logs pod-name\nkubectl exec -it pod-name -- /bin/bash\n```\n\n## 部署示例\n\n```yaml\napiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: my-app\nspec:\n  replicas: 3\n  selector:\n    matchLabels:\n      app: my-app\n  template:\n    spec:\n      containers:\n      - name: app\n        image: my-app:latest\n```',4,'published',177,'2025-12-20 11:00:00','2025-12-20 11:00:00'),(14,5,'软件工程复习','视图\n1. 用例视图\n描述参与者（用户、外部系统）与系统的交互，体现系统 “做什么”。\n2. 逻辑视图\n分解系统为功能模块，定义模块间的接口和依赖，体现 “如何实现需求”。\n3. 实现视图\n映射逻辑模块到实际代码文件（如 Java 的包、Vue 的组件目录），包含库依赖、编译配置。\n4. 部署视图\n描述服务器、网络设备的分布，以及软件组件（如微服务、数据库）在硬件上的部署位置。\n5. 进程视图\n描述进程、线程的生命周期，以及它们之间的通信方式，解决 “系统如何运行” 的问题。\n\n里氏替换原则（LSP）核心结论：子类对象可以无缝替换父类对象，且不影响程序原有逻辑的正确性。\n\n维护类型\n1. 纠错性维护\n2. 适应性维护\n3. 完善性维护\n4. 预防性维护\n\n软件可维护性的因素：\n软件的可理解性、可测试性、可修改性、可移植性、可重用性\n\n模块耦合度\n1. 内容耦合模块间最紧密的耦合，一个模块直接访问另一个模块的内部数据 / 代码，修改一个模块会直接破坏另一个模块。\n2. 公共耦合多个模块共享同一个全局数据区（如全局变量、公共数据结构），一个模块修改公共区数据会影响所有依赖它的模块。\n3. 控制耦合一个模块向另一个模块传递 “控制信号”（如标志位、开关值），接收方根据该信号调整自身逻辑，耦合度高于数据耦合。\n4. 数据耦合模块间仅通过参数传递简单数据（如基本类型、独立数据结构），是耦合度最低、最理想的耦合方式。\n\n能力成熟度模型（CMM）\n1. 初始级（Level 1）软件过程无规范、全靠个人能力，项目成功与否取决于开发者经验，进度、质量不可控，返工率高。核心特点：混乱、不可预测。\n2. 可重复级（Level 2）建立基础的项目管理流程（如需求管理、计划制定、配置管理），能重复以往成功项目的做法，但仅局限于单个项目，未形成组织级标准。核心特点：单个项目可控，无通用标准。\n3. 已定义级（Level 3）组织层面制定了标准化的软件过程规范（如统一的开发流程、文档模板），所有项目都遵循该标准，过程可文档化、可培训、可复用。核心特点：组织级标准化流程。\n4. 已管理级（Level 4）引入量化管理，用数据（如缺陷率、进度偏差率）监控和控制软件过程，能精准预测项目质量和进度，及时发现偏差并调整。核心特点：数据驱动、量化控制。\n5. 优化级（Level 5）最高级别，组织持续改进过程，通过数据分析、新技术试点、经验总结，不断优化流程，实现持续的过程能力提升。\n\n',1,'published',0,'2026-01-05 18:15:20','2026-01-05 18:15:20'),(15,5,'系统整体架构图','# 系统整体架构图\n\n本文档展示项目的整体技术架构，包括前端、后端、数据库、外部服务等各个组件及其交互关系。\n\n## 目录\n1. [系统整体架构图](#1-系统整体架构图)\n2. [技术架构分层图](#2-技术架构分层图)\n3. [部署架构图](#3-部署架构图)\n4. [数据流架构图](#4-数据流架构图)\n\n---\n\n## 1. 系统整体架构图\n\n### Mermaid架构图（推荐）\n```mermaid\ngraph TB\n    subgraph \"用户层\"\n        U1[Web浏览器]\n        U2[移动端浏览器]\n    end\n    \n    subgraph \"前端层 - Vue3\"\n        V1[聊天界面<br/>Chat.vue]\n        V2[AI助手界面<br/>AiAssistant.vue]\n        V3[视频通话界面<br/>WebRTC组件]\n        V4[管理后台<br/>Admin界面]\n        V5[路由管理<br/>Vue Router]\n        V6[状态管理<br/>Pinia/Vuex]\n    end\n    \n    subgraph \"网关层\"\n        N1[Nginx反向代理]\n        N2[负载均衡]\n        N3[静态资源服务]\n    end\n    \n    subgraph \"应用层 - SpringBoot\"\n        direction TB\n        subgraph \"控制器层\"\n            C1[ChatController<br/>聊天管理]\n            C2[AiAssistantController<br/>AI助手]\n            C3[UserController<br/>用户管理]\n            C4[FileController<br/>文件管理]\n        end\n        \n        subgraph \"业务逻辑层\"\n            S1[ChatService<br/>聊天服务]\n            S2[AiChatService<br/>AI服务]\n            S3[UserService<br/>用户服务]\n            S4[WebSocketServer<br/>实时通信]\n        end\n        \n        subgraph \"数据访问层\"\n            M1[ChatMapper]\n            M2[AiChatMapper]\n            M3[UserMapper]\n            M4[MyBatis-Plus]\n        end\n    end\n    \n    subgraph \"中间件层\"\n        MW1[Redis缓存<br/>会话存储]\n        MW2[WebSocket<br/>实时通信]\n        MW3[Spring AI<br/>AI集成框架]\n    end\n    \n    subgraph \"数据层\"\n        DB1[(MySQL主库<br/>业务数据)]\n        DB2[(MySQL从库<br/>读取优化)]\n    end\n    \n    subgraph \"外部服务\"\n        EXT1[阿里云OSS<br/>文件存储]\n        EXT2[LLM模型<br/>DeepSeek/OpenAI]\n        EXT3[TURN服务器<br/>WebRTC中继]\n        EXT4[STUN服务器<br/>NAT穿透]\n    end\n    \n    %% 连接关系\n    U1 --> N1\n    U2 --> N1\n    N1 --> V1\n    N1 --> V2\n    N1 --> V3\n    N1 --> V4\n    \n    V1 --> C1\n    V2 --> C2\n    V3 --> C1\n    V4 --> C3\n    \n    V1 -.-> MW2\n    V2 -.-> MW2\n    V3 -.-> MW2\n    \n    C1 --> S1\n    C2 --> S2\n    C3 --> S3\n    \n    S1 --> M1\n    S2 --> M2\n    S3 --> M3\n    S4 --> MW1\n    \n    M1 --> M4\n    M2 --> M4\n    M3 --> M4\n    M4 --> DB1\n    M4 --> DB2\n    \n    S2 --> MW3\n    MW3 --> EXT2\n    \n    S1 --> EXT1\n    S3 --> EXT1\n    \n    V3 --> EXT3\n    V3 --> EXT4\n    \n    MW2 --> S4\n```\n\n### PlantUML架构图\n```plantuml\n@startuml 系统整体架构图\n!theme plain\nskinparam backgroundColor #FFFFFF\nskinparam defaultFontName \"Microsoft YaHei\"\n\ntitle 系统整体架构图\n\npackage \"用户层\" {\n    [Web浏览器] as Browser\n    [移动端] as Mobile\n}\n\npackage \"前端层 (Vue3 + Vite)\" {\n    [聊天界面] as ChatUI\n    [AI助手界面] as AIUI\n    [视频通话] as VideoUI\n    [管理后台] as AdminUI\n    [路由管理] as Router\n    [状态管理] as Store\n}\n\npackage \"网关层\" {\n    [Nginx] as Nginx\n    [负载均衡] as LB\n}\n\npackage \"应用层 (SpringBoot)\" {\n    package \"控制器层\" {\n        [ChatController] as ChatCtrl\n        [AiAssistantController] as AiCtrl\n        [UserController] as UserCtrl\n        [FileController] as FileCtrl\n    }\n    \n    package \"服务层\" {\n        [ChatService] as ChatSvc\n        [AiChatService] as AiSvc\n        [UserService] as UserSvc\n        [WebSocketServer] as WSServer\n    }\n    \n    package \"数据访问层\" {\n        [MyBatis-Plus] as MBP\n        [ChatMapper] as ChatMapper\n        [UserMapper] as UserMapper\n    }\n}\n\npackage \"中间件层\" {\n    [Redis缓存] as Redis\n    [WebSocket] as WS\n    [Spring AI] as SpringAI\n}\n\npackage \"数据层\" {\n    database \"MySQL主库\" as MainDB\n    database \"MySQL从库\" as SlaveDB\n}\n\npackage \"外部服务\" {\n    [阿里云OSS] as OSS\n    [LLM模型] as LLM\n    [TURN服务器] as TURN\n    [STUN服务器] as STUN\n}\n\n\' 连接关系\nBrowser --> Nginx\nMobile --> Nginx\nNginx --> ChatUI\nNginx --> AIUI\nNginx --> VideoUI\nNginx --> AdminUI\n\nChatUI --> ChatCtrl\nAIUI --> AiCtrl\nAdminUI --> UserCtrl\nVideoUI --> FileCtrl\n\nChatUI ..> WS\nAIUI ..> WS\nVideoUI ..> WS\n\nChatCtrl --> ChatSvc\nAiCtrl --> AiSvc\nUserCtrl --> UserSvc\n\nChatSvc --> ChatMapper\nAiSvc --> ChatMapper\nUserSvc --> UserMapper\nWSServer --> Redis\n\nChatMapper --> MBP\nUserMapper --> MBP\nMBP --> MainDB\nMBP --> SlaveDB\n\nAiSvc --> SpringAI\nSpringAI --> LLM\n\nChatSvc --> OSS\nUserSvc --> OSS\n\nVideoUI --> TURN\nVideoUI --> STUN\n\nWS --> WSServer\n\n@enduml\n```\n\n---\n\n## 2. 技术架构分层图\n\n### Mermaid分层架构图\n```mermaid\ngraph TD\n    subgraph \"表现层 (Presentation Layer)\"\n        P1[Vue3 + TypeScript]\n        P2[Element Plus UI]\n        P3[Vite构建工具]\n        P4[WebRTC API]\n    end\n    \n    subgraph \"网关层 (Gateway Layer)\"\n        G1[Nginx反向代理]\n        G2[SSL/TLS终端]\n        G3[静态资源服务]\n        G4[负载均衡]\n    end\n    \n    subgraph \"应用层 (Application Layer)\"\n        A1[SpringBoot 3.x]\n        A2[Spring Security]\n        A3[Spring WebSocket]\n        A4[Spring AI]\n    end\n    \n    subgraph \"业务层 (Business Layer)\"\n        B1[聊天业务逻辑]\n        B2[AI对话业务]\n        B3[用户管理业务]\n        B4[文件管理业务]\n        B5[WebRTC信令处理]\n    end\n    \n    subgraph \"数据访问层 (Data Access Layer)\"\n        D1[MyBatis-Plus ORM]\n        D2[Redis Template]\n        D3[连接池管理]\n        D4[事务管理]\n    end\n    \n    subgraph \"数据层 (Data Layer)\"\n        DB1[(MySQL 8.0)]\n        DB2[(Redis 6.x)]\n        DB3[阿里云OSS]\n    end\n    \n    subgraph \"外部服务层 (External Services)\"\n        E1[DeepSeek AI]\n        E2[OpenAI API]\n        E3[TURN/STUN服务器]\n    end\n    \n    P1 --> G1\n    G1 --> A1\n    A1 --> B1\n    B1 --> D1\n    D1 --> DB1\n    \n    A4 --> E1\n    B5 --> E3\n    D2 --> DB2\n    B4 --> DB3\n```\n\n---\n\n## 3. 部署架构图\n\n### Mermaid部署架构图\n```mermaid\ngraph TB\n    subgraph \"用户访问\"\n        U[用户浏览器]\n    end\n    \n    subgraph \"CDN层\"\n        CDN[阿里云CDN<br/>静态资源加速]\n    end\n    \n    subgraph \"负载均衡层\"\n        LB[Nginx负载均衡器<br/>80/443端口]\n    end\n    \n    subgraph \"应用服务器集群\"\n        APP1[应用服务器1<br/>SpringBoot:8080]\n        APP2[应用服务器2<br/>SpringBoot:8080]\n        APP3[应用服务器3<br/>SpringBoot:8080]\n    end\n    \n    subgraph \"数据库集群\"\n        MASTER[(MySQL主库<br/>读写)]\n        SLAVE1[(MySQL从库1<br/>只读)]\n        SLAVE2[(MySQL从库2<br/>只读)]\n    end\n    \n    subgraph \"缓存集群\"\n        REDIS1[Redis主节点]\n        REDIS2[Redis从节点]\n    end\n    \n    subgraph \"文件存储\"\n        OSS[阿里云OSS<br/>对象存储]\n    end\n    \n    subgraph \"外部服务\"\n        AI[AI模型服务<br/>DeepSeek API]\n        TURN[TURN服务器<br/>WebRTC中继]\n    end\n    \n    subgraph \"监控运维\"\n        MON[监控系统<br/>Prometheus+Grafana]\n        LOG[日志系统<br/>ELK Stack]\n    end\n    \n    U --> CDN\n    CDN --> LB\n    LB --> APP1\n    LB --> APP2\n    LB --> APP3\n    \n    APP1 --> MASTER\n    APP2 --> MASTER\n    APP3 --> MASTER\n    \n    APP1 --> SLAVE1\n    APP2 --> SLAVE2\n    APP3 --> SLAVE1\n    \n    APP1 --> REDIS1\n    APP2 --> REDIS1\n    APP3 --> REDIS1\n    \n    REDIS1 --> REDIS2\n    MASTER --> SLAVE1\n    MASTER --> SLAVE2\n    \n    APP1 --> OSS\n    APP2 --> OSS\n    APP3 --> OSS\n    \n    APP1 --> AI\n    APP2 --> AI\n    APP3 --> AI\n    \n    U -.-> TURN\n    \n    APP1 --> MON\n    APP2 --> MON\n    APP3 --> MON\n    \n    APP1 --> LOG\n    APP2 --> LOG\n    APP3 --> LOG\n```\n\n---\n\n## 4. 数据流架构图\n\n### Mermaid数据流图\n```mermaid\ngraph LR\n    subgraph \"数据输入\"\n        I1[用户聊天消息]\n        I2[AI对话请求]\n        I3[文件上传]\n        I4[WebRTC信令]\n    end\n    \n    subgraph \"数据处理\"\n        P1[消息验证与过滤]\n        P2[AI上下文构建]\n        P3[文件格式转换]\n        P4[信令路由]\n    end\n    \n    subgraph \"业务逻辑\"\n        B1[聊天消息分发]\n        B2[AI模型调用]\n        B3[文件存储管理]\n        B4[WebRTC连接管理]\n    end\n    \n    subgraph \"数据存储\"\n        S1[(聊天记录<br/>MySQL)]\n        S2[(AI会话<br/>MySQL)]\n        S3[(用户文件<br/>OSS)]\n        S4[(会话缓存<br/>Redis)]\n    end\n    \n    subgraph \"数据输出\"\n        O1[实时消息推送]\n        O2[AI流式回复]\n        O3[文件下载链接]\n        O4[WebRTC媒体流]\n    end\n    \n    I1 --> P1 --> B1 --> S1 --> O1\n    I2 --> P2 --> B2 --> S2 --> O2\n    I3 --> P3 --> B3 --> S3 --> O3\n    I4 --> P4 --> B4 --> S4 --> O4\n    \n    B2 -.-> S4\n    B1 -.-> S4\n```\n\n---\n\n## 架构特点说明\n\n### 🏗️ 架构优势\n\n1. **微服务化设计**: 模块化的服务架构，易于扩展和维护\n2. **高可用性**: 数据库主从复制，Redis集群，应用服务器集群\n3. **高性能**: CDN加速，Redis缓存，数据库读写分离\n4. **实时性**: WebSocket实现实时通信，SSE实现流式AI回复\n5. **可扩展性**: 水平扩展应用服务器，支持负载均衡\n\n### 🔧 技术栈\n\n**前端技术栈**:\n- Vue3 + TypeScript + Vite\n- Element Plus UI组件库\n- WebRTC音视频通话\n- Pinia状态管理\n\n**后端技术栈**:\n- SpringBoot 3.x + Java 17\n- Spring AI集成框架\n- MyBatis-Plus ORM\n- WebSocket实时通信\n\n**数据存储**:\n- MySQL 8.0 (主从复制)\n- Redis 6.x (缓存集群)\n- 阿里云OSS (文件存储)\n\n**外部服务**:\n- DeepSeek/OpenAI (AI模型)\n- TURN/STUN服务器 (WebRTC)\n\n### 📊 性能指标\n\n- **并发用户**: 支持1000+在线用户\n- **消息延迟**: <100ms实时消息传输\n- **AI响应**: 流式回复，首字延迟<2s\n- **文件上传**: 支持100MB大文件上传\n- **可用性**: 99.9%系统可用性\n\n### 🔒 安全措施\n\n- HTTPS/WSS加密传输\n- JWT Token身份认证\n- SQL注入防护\n- XSS攻击防护\n- 文件类型验证\n- 接口限流保护\n\n这个架构图展示了系统的完整技术架构，为系统的开发、部署和运维提供了清晰的指导。',1,'published',0,'2026-01-07 12:14:24','2026-01-07 12:14:24'),(16,5,'LLM - Google NotebookLM Skill 介绍与实战','<br />\n\n#### 文章目录\n\n* [一、项目概览：一个「非官方」但很能打的 NotebookLM SDK](#_NotebookLM_SDK_17)\n*\n  * [1.1 项目是什么](#11__19)\n* [二、核心能力：把 NotebookLM 的所有按钮都变成 API](#_NotebookLM__API_44)\n*\n  * [2.1 Notebook、数据源、对话、研究、分享：全流程打通](#21_Notebook_48)\n  * [2.2 内容生成：把 Studio 里的所有模板都开放出来](#22__Studio__66)\n  * [2.3 超出网页端的「隐藏技能」](#23__90)\n* [三、三种使用方式：Python API、CLI、Agent 技能](#Python_APICLIAgent__113)\n*\n  * [3.1 CLI：用命令行走完整流程](#31_CLI_121)\n  * [3.1.1 安装和登录](#311__123)\n  * [3.1.2 从「建本 → 加料 → 问答 → 生成 → 下载」一条龙](#312__________144)\n  * [3.2 Python API：写自己的自动化流水线](#32_Python_API_208)\n  * [3.2.1 客户端初始化](#321__212)\n  * [3.2.2 一个简版「自动处理 Notebook」示例](#322__Notebook_229)\n  * [3.3 Agent Skills：交给 AI 编程助手去调用](#33_Agent_Skills_AI__279)\n* [四、典型应用场景：从个人研究到小型内容工厂](#_307)\n*\n  * [4.1 研究自动化：不再手动搬运资料](#41__311)\n  * [4.2 教学与培训：自动生产「课程 + 练习 + 闪卡」](#42______330)\n  * [4.3 企业内知识自动整理：知识库 + 学习包](#43____346)\n* [五、注意事项：非官方 API 的边界与工程实践](#_API__368)\n*\n  * [5.1 兼容性与稳定性](#51__372)\n  * [5.2 安全与合规](#52__392)\n  * [5.3 不要盲目上生产](#53__407)\n* [六、实战建议：如果你现在就想试着用起来](#_420)\n*\n  * [6.1 第一阶段：个人层面的「自动做学习包」](#61__424)\n  * [6.2 第二阶段：项目 / 团队级自动化](#62____434)\n  * [6.3 第三阶段：和 Agent 体系打通](#63__Agent__448)\n* [实操](#_467)\n*\n  * [借助cc安装 notebooklm skill](#cc_notebooklm_skill_469)\n  * [notebooklm login首次登录](#notebooklm_login_608)\n  * [安装状态验证](#_628)\n  * [如何使用 notebooklm 这个skill](#_notebooklm_skill_676)\n  * [使用](#_732)\n* [结语：NotebookLM 的「程序化控制台」](#NotebookLM__862)\n\n<br />\n\n![在这里插入图片描述](http://localhost:9000/blog/crawled/f3766e97-c5d2-49f3-a992-8401ddc8ea05.png)\n\nNotebookLM 出来之后，很多人第一反应是：这东西要是能「编程调用」就爽了。 官方暂时没开放正式 API，但社区已经有人「抠」出了内部接口，封装成了一个可用的 Python SDK 和 CLI，这就是 `notebooklm-py`。\n\n接下来我们就用一篇偏「实战导向」的长文，搞清楚三件事：\n\n1. `notebooklm-py` 到底能做什么，适合用在什么场景\n2. 作为开发者，怎么用 Python/CLI/Agent 三种方式接入\n3. 在能力边界、安全性、工程落地上应该注意什么\n\n*** ** * ** ***\n\n{#_NotebookLM_SDK_17}一、项目概览：一个「非官方」但很能打的 NotebookLM SDK\n-------------------------------------------------------\n\n### {#11__19}1.1 项目是什么\n\n`notebooklm-py` 的定位很直接：Google NotebookLM 的非官方 Python API + CLI 工具集。\n\n* 仓库地址：`https://github.com/teng-lin/notebooklm-py`\n* 语言：100% Python，[MIT 协议](https://github.com/teng-lin/notebooklm-py/blob/main/LICENSE)\n* 最新版本：v0.3.2（2 周前发布），持续更新中\n* 安装方式：`pip install notebooklm-py`，支持额外安装浏览器登录能力 `[browser]`\n\n它的关键点有三个：\n\n* 使用的是 **Google 未公开的内部接口**，完全非官方\n* 接口可能随时变动，所以更适合原型验证、个人项目、研究自动化\n* 在功能上，基本「覆盖 + 超出」了网页版 NotebookLM 能做的事\n\n官方 README 里也明确打了一个大大的 ⚠ 提示：\n\n* 不隶属于 Google\n* 接口可能会失效\n* 重度使用会触发限流\n\n所以它更像是一块「功能很强，但风险自担」的积木： 能省你大量时间，但不建议直接作为关键生产系统的唯一依赖。\n\n*** ** * ** ***\n\n{#_NotebookLM__API_44}二、核心能力：把 NotebookLM 的所有按钮都变成 API\n------------------------------------------------------\n\n从 README 的功能表可以看到，`notebooklm-py` 基本「把网页上能点的东西都做成了接口」，还能多给你一些网页不存在的能力。\n\n### {#21_Notebook_48}2.1 Notebook、数据源、对话、研究、分享：全流程打通\n\n先看它对 NotebookLM 核心对象的覆盖程度：\n\n|    类别    |                                          能力一览                                           |\n|----------|-----------------------------------------------------------------------------------------|\n| Notebook | 创建、列出、重命名、删除                                                                            |\n| 数据源      | 支持 URL、YouTube、文件（PDF / 文本 / Markdown / Word / 音视频 / 图片）、Google Drive、粘贴文本；刷新、获取指南、获取全文 |\n| 对话       | 向 Notebook 提问、查看对话历史、自定义 persona                                                        |\n| 研究功能     | 调用 Web / Drive 研究代理，支持「快速 / 深度」模式，并自动导入结果到 notebook                                     |\n| 分享       | 创建公开 / 私有链接，设置用户权限（查看者 / 编辑者），控制访问级别                                                    |\n\n这些能力意味着，你可以用代码做一件非常常见但以前全靠手动的事：\n> 批量：创建一个 Notebook → 导入一堆论文 / 视频 / 链接 → 跑几轮 Web 研究 → 整理输出为报告 / 思维导图 / 问答 → 导出给团队。\n\n以前你要在浏览器里点半天，现在只需要写几百行脚本就能完全自动化。\n\n### {#22__Studio__66}2.2 内容生成：把 Studio 里的所有模板都开放出来\n\nNotebookLM 的 Studio 支持各种「产物」生成：音频、视频、幻灯片、信息图、测验、闪卡、报告、表格、思维导图等。\n\n`notebooklm-py` 直接把这些都做成了 API，并且保留了大量参数选项：\n\n|  类型  |            可配置项（部分）             |          导出格式          |\n|------|---------------------------------|------------------------|\n| 音频概览 | 4 种风格（深度、简要、点评、辩论）、3 种长度、50+ 语言 | MP3 / MP4              |\n| 视频概览 | 2 种内容格式、9 种视觉风格（经典、白板、卡通、动漫等）   | MP4                    |\n| 幻灯片  | 详细版 / 演讲者版、可控页数                 | PDF                    |\n| 信息图  | 3 种方向、3 种信息密度                   | PNG                    |\n| 测验   | 题量、难度可调                         | JSON / Markdown / HTML |\n| 闪卡   | 题量、难度可调                         | JSON / Markdown / HTML |\n| 报告   | 模板（简报、学习指南、博客文）或自定义说明           | Markdown               |\n| 数据表  | 用自然语言描述字段结构                     | CSV                    |\n| 思维导图 | 自动构建层级结构                        | JSON                   |\n\n对开发者来说，这些能力最直接的用途是：\n\n* 做 **内容流水线**：从原始资料到播客 / 视频 / PPT / 练习题 / 知识卡片，一次性跑完\n* 做 **学习系统**：定期把新文档喂进去，自动生成学习包（讲解 + 测验 + 闪卡 + 思维导图）\n* 做 **知识可视化**：拿到思维导图的 JSON 后，用你自己的可视化方案渲染\n\n### {#23__90}2.3 超出网页端的「隐藏技能」\n\n有一块是网页端完全没暴露、但在 API 里非常有价值的能力：\n\n* 批量下载：同类产物一次性全部打包拉下来\n* 测验 / 闪卡导出：不仅在网页里点点做题，还能拿到结构化 JSON、Markdown、HTML\n* 思维导图 JSON：拿到完整树形结构，方便你做二次可视化或分析\n* 数据表 CSV：和数据分析 / BI 工具直接对接\n* 数据源全文访问：直接拿到 NotebookLM 已索引的文本内容\n* 分享权限编程管理：可以在脚本里批量调整 Notebook 的分享策略\n\n一个很典型的例子：  \n\n你做了一个企业内部知识学习系统，想用 NotebookLM 帮你生成测验，但不想所有人都跑到 NotebookLM 网页上做题。  \n\n用 `notebooklm-py` 可以这样玩：\n\n* 用 NotebookLM 生成测验 → 导出 JSON\n* 把 JSON 接到你自己的小程序 / Web 前端 → 员工在内部系统里完成答题\n* 回答记录和成绩全走你自己的后端逻辑\n\n这就是「用 NotebookLM 做生成，但交互和数据资产还在自己手里」。\n\n*** ** * ** ***\n\n{#Python_APICLIAgent__113}三、三种使用方式：Python API、CLI、Agent 技能\n----------------------------------------------------------\n\n项目作者把使用方式分成了三块，分别对不同人群友好。\n\n* Python API：写代码，做集成 / 异步流程 / 自定义管线\n* CLI：写脚本、一次性任务、CI 自动化\n* Agent Skills：交给你的 AI 编程助手去调用\n\n### {#31_CLI_121}3.1 CLI：用命令行走完整流程\n\n### {#311__123}3.1.1 安装和登录\n\n安装很简单：\n\n```prism language-bash\n# 基础安装\npip install notebooklm-py\n\n# 第一次登录建议带浏览器支持\npip install \"notebooklm-py[browser]\"\nplaywright install chromium\n```\n\n然后登录 NotebookLM 账号（会自动打开浏览器）：\n\n```prism language-bash\nnotebooklm login\n```\n\n登录信息会持久化存储，后面 CLI 和 Python API 都能复用。\n\n### {#312__________144}3.1.2 从「建本 → 加料 → 问答 → 生成 → 下载」一条龙\n\nREADME 给了一个完整的命令行示例，我们拆开看一下：「一个研究 Notebook 的生命周期」：\n\n1. 创建 Notebook\n\n```prism language-bash\nnotebooklm create \"My Research\"\nnotebooklm use\n```\n\n这里 `use` 会选择当前活跃的 Notebook，后续命令默认作用在它上面。\n\n2. 添加数据源\n\n```prism language-bash\nnotebooklm source add \"https://en.wikipedia.org/wiki/Artificial_intelligence\"\nnotebooklm source add \"./paper.pdf\"\n```\n\n一个 URL 一个本地 PDF，很符合真实场景：官方资料 + 论文。\n\n3. 用资料对话\n\n```prism language-bash\nnotebooklm ask \"What are the key themes?\"\n```\n\nNotebookLM 会基于当前 Notebook 的所有数据源来回答。\n\n4. 生成各种内容\n\n```prism language-bash\nnotebooklm generate audio \"make it engaging\" --wait\nnotebooklm generate video --style whiteboard --wait\nnotebooklm generate quiz --difficulty hard\nnotebooklm generate flashcards --quantity more\nnotebooklm generate slide-deck\nnotebooklm generate infographic --orientation portrait\nnotebooklm generate mind-map\nnotebooklm generate data-table \"compare key concepts\"\n```\n\n这里有几个要点：\n\n* 大多命令支持附加说明，比如「讲得生动一点」「对比核心概念」\n* `--wait` 表示阻塞到任务完成（否则需要自己轮询）\n\n5. 下载产物\n\n```prism language-bash\nnotebooklm download audio ./podcast.mp3\nnotebooklm download video ./overview.mp4\nnotebooklm download quiz --format markdown ./quiz.md\nnotebooklm download flashcards --format json ./cards.json\nnotebooklm download slide-deck ./slides.pdf\nnotebooklm download mind-map ./mindmap.json\nnotebooklm download data-table ./data.csv\n```\n\n一条命令一个文件，格式也能选（比如测验 / 闪卡可以是 Markdown/HTML/JSON）。\n\n这一整串组合起来，就是一个最简单的「自动做学习包」的脚本骨架。\n\n### {#32_Python_API_208}3.2 Python API：写自己的自动化流水线\n\n如果你想更细粒度地控制 NotebookLM，或者要集成到服务端 / Job 流水线，就更适合用 Python API。\n\n### {#321__212}3.2.1 客户端初始化\n\n典型写法：使用存储中已有的登录信息创建客户端。\n\n```prism language-python\nimport asyncio\nfrom notebooklm import NotebookLMClient\n\nasync def main():\n    async with await NotebookLMClient.from_storage() as client:\n        ...\n        \nasyncio.run(main())\n```\n\n`from_storage()` 会复用你之前通过 CLI 登录时保存的凭证，因此建议先跑一遍 `notebooklm login`。\n\n### {#322__Notebook_229}3.2.2 一个简版「自动处理 Notebook」示例\n\nREADME 提供了一个涵盖创建 Notebook、添加数据源、问答、生成音频 / 测验 / 思维导图、下载结果的示例，我们把逻辑拆一下：\n\n```prism language-python\nasync with await NotebookLMClient.from_storage() as client:\n    # 1. 创建 Notebook\n    nb = await client.notebooks.create(\"Research\")\n\n    # 2. 添加 URL 数据源，并等待处理完成\n    await client.sources.add_url(nb.id, \"https://example.com\", wait=True)\n\n    # 3. 基于资料提问\n    result = await client.chat.ask(nb.id, \"Summarize this\")\n    print(result.answer)\n\n    # 4. 生成音频讲解\n    status = await client.artifacts.generate_audio(\n        nb.id,\n        instructions=\"make it fun\",\n    )\n    await client.artifacts.wait_for_completion(nb.id, status.task_id)\n    await client.artifacts.download_audio(nb.id, \"podcast.mp3\")\n\n    # 5. 生成测验并导出 JSON\n    status = await client.artifacts.generate_quiz(nb.id)\n    await client.artifacts.wait_for_completion(nb.id, status.task_id)\n    await client.artifacts.download_quiz(\n        nb.id,\n        \"quiz.json\",\n        output_format=\"json\",\n    )\n\n    # 6. 生成思维导图并导出 JSON\n    result = await client.artifacts.generate_mind_map(nb.id)\n    await client.artifacts.download_mind_map(nb.id, \"mindmap.json\")\n```\n\n这里面有几个工程上值得注意的小点：\n\n* API 设计是 **异步** 的，用起来比较适合 I/O 密集的批处理场景\n* 生成类操作基本都走「提交任务 → 等待完成 → 下载结果」三段式\n* 产物下载都是显式调用，方便你控制文件命名和存储路径\n\n基于这一套，你很容易拓展出一些更实际的东西：\n\n* 批量处理多个 Notebook（比如一个项目一个 Notebook）\n* 根据生成的测验 / 思维导图再做一些内部加工\n* 用调度系统（如 Airflow）按天 / 按周自动跑一遍「新资料 → 新内容包」\n\n### {#33_Agent_Skills_AI__279}3.3 Agent Skills：交给 AI 编程助手去调用\n\n还有一类用户是：你常用 Claude Code 这类 AI 编程助手，希望直接对它说「帮我生成一个播客，并且下载下来」。\n\n`notebooklm-py` 内置了专门的 Agent 技能支持：\n\n1. 先安装技能\n\n```prism language-bash\nnotebooklm skill install\n```\n\n2. 然后在 Claude Code 里直接用自然语言：\n\n* 「Create a podcast about quantum computing」\n* 「Download the quiz as markdown」\n* 「/notebooklm generate video」\n\n从开发者视角看，这其实是把 NotebookLM 做成了「二级工具」：\n\n* 你的人 → Claude / 其它 Agent\n* Claude → `notebooklm-py`\n* `notebooklm-py` → NotebookLM\n\n适合用在：你不想自己写太细的脚本，更希望把意图交给 Agent 处理。\n\n*** ** * ** ***\n\n{#_307}四、典型应用场景：从个人研究到小型内容工厂\n----------------------------\n\n结合项目给出的能力，我们可以抽象出几类比较典型的应用方式。\n\n### {#41__311}4.1 研究自动化：不再手动搬运资料\n\n目标用户：科研人员、分析师、咨询顾问、自媒体作者。\n\n流程可以设计成这样：\n\n1. 按主题新建 Notebook，例如「GenAI 在医疗行业的应用」\n2. 自动抓取一批公开资料：官方白皮书、论文、新闻、报告 PDF\n3. 调用 Web / Drive 研究代理做补充检索\n4. 自动生成：\n   * 深度音频讲解\n   * 结构化报告（简报版 / 学习指南）\n   * 比较关键概念的数据表\n   * 带层级的思维导图\n5. 导出 Markdown / CSV / JSON，接入你自己的写作工具链\n\n`notebooklm-py` 能帮你的点在于：  \n\n你不再需要每次打开 NotebookLM 网站、点击导出、复制粘贴，整个过程都能脚本化。\n\n### {#42______330}4.2 教学与培训：自动生产「课程 + 练习 + 闪卡」\n\n目标用户：教育工作者、企业内部培训负责人。\n\n设计思路可以是：\n\n* 每一个课程 / 模块建一个 Notebook\n* 喂入若干资料：教材章节 PDF、讲义、参考视频、补充阅读链接\n* 用 API 一次性生成：\n  * 面向学生的讲解音频 / 视频\n  * 课堂 PPT 草稿（幻灯片 PDF）\n  * 测验题（JSON，方便导入到你自己的考试系统）\n  * 闪卡集合（HTML/Markdown，用于记忆）\n\n对你来说，NotebookLM 的作用从「老师手动用的工具」，升级成了「教学内容流水线里的一个生成模块」。\n\n### {#43____346}4.3 企业内知识自动整理：知识库 + 学习包\n\n目标用户：有内部知识库、且需要持续培训员工的企业技术 / HR 团队。\n\n结合 Google Drive / 文档系统，你可以：\n\n1. 定期把新文档（技术方案、SOP、产品说明）同步到 NotebookLM\n2. 自动生成：\n   * 入门学习包（音频 + PPT + 报告）\n   * 新员工测验题 + 闪卡\n3. 把导出的文件接入内部门户、学习平台或机器人问答系统\n\n重点是：流程可完全自动触发，比如：\n\n* 每周扫描一个「新文档」文件夹\n* 有新增就创建 / 更新对应 Notebook\n* 生成更新后的内容包并通知相关员工\n\n`notebooklm-py` 在这里更像是一个「智能文档加工器」。\n\n*** ** * ** ***\n\n{#_API__368}五、注意事项：非官方 API 的边界与工程实践\n-----------------------------------\n\n能力很强，但坑也要提前说清楚。\n\n### {#51__372}5.1 兼容性与稳定性\n\n项目自己写得很直白：\n\n* 使用的是 Google 未公开的内部接口\n* Google 随时可能调整路径 / 协议 / 风控策略\n* 大量并发调用可能触发限流、甚至账号风控\n\n官方文档里有专门的「API Stability」说明，建议你在用之前至少扫一眼：\n\n* 哪些能力相对稳定\n* 哪些功能是在「试验性」阶段\n* 版本号策略和变更说明\n\n实际工程中比较稳妥的做法是：\n\n* 把 `notebooklm-py` 封装在你自己的一层服务里，不要在各个业务散落使用\n* 在关键调用前后加重试和错误分类处理\n* 跟随 `CHANGELOG` 和 Release 节奏做版本管理\n\n### {#52__392}5.2 安全与合规\n\n项目提供了专门的 Security 文档，说明了它如何处理凭证和安全问题。\n\n你在企业内部使用时，最好注意：\n\n* 不要把登录用的 Cookie / Token 直接硬编码到代码仓库\n* 生产环境可以考虑用专门的服务账号 / 限权账号\n* 对日志做脱敏（避免把完整请求 / 响应内容打到日志里）\n\n尤其是在接入敏感数据（如内部文档、客户信息）时，要清楚：\n\n* NotebookLM 本身是云端服务，你需要遵守企业的合规要求\n* `notebooklm-py` 只是调用方式的变化，不会改变底层数据流向\n\n### {#53__407}5.3 不要盲目上生产\n\n综合项目给出的风险提示，一个比较务实的态度是：\n\n* 凡是 **用户体验敏感** 的前台功能，用 `notebooklm-py` 做辅助，保留手工兜底方案\n* 凡是 **内部效率工具 / 非关键流程**，可以大胆一些\n* 关键核心业务的自动化，最好设计成「可回滚到人肉操作」的模式\n\n换句话说：  \n\n把它当成一个非常好用的「外挂」，而不是「基建」。\n\n*** ** * ** ***\n\n{#_420}六、实战建议：如果你现在就想试着用起来\n--------------------------\n\n最后，我们给一个简单的「分层落地路线」，方便你按阶段尝试。\n\n### {#61__424}6.1 第一阶段：个人层面的「自动做学习包」\n\n目标：先服务好你自己。\n\n* 步骤 1：用 CLI 跑通「建本 → 加料 → 问答 → 生成 → 下载」的流程\n* 步骤 2：写一个简单的 shell / Python 脚本，把你最近在看的几篇论文 / 文档做成播客 + PPT + 测验\n* 步骤 3：把测验 / 闪卡导出的 JSON，接到一个简单的前端小页面里做练习\n\n这阶段重点是熟悉命令和参数，理解 NotebookLM 能帮你做什么、做得怎么样。\n\n### {#62____434}6.2 第二阶段：项目 / 团队级自动化\n\n目标：把它变成你团队的「文档加工器」。\n\n* 选一个相对独立的项目，例如「某产品的内部培训资料」\n* 约定一个资料存放的文件夹（本地 / Drive）\n* 写一个定时任务：\n  * 检测文件变更\n  * 自动同步到 Notebook\n  * 生成一整套内容（报告 + 幻灯片 + 测验 + 闪卡）\n* 把产物放到一个统一的地方（Git 仓库、内网盘、学习平台）\n\n这一步你会开始关注版本、错误处理、以及生成质量的稳定性。\n\n### {#63__Agent__448}6.3 第三阶段：和 Agent 体系打通\n\n目标：你只负责提需求，Agent 负责调 `notebooklm-py` 干活。\n\n* 如果你在用 Claude Code，可以直接安装它的技能，然后：\n  * 让 Claude 根据你的命令自动选 Notebook、生成指定内容、下载到某个路径\n  * 把 `notebooklm-py` 变成 Agent 的一个「工具插件」\n* 如果你有自己的多 Agent 系统，也可以参考文档里「RPC Development / RPC Reference」，按同样思路把 NotebookLM 抽象成一个工具节点\n\n这一步的核心价值是：  \n\n你不再需要记每一个 CLI 命令 / API 调用，只要告诉 Agent 你的意图，让它自己规划调用顺序。\n\n*** ** * ** ***\n\n{#_467}实操\n---------\n\n### {#cc_notebooklm_skill_469}借助cc安装 notebooklm skill\n\n```prism language-bash\n \n❯ 帮我安装这个Claude skill 地址是 https://github.com/teng-lin/notebooklm-py \n\n⏺ 我来帮你安装这个 Claude skill。首先让我获取这个仓库的信息。\n\n⏺ fetch - fetch (MCP)(url: \"https://github.com/teng-lin/notebooklm-py\", max_length: 10000)\n  ⎿  Error: Command \'[\'node\', \'ExtractArticle.js\', \'-i\', \'/var/folders/3n/gbt3p39s5pdc4l55js62gxnm0000gn/T/readabilipyy5u5yqal\', \'-o\', \n     \'/var/folders/3n/gbt3p39s5pdc4l55js62gxnm0000gn/T/readabilipyy5u5yqal.json\']\' returned non-zero exit status 1.\n\n⏺ fetch - fetch (MCP)(url: \"https://raw.githubusercontent.com/teng-lin/notebooklm-py/main/README.md\", max_length: 10000)\n  ⎿  Content type text/plain; charset=utf-8 cannot be simplified to markdown, but here is the raw content:                                                                                                  \n     Contents of https://raw.githubusercontent.com/teng-lin/notebooklm-py/main/README.md:\n     # notebooklm-py\n     ... +218 lines (ctrl+o to expand)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ 这是一个 Google NotebookLM 的 Python API 工具，支持 Claude Code skills。让我查看一下如何安装这个 skill。\n\n⏺ fetch - fetch (MCP)(max_length: 15000, url: \"https://raw.githubusercontent.com/teng-lin/notebooklm-py/main/docs/cli-reference.md\")\n  ⎿  Content type text/plain; charset=utf-8 cannot be simplified to markdown, but here is the raw content:                                                                                                  \n     Contents of https://raw.githubusercontent.com/teng-lin/notebooklm-py/main/docs/cli-reference.md:\n     # CLI Reference\n     ... +359 lines (ctrl+o to expand)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ 我找到了安装方法。根据文档，安装这个 Claude skill 需要两步：\n\n  1. 首先安装 notebooklm-py Python 包\n  2. 然后运行 notebooklm skill install 命令\n\n  让我帮你执行这些步骤：\n\n⏺ Bash(pip install \"notebooklm-py[browser]\")\n  ⎿  Error: Exit code 127\n     (eval):1: command not found: pip\n\n⏺ Bash(pip3 install \"notebooklm-py[browser]\")\n  ⎿  Defaulting to user installation because normal site-packages is not writeable\n     Collecting notebooklm-py[browser]\n       Downloading notebooklm_py-0.1.1-py3-none-any.whl.metadata (7.9 kB)\n     ... +67 lines (ctrl+o to expand)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ 包安装成功了。现在让我安装 Playwright 浏览器并安装 Claude skill：\n\n⏺ Bash(/Users/artisan/Library/Python/3.9/bin/playwright install chromium) timeout: 3m 0s\n  ⎿  Downloading Chrome for Testing 145.0.7632.6 (playwright chromium v1208) from https://cdn.playwright.dev/chrome-for-testing-public/145.0.7632.6/mac-arm64/chrome-mac-arm64.zip\n     |                                                                                |   0% of 162.3 MiB\n     |■■■■■■■■                                                                        |  10% of 162.3 MiB\n     ... +30 lines (ctrl+o to expand)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ Bash(/Users/artisan/Library/Python/3.9/bin/notebooklm skill install)\n  ⎿  Error: Exit code 1\n     Traceback (most recent call last):\n       File \"/Users/artisan/Library/Python/3.9/bin/notebooklm\", line 3, in <module>\n         from notebooklm.notebooklm_cli import main\n       File \"/Users/artisan/Library/Python/3.9/lib/python/site-packages/notebooklm/notebooklm_cli.py\", line 34, in <module>\n         from .cli import (\n       File \"/Users/artisan/Library/Python/3.9/lib/python/site-packages/notebooklm/cli/__init__.py\", line 19, in <module>\n         from .source import source\n       File \"/Users/artisan/Library/Python/3.9/lib/python/site-packages/notebooklm/cli/source.py\", line 23, in <module>\n         from .helpers import (\n     ... +3 lines (ctrl+o to see all)\n\n⏺ 这个包需要 Python 3.10+，但你的系统默认是 Python 3.9。让我检查一下是否有更高版本的 Python：\n\n⏺ Bash(which python3.10 python3.11 python3.12 python3.13 2>/dev/null || brew list | grep python)\n  ⎿  /opt/homebrew/bin/python3.10 \n     python3.11 not found\n     python3.12 not found\n     ... +3 lines (ctrl+o to expand)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ 你有 Python 3.10 和 3.13。让我用 Python 3.13 重新安装：\n\n⏺ Bash(/opt/homebrew/bin/python3.13 -m pip install \"notebooklm-py[browser]\")\n  ⎿  Error: Exit code 1\n     error: externally-managed-environment\n\n     × This environment is externally managed\n     ╰─> To install Python packages system-wide, try brew install\n         xyz, where xyz is the package you are trying to\n         install.\n         \n         If you wish to install a Python library that isn\'t in Homebrew,\n         use a virtual environment:\n     ... +24 lines (ctrl+o to see all)\n\n⏺ 让我使用 pipx 来安装：\n\n⏺ Bash(which pipx || brew install pipx)\n  ⎿  pipx not found                                                                                              \n     ==> Fetching downloads for: pipx\n     ==> Installing dependencies for pipx: ca-certificates, openssl@3, readline, sqlite, xz, zstd and python@3.14\n     ... +202 lines (ctrl+o to expand)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ Bash(pipx install \"notebooklm-py[browser]\")\n  ⎿    installed package notebooklm-py 0.3.2, installed using Python 3.14.3\n       These apps are now globally available\n         - notebooklm\n     ... +5 lines (ctrl+o to expand)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ Bash(notebooklm skill install)\n  ⎿  Installed NotebookLM skill to /Users/artisan/.claude/skills/notebooklm/SKILL.md\n       Version: 0.3.2\n     ... +2 lines (ctrl+o to expand)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ 安装成功了。让我验证一下安装状态：\n\n⏺ Bash(notebooklm skill status)\n  ⎿  Installed at /Users/artisan/.claude/skills/notebooklm/SKILL.md\n       Skill version: 0.3.2\n       CLI version:   0.3.2\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ NotebookLM skill 已成功安装。以下是安装总结：\n\n  已完成的步骤：\n  1. 使用 pipx 安装了 notebooklm-py[browser] v0.3.2\n  2. 安装了 Playwright Chromium 浏览器\n  3. 安装了 Claude Code skill 到 ~/.claude/skills/notebooklm/SKILL.md\n\n  使用方法：\n  - 在 Claude Code 中使用 /notebooklm 命令\n  - 或者用自然语言，比如 \"create a podcast about X\"\n\n  首次使用前需要登录 Google：\n  notebooklm login\n\n  这会打开浏览器让你登录 Google 账号来授权访问 NotebookLM。\n```\n\n### {#notebooklm_login_608}notebooklm login首次登录\n\n首次登陆 ,执行 notebooklm login 会自动打开浏览器，输入自己的账号\n\n```prism language-bash\nartisan@ % notebooklm login\nOpening browser for Google login...\nUsing persistent profile: /Users/artisan/.notebooklm/browser_profile\n\nInstructions:\n1. Complete the Google login in the browser window\n2. Wait until you see the NotebookLM homepage\n3. Press ENTER here to save and close\n\n[Press ENTER when logged in] \n\nAuthentication saved to: /Users/artisan/.notebooklm/storage_state.json\n```\n\n### {#_628}安装状态验证\n\n回到cc中，验证下状态\n\n```prism language-c\n❯ notebooklm  list \n\n⏺ Bash(notebooklm list)\n  ⎿                                     Notebooks                                    \n     ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━┳━━━━━━━━━━━━━━━━━━━━━━━━━━━┳━━━━━━━━┳━━━━━━━━━━━━┓\n     ┃ ID                         ┃ Title                     ┃ Owner  ┃ Created    ┃\n     ... +30 lines (ctrl+o to expand)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ 登录成功！你的 NotebookLM 账号已经认证，可以看到你有 13 个笔记本。\n\n  现在你可以使用 NotebookLM 的所有功能了，比如：\n  - 创建新笔记本：notebooklm create \"标题\"\n  - 添加资料来源：notebooklm source add \"URL或文件\"\n  - 生成播客：notebooklm generate audio\n  - 提问：notebooklm ask \"问题\"\n\n  需要我帮你做什么操作吗？\n```\n\n```prism language-bash\n❯ 这个notebooklm的skill是全局的吗？ \n\n⏺ 是的，这个 skill 是全局安装的。\n\n  它被安装到了 ~/.claude/skills/notebooklm/SKILL.md，这个目录是 Claude Code 的全局 skills 目录，所以在任何项目中都可以使用 /notebooklm 命令或相关功能。\n\n  你可以验证：\n\n  notebooklm skill status\n\n  会显示：\n  Installed at /Users/artisan/.claude/skills/notebooklm/SKILL.md\n    Skill version: 0.3.2\n    CLI version:   0.3.2\n\n  这意味着无论你在哪个项目目录下使用 Claude Code，都可以直接使用 NotebookLM 功能。\n```\n\n### {#_notebooklm_skill_676}如何使用 notebooklm 这个skill\n\n```prism language-bash\n❯ 如何使用 notebooklm 这个skill \n\n⏺ NotebookLM 是一个可以让你通过命令行操作 Google NotebookLM 的工具。以下是主要使用方式：\n\n  基本流程\n\n  1. 首次使用需要登录认证：\n  notebooklm login          # 会打开浏览器进行 Google OAuth 登录\n  notebooklm list           # 验证登录是否成功\n\n  2. 创建笔记本并添加资料：\n  notebooklm create \"我的研究\"              # 创建笔记本\n  notebooklm source add \"https://...\"       # 添加网页\n  notebooklm source add ./document.pdf      # 添加本地文件\n  notebooklm source add \"https://youtube.com/...\"  # 添加 YouTube 视频\n\n  3. 与资料对话：\n  notebooklm ask \"总结一下主要内容\"\n  notebooklm ask \"这篇文章的核心观点是什么？\"\n\n  4. 生成内容（需要确认）：\n  notebooklm generate audio \"用轻松的方式讲解\"   # 生成播客\n  notebooklm generate video \"简要说明概念\"       # 生成视频\n  notebooklm generate quiz                       # 生成测验\n  notebooklm generate flashcards                 # 生成闪卡\n\n  5. 下载生成的内容：\n  notebooklm download audio ./podcast.mp3\n  notebooklm download video ./video.mp4\n  notebooklm download quiz ./quiz.md --format markdown\n\n  常用场景\n  ┌──────────┬────────────────────────────────────────────────┐\n  │   场景   │                      说明                      │\n  ├──────────┼────────────────────────────────────────────────┤\n  │ 研究总结 │ 添加多个 URL/文档，让 AI 帮你总结和分析        │\n  ├──────────┼────────────────────────────────────────────────┤\n  │ 生成播客 │ 把资料转成两人对话风格的音频                   │\n  ├──────────┼────────────────────────────────────────────────┤\n  │ 学习辅助 │ 生成测验和闪卡帮助记忆                         │\n  ├──────────┼────────────────────────────────────────────────┤\n  │ 深度研究 │ 用 source add-research \"主题\" 自动搜索网络资料 │\n  └──────────┴────────────────────────────────────────────────┘\n  设置中文输出\n\n  notebooklm language set zh_Hans   # 设置为简体中文\n\n  需要我帮你执行具体操作吗？比如检查认证状态或创建一个新笔记本？\n```\n\n### {#_732}使用\n\n```prism language-bash\n ❯ 请调用notebooklm为这个工程生成一个PPT，用于介绍技术实现，详细一些 \n\n⏺ 我来为这个 UOM 项目创建一个 NotebookLM 笔记本并生成技术介绍 PPT。首先让我收集项目的关键技术文档。\n\n⏺ Explore(Explore UOM codebase structure)\n  ⎿  Done (37 tool uses · 66.3k tokens · 4m 54s)                                                                                                                                                            \n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ 我已经收集了项目的详细技术信息。现在让我创建一个 NotebookLM 笔记本，添加这些技术文档作为来源，然后生成 PPT。\n\n⏺ Bash(notebooklm create \"UOM 统一运维管理平台 - 技术架构介绍\")\n  ⎿  Created notebook: 7d8c9378-a0c5-4579-91af-c6047bd13b82 - UOM 统一运维管理平台 -\n     技术架构介绍\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ Bash(notebooklm use 7d8c9378-a0c5-4579-91af-c6047bd13b82)\n  ⎿  ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━┳━━━━━━━━━━━━━━━━━━━━━━━━━━━━┳━━━━━━━┳━━━━━━━━━━━━┓\n     ┃ ID                         ┃ Title                      ┃ Owner ┃ Created    ┃\n     ┡━━━━━━━━━━━━━━━━━━━━━━━━━━━━╇━━━━━━━━━━━━━━━━━━━━━━━━━━━━╇━━━━━━━╇━━━━━━━━━━━━┩\n     ... +3 lines (ctrl+o to expand)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ 现在我需要创建一份详细的技术文档作为 NotebookLM 的来源。让我先把技术概要写入一个临时文件，然后上传到 NotebookLM。\n\n⏺ Write(/tmp/uom-tech-overview.md)\n  ⎿  Wrote 505 lines to ../../../../tmp/uom-tech-overview.md                                                                                                                     \n     # UOM 统一运维管理平台 - 技术架构文档\n     ## 一、项目概述\n     **项目名称**: UOM (Unify Online Management) - 统一在线运维中心\n     **版本**: 2.8.12\n     **架构模式**: 两层分布式架构（Server + Agent）\n     **定位**: 企业级统一运维管理平台，支持集群管理、节点运维、应用部署和生命周期管理\n     UOM 是一个功能完整的 DevOps 运维管理平台，采用 Java + Vue 技术栈开发，通过 Server-Agent 两层架构实现对分布式服务器集群的统一管理。系统支持节点监控、应用部署、脚本执行、SSH\n     远程终端、告警通知等企业级运维功能。\n     ... +495 lines (ctrl+o to expand)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ Bash(notebooklm source add /tmp/uom-tech-overview.md) timeout: 1m 0s\n  ⎿  Added source: b567aee7-0ac0-4e04-b1c2-511161c6e4c6\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ Bash(notebooklm source add /Volumes/artisan/code/uom2026/CLAUDE.md) timeout: 1m 0s\n  ⎿  Added source: 2ca9f3c8-22a5-476e-8ddc-7a6babd20531\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ Bash(notebooklm source list)\n  ⎿                  Sources in 7d8c9378-a0c5-4579-91af-c6047bd13b82                 \n     ┏━━━━━━━━━━━━━━━━━━┳━━━━━━━━━━━━━━━━━━┳━━━━━━━━━━━━━┳━━━━━━━━━━━━━━━━━┳━━━━━━━━┓\n     ┃ ID               ┃ Title            ┃ Type        ┃ Created         ┃ Status ┃\n     ... +6 lines (ctrl+o to expand)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ 来源已准备就绪。现在让我设置中文语言并生成详细的 PPT。\n\n⏺ Bash(notebooklm language set zh_Hans)\n  ⎿  ⚠️  This is a GLOBAL setting that affects all notebooks.\n\n     Language set to: zh_Hans (中文（简体）)\n     (synced to server)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ 现在生成详细的 Slide Deck（PPT）。这是一个长时间运行的操作，需要你确认是否继续。\n                                                                                        \n⏺ User answered Claude\'s questions:\n  ⎿  · 是否开始生成 UOM 技术架构介绍 PPT？生成过程可能需要 5-15 分钟。 → 开始生成 (推荐)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ Bash(notebooklm generate slide-deck \"请生成一份详细的 UOM 统一运维管理平台技术架构介绍 PPT，包含以下内容：\n      1. 项目概述和定位...)\n  ⎿  {                                                   \n       \"task_id\": \"d4c19bff-a416-467f-ac03-bddf6bd9114f\",\n       \"status\": \"pending\"\n     }\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ PPT 生成任务已启动。我会在后台监控生成进度，完成后自动下载。\n\n⏺ Task(Wait for PPT and download)\n  ⎿  Backgrounded agent (↓ to manage · ctrl+o to expand)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ PPT 正在后台生成中，任务 ID: d4c19bff-a416-467f-ac03-bddf6bd9114f\n\n  后台代理正在等待生成完成，完成后会自动下载到 /Volumes/artisan/code/uom2026/UOM技术架构介绍.pdf。\n\n  生成过程通常需要 5-15 分钟。你可以继续做其他事情，我会在完成后通知你。\n\n  要查看进度，可以运行：\n  notebooklm artifact list\n```\n\n```prism language-bash\n ❯ notebooklm artifact list \n\n⏺ Bash(notebooklm artifact list)\n  ⎿                 Artifacts in 7d8c9378-a0c5-4579-91af-c6047bd13b82                \n     ┏━━━━━━━━━━━━━━━┳━━━━━━━━━━━━━━━━┳━━━━━━━━━━━━━━━┳━━━━━━━━━━━━━━━┳━━━━━━━━━━━━━┓\n     ┃ ID            ┃ Title          ┃ Type          ┃ Created       ┃ Status      ┃\n     ... +5 lines (ctrl+o to expand)\n  ⎿  Running PostToolUse hooks... (1/2 done)\n\n⏺ PPT 仍在生成中（状态: in_progress）。后台代理正在等待完成，完成后会自动下载。\n\n  通常 Slide Deck 生成需要 5-15 分钟，请稍候。\n\n✻ Cogitated for 34s\n\n⏺ Agent \"Wait for PPT and download\" completed\n\n⏺ PPT 生成完成并已下载！\n\n  文件信息：\n  - 路径: /Volumes/artisan/code/uom2026/UOM技术架构介绍.pdf\n  - 大小: 约 22.9 MB\n  - 页数: 17 页\n  - 标题: UOM Unified Operations Platform Technical Deep Dive\n\n  你可以直接打开这个 PDF 文件查看技术架构介绍 PPT。\n```\n\n*** ** * ** ***\n\n{#NotebookLM__862}结语：NotebookLM 的「程序化控制台」\n-----------------------------------------\n\n用一句话来概括 `notebooklm-py`：\n> 它把 NotebookLM 变成了一个可以脚本化、自动化、接入 Agent 的「可编程知识工作台」。\n\n如果你已经在用 NotebookLM 做研究、写作或教学，这个项目会极大拓展它在你工作流里的位置：  \n\n从「一个网页工具」，变成「内容 / 知识流水线中的一环」。\n\n当然，也要记住它的前提标签：**非官方、接口可能变动、适合原型和内部自动化**。\n\n建议你可以先从一个最简单的小目标入手，比如：\n> 把你最近看的三篇技术博客 + 两篇论文，做成一套「通勤路上听的播客 + 下班后刷的练习题」。\n\n写完这个脚本，你大概率就会明白：  \n\n为什么很多人说，像 `notebooklm-py` 这种工具，是未来「个人知识工厂」的标配。\n\n![在这里插入图片描述](http://localhost:9000/blog/crawled/2153ef08-94e3-428d-ab9d-5a41b4c52a12.jpeg)\n\n\n---\n\n> 本文转载自：[https://artisan.blog.csdn.net/article/details/157900987?fromshare=blogdetail&sharetype=blogdetail&sharerId=157900987&sharerefer=PC&sharesource=&sharefrom=from_link](https://artisan.blog.csdn.net/article/details/157900987?fromshare=blogdetail&sharetype=blogdetail&sharerId=157900987&sharerefer=PC&sharesource=&sharefrom=from_link)',1,'published',0,'2026-02-10 00:09:58','2026-02-10 00:09:58'),(17,5,'从 0 到 1 在浏览器里点亮你的第一个 3D 世界','很多前端第一次接触 three.js，都会被一堆新名词劝退：  \n**场景、相机、网格、几何体、材质、渲染器......**\n\n别急，其实 three.js 的核心就一句话：\n> **用 JavaScript 在浏览器里搭一个 3D 世界，然后让摄像机拍下来。**\n\n我们一步一步来。\n\n### {#Threejs__11}一、Three.js 在干嘛？先建立直觉\n\n在 three.js 里，几乎所有代码都围绕这 3 个对象展开：\n\n* **Scene（场景）**：整个 3D 世界的容器\n* **Camera（相机）**：你\"站在哪里\"看这个世界\n* **Renderer（渲染器）** ：把 3D 世界画到 `<canvas>` 上\n\n你可以把它理解成：\n\n```prism language-txt\nScene：舞台\nCamera：摄像机\nRenderer：摄影师 + 显示器\n```\n\n### {#_29}二、准备一个最小可运行环境\n\n先别上复杂工程，**一个 HTML 文件就够了**。\n\n#### {#1__threejs_33}1️⃣ 引入 three.js\n\n```prism language-html\n<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <title>Three.js 入门</title>\n  <style>\n    body {\n      margin: 0;\n      overflow: hidden;\n    }\n  </style>\n</head>\n<body>\n  <script src=\"https://unpkg.com/three@0.160.0/build/three.min.js\"></script>\n  <script>\n    // 后面的代码都写在这里\n  </script>\n</body>\n</html>\n```\n\n### {#_3D__59}三、创建你的第一个 3D 世界\n\n#### {#1__Scene_61}1️⃣ 创建场景 Scene\n\n```prism language-js\nconst scene = new THREE.Scene();\n```\n\n这一步很简单，但非常关键：  \n**后面所有 3D 物体，最终都会被丢进这个 scene 里。**\n\n#### {#2__Camera_72}2️⃣ 创建相机 Camera\n\nthree.js 最常用的是 **透视相机（PerspectiveCamera）**，更接近人眼。\n\n```prism language-js\nconst camera = new THREE.PerspectiveCamera(\n  75,                          // 视野角度（FOV）\n  window.innerWidth / window.innerHeight, // 宽高比\n  0.1,                         // 近裁剪面\n  1000                         // 远裁剪面\n);\n\ncamera.position.z = 5;\n```\n\n这里先记住一个经验值：\n\n* **z = 5**：基本能看到原点附近的物体\n* 物体默认都在 `(0, 0, 0)`\n\n#### {#3__Renderer_94}3️⃣ 创建渲染器 Renderer\n\n```prism language-js\nconst renderer = new THREE.WebGLRenderer({ antialias: true });\nrenderer.setSize(window.innerWidth, window.innerHeight);\ndocument.body.appendChild(renderer.domElement);\n```\n\n这一步做了三件事：\n\n1. 创建 WebGL 渲染器\n2. 设置画布尺寸\n3. 把 `<canvas>` 插入页面\n\n### {#_110}四、往场景里放点\"东西\"\n\n#### {#1_Box_112}1️⃣ 创建一个立方体（Box）\n\n在 three.js 里，一个能显示的物体 = **几何体 + 材质 + 网格**\n\n```prism language-js\nconst geometry = new THREE.BoxGeometry(1, 1, 1);\nconst material = new THREE.MeshBasicMaterial({ color: 0x00ff00 });\nconst cube = new THREE.Mesh(geometry, material);\n\nscene.add(cube);\n```\n\n解释一下：\n\n* **BoxGeometry**：立方体的\"形状\"\n* **MeshBasicMaterial**：最基础的材质（不受光照影响）\n* **Mesh**：把形状和材质组合起来的\"实体物体\"\n\n#### {#2__132}2️⃣ 让场景渲染出来\n\n```prism language-js\nrenderer.render(scene, camera);\n```\n\n如果你现在打开页面，**你已经能看到一个绿色立方体了 🎉**\n\n### {#_142}五、让立方体动起来（动画的本质）\n\n动画在 three.js 里，本质就是一句话：\n> **不断修改物体属性 + 不断重新渲染**\n\n#### {#1__requestAnimationFrame_148}1️⃣ 使用 requestAnimationFrame\n\n```prism language-js\nfunction animate() {\n  requestAnimationFrame(animate);\n\n  cube.rotation.x += 0.01;\n  cube.rotation.y += 0.01;\n\n  renderer.render(scene, camera);\n}\n\nanimate();\n```\n\n你会看到立方体开始转了。\n\n这里有个重要认知：\n\n* three.js **不会自动刷新**\n* 你每一帧都要手动 render\n\n### {#_172}六、加一点真实感：光照\n\n刚才我们用的是 `MeshBasicMaterial`，它**不吃光** 。  \n\n换一个支持光照的材质试试。\n\n#### {#1__177}1️⃣ 加环境光\n\n```prism language-js\nconst ambientLight = new THREE.AmbientLight(0xffffff, 0.5);\nscene.add(ambientLight);\n```\n\n#### {#2__184}2️⃣ 加平行光（类似太阳）\n\n```prism language-js\nconst directionalLight = new THREE.DirectionalLight(0xffffff, 1);\ndirectionalLight.position.set(5, 5, 5);\nscene.add(directionalLight);\n```\n\n#### {#3__192}3️⃣ 换成标准材质\n\n```prism language-js\nconst material = new THREE.MeshStandardMaterial({ color: 0x00ff00 });\n```\n\n现在立方体会有明暗变化，看起来就\"立体\"多了。\n\n### {#_5__202}七、新人最常踩的 5 个坑\n\n说点你以后一定会遇到的：\n\n1. **黑屏**\n\n   * 相机位置不对\n   * 没调用 `render`\n   * 物体没 `scene.add`\n2. **物体太小 / 看不见**\n\n   * 尺寸太小\n   * 被相机裁剪面裁掉了\n3. **窗口缩放后画面变形**   \n\n   记得监听 resize：\n\n   ```prism language-js\n   window.addEventListener(\'resize\', () => {\n     camera.aspect = window.innerWidth / window.innerHeight;\n     camera.updateProjectionMatrix();\n     renderer.setSize(window.innerWidth, window.innerHeight);\n   });\n   ```\n\n4. **性能突然变差**\n\n   * 网格数太多\n   * 几何体面数过高\n   * 每帧创建新对象\n5. **一开始就想做大场景**   \n\n   👉 新人阶段：**先学会\"看见、移动、交互\"**\n\n### {#_239}八、下一步你可以学什么？\n\n当你掌握了上面这些，接下来非常自然的路线是：\n\n* `OrbitControls`：用鼠标拖动视角\n* 加载模型：`GLTFLoader`\n* 材质进阶：纹理、法线贴图\n* 性能基础：合批、实例化\n* three.js + 前端框架（React / Vue）\n\n### {#_251}写在最后\n\nthree.js 并不神秘，它只是把 **WebGL 的复杂性封装成了你熟悉的 JS 对象模型**。\n\n你现在已经掌握了 three.js 的 **\"最小心智模型\"**：\n> 场景 + 相机 + 渲染器  \n>\n> 几何体 + 材质 = 物体  \n>\n> 动画 = 不停地改属性 + render\n\n\n---\n\n> 本文转载自：[https://blog.csdn.net/xrl__/article/details/157806559?fromshare=blogdetail&sharetype=blogdetail&sharerId=157806559&sharerefer=PC&sharesource=&sharefrom=from_link](https://blog.csdn.net/xrl__/article/details/157806559?fromshare=blogdetail&sharetype=blogdetail&sharerId=157806559&sharerefer=PC&sharesource=&sharefrom=from_link)',1,'published',0,'2026-02-10 00:17:02','2026-02-10 00:17:02'),(19,5,'套路化编程 C# winform 自适应缩放布局','[初级代码游戏的专栏介绍与文章目录-CSDN博客](https://blog.csdn.net/2301_77171572/article/details/136553502 \"初级代码游戏的专栏介绍与文章目录-CSDN博客\")\n\n本例程实现基本的自适应缩放布局。\n\n在本例程中你将会学习到如何通过鼠标改变界面比例（SplitContainer）、如何使用流布局（FlowLayoutPanel）排列控件，当然首先需要了解如何设置控件随窗口缩放。\n\n**目录**\n\n[创建项目](#%E5%88%9B%E5%BB%BA%E9%A1%B9%E7%9B%AE)\n\n[​编辑 控件自适应缩放](#%E2%80%8B%E7%BC%96%E8%BE%91%C2%A0%E6%8E%A7%E4%BB%B6%E8%87%AA%E9%80%82%E5%BA%94%E7%BC%A9%E6%94%BE)\n\n[使用SplitContainer调整界面比例](#%E4%BD%BF%E7%94%A8SplitContainer%E8%B0%83%E6%95%B4%E7%95%8C%E9%9D%A2%E6%AF%94%E4%BE%8B)\n\n[放置split控件](#%E6%94%BE%E7%BD%AEsplit%E6%8E%A7%E4%BB%B6)\n\n[将已有控件放入容器](#%E5%B0%86%E5%B7%B2%E6%9C%89%E6%8E%A7%E4%BB%B6%E6%94%BE%E5%85%A5%E5%AE%B9%E5%99%A8)\n\n[使用流布局容器FlowLayoutPanel](#%C2%A0%E4%BD%BF%E7%94%A8%E6%B5%81%E5%B8%83%E5%B1%80%E5%AE%B9%E5%99%A8FlowLayoutPanel)\n\n[放置flow控件](#%E6%94%BE%E7%BD%AEflow%E6%8E%A7%E4%BB%B6)\n\n[设置属性](#%E8%AE%BE%E7%BD%AE%E5%B1%9E%E6%80%A7%C2%A0)\n\n[增加控件](#%E5%A2%9E%E5%8A%A0%E6%8E%A7%E4%BB%B6)\n\n[运行效果](#%E8%BF%90%E8%A1%8C%E6%95%88%E6%9E%9C%C2%A0)\n\n[用代码协调布局](#%E7%94%A8%E4%BB%A3%E7%A0%81%E5%8D%8F%E8%B0%83%E5%B8%83%E5%B1%80)\n\n*** ** * ** ***\n\n<br />\n\n创建项目\n--------------------------------------------\n\n用VS2022创建一个新项目：\n\n![](http://localhost:9000/blog/crawled/bab6b077-b9de-4386-b53e-b30225171322.png)\n\n选择\"windows窗体应用\"。.net的命名体系是微软改名部的杰作，乱得比粥更乱，Framework已经停止更新了，做新的程序就别用了。WPF不太会，MFC过来的人比较习惯winform。下一代技术不明朗，不着急。\n\n框架选择8.0：\n\n![](http://localhost:9000/blog/crawled/53b30739-b849-42ed-880c-72cfc085bae4.png)\n\n选别的应该是差不多的。\n\n然后就进入项目了：\n\n![](http://localhost:9000/blog/crawled/0aef42dd-2dbd-4152-b421-f4a22084af95.png)\n\n编译运行就是这样：\n\n![](http://localhost:9000/blog/crawled/344a0974-f5fb-4f04-b1e5-05670462d8eb.png) 控件自适应缩放\n--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------\n\n首先我们来实现控件的自适应缩放。\n\n从工具箱（如果没有打开可以在菜单的【视图】下面找到\"工具箱\"）选择一个文本框（随便什么都行），放在窗体上：\n\n![](http://localhost:9000/blog/crawled/57b484ba-e07a-4b5f-8031-f978db22310c.png)\n\n默认的名字是textBox1，以后要用这个名字来选择控件设置属性。\n\n现在编译运行程序，主窗口是可以缩放的，但编辑框位置不会改变：\n\n![](http://localhost:9000/blog/crawled/baa7734e-945c-4b20-afe4-5a8a786c818a.png)\n\n修改编辑框的布局：\n\n![](http://localhost:9000/blog/crawled/30129e00-ec7e-4039-b7d5-dbe73bfe5407.png) 将Anchor改为四面都选中，如上图红框，再运行程序，用鼠标拉伸窗口：\n\n![](http://localhost:9000/blog/crawled/4d02036d-c9d1-44f8-883a-6a88bf221603.png)\n\n现在编辑框会变长了，却不会变高，这是因为单行编辑框不支持变高。将属性的Mutilline改为true就可以变高：\n\n![](http://localhost:9000/blog/crawled/af7f8b83-4d40-4270-8563-7da707ddfc4a.png) Anchor的作用很容易理解，就是锁定控件边框和父窗体边框的距离，这样就实现了自动缩放。\n\n使用SplitContainer调整界面比例\n----------------------------------------------------------------------------------------------------------------\n\n### 放置split控件\n\n现在给主窗体增加一个SplitContainer控件：\n\n![](http://localhost:9000/blog/crawled/7db5fd09-7944-4f99-a6f6-1b7ebafc8e05.png)\n\n注意红框里的控件名字，容器类控件在设计视图上很难选中，一不小心就点到子控件了，所以要记住名字，在属性窗口做选择。\n\n将容器控件拉大一些，可以用鼠标拖动中间的分隔条改变比例，如果不小心点到了子空间里面，就在属性窗口重新选择容器。\n\n### 将已有控件放入容器\n\n确保容器的Panel2足以放下之前创建的编辑框，把编辑框拖放到Panel2上：\n\n![](http://localhost:9000/blog/crawled/4e4645bf-1100-421b-a096-ddbfe27d2495.png)\n\n放进去以后尺寸变得太小了，调整大一些：\n\n![](http://localhost:9000/blog/crawled/57cfb41a-bc16-4227-ac16-e639ee461b41.png) 编辑框的Anchor属性仍然没有变，只是改变了父子关系。\n\n现在对容器也设置Anchor属性为四边都锁定：\n\n![](http://localhost:9000/blog/crawled/9ef42ef5-ffbf-4aa5-9f88-1b382784dd07.png)\n\n前面已经说了很难在设计窗口选中容器，所以要在属性窗口选择。然后运行程序：\n\n![](http://localhost:9000/blog/crawled/96af989c-2b40-45f5-8987-ea585156399a.png)\n\n![](http://localhost:9000/blog/crawled/f280465a-93f4-4ca3-b53f-9581266ed574.png)\n\n红线处应该有一条黑线可供拖动的，截图出来没有了。\n\n现在我们已经明白这个容器的运作机制了。然后我们把界面调整好看一些：\n\n容器拖放到最大，编辑控件也拖放到最大，再放一个控件到左边面板：\n\n![](http://localhost:9000/blog/crawled/727a32df-e1ba-4947-9c40-8b82b1b2b6de.png)\n\n左边是运行效果，右边是设计，随意缩放和改变比例：\n\n![](http://localhost:9000/blog/crawled/80027257-e2c1-4eb3-9497-b445d8f5216e.png)\n\n使用流布局容器FlowLayoutPanel\n--------------------------------------------------------------------------------------------------------------\n\n### 放置flow控件\n\n首先把SplitContainer缩小：\n\n![](http://localhost:9000/blog/crawled/56b32374-62f9-4f71-8202-64551313c495.png)\n\n然后从工具箱放置一个FlowLayoutPanel，放在刚才腾出的空位置上：\n\n![](http://localhost:9000/blog/crawled/9d65e858-440a-4a9f-929e-a65cbc4d734f.png)\n\n### 设置属性\n\nFlowLayoutPanel位置和属性调整一下：\n\n​​​​​![](http://localhost:9000/blog/crawled/02c17917-bfd4-4ac6-b79d-ef47feb96c56.png)\n\nAnchor改一下，改成三面锁定，如上图，\"Top,Left,Right\"。再将AutoSize设置为\"True\"，大小会根据内容自动变化。与缩放相关的选项可能会互相干扰，上面的操作是在默认属性基础上改两个，如果对效果有疑惑，删掉重新来。\n\n### 增加控件\n\n现在拖放一些控件到flow面板上，我放了5个按钮：\n\n![](http://localhost:9000/blog/crawled/ff10958f-f2fa-4f3e-8d4c-60c889b83d45.png)\n\n### 运行效果\n\n什么属性都不用改，直接运行程序就可以看到FlowLayoutPanel的自动排列效果了：\n\n![](http://localhost:9000/blog/crawled/9fa2de45-6d89-4725-9bbc-f01e014d7446.png)\n\n![](http://localhost:9000/blog/crawled/c893b0c5-bb6e-4d6e-ae11-c1076efeee99.png)\n\n挺不错的。想想看是不是缺了什么？\n\n### 用代码协调布局\n\n自动拉伸的flow控件把下面的Split容器遮盖了。如何解决呢？用一点点代码就可以解决了。\n\n给窗口增加Resize事件的处理程序，在属性的事件里的Resize后面的编辑区域双击即可自动增加处理程序：\n\n![](http://localhost:9000/blog/crawled/8631de91-8824-4b99-9064-10e25ed84aef.png)\n\n![](http://localhost:9000/blog/crawled/d80ac3de-db67-49ee-ba47-3b30dd584db2.png) 编辑代码：\n\n```cs\n		private void Form1_Resize(object sender, EventArgs e)\n		{\n			int flowHeight = 0;\n			foreach (Control v in this.flowLayoutPanel1.Controls)\n			{\n				int tmp = v.Location.Y + v.Height;\n				if (tmp > flowHeight) flowHeight = tmp;\n			}\n			int splitBottom = this.ClientSize.Height - 3;\n			int newtop = flowHeight + 3;\n			int newheight = splitBottom - newtop;\n			splitContainer1.Top = newtop;\n			splitContainer1.Height = newheight;\n		}\n```\n\n这段代码依赖两个容器的名字，但不依赖flow容器的子容器的名字。由于这里使用了代码来重设splitContainer1的上下位置，所以在属性里面要把上下锚定去掉，不然会与这里的代码冲突。费好大劲才发现这个问题。\n\n运行效果如下：\n\n![](http://localhost:9000/blog/crawled/5e31cf8b-8860-47ca-a560-8410f901813f.png)\n\nsplit容器的子控件的内容没有被遮盖。\n\n注意把flow容器的尺寸设置为刚好容纳一行按钮，因为代码假设了按钮和split容器的距离是3，实际中可以跟需要调整。\n\n<br />\n\n（这里是结束）\n\n\n---\n\n> 本文转载自：[https://blog.csdn.net/2301_77171572/article/details/135997354?fromshare=blogdetail&sharetype=blogdetail&sharerId=135997354&sharerefer=PC&sharesource=&sharefrom=from_link](https://blog.csdn.net/2301_77171572/article/details/135997354?fromshare=blogdetail&sharetype=blogdetail&sharerId=135997354&sharerefer=PC&sharesource=&sharefrom=from_link)',1,'published',0,'2026-02-10 00:29:16','2026-02-10 00:29:16'),(20,5,'自注意力机制self-attention与NLP','前几节课中，我们都是以图片作为输入对象，然而在实际当中，常见的输入还有文字、声音等不同种类。那么今天我们就来介绍一下新的输入对象------文字。\n\n文字输入\n----\n\n<br />\n\n  将文字作为输入的时，面临的第一个问题就是------怎么用数据来表示文字，根据之前的学习，我们将图片转为多维矩阵，作为输入值，同理我们也可以将文字编码为向量。\n\n  首先我们可以考虑使用One-hot Encoding独热编码，这种编码我们已经使用很多次了，但如果使用它将文字编码为向量，那不得不考虑：  \n\n1、汉字种类太多，会导致维度过长。  \n\n2、无法体现出文字之间的关系。第一点很好理解，不过多赘述。而在第二点里，例如\"猫\"\"狗\"两个词，二者在语义上是相似的，而由于独热编码向量之间正交，无法表示词汇之间的语义相似性。\n\n![](http://localhost:9000/blog/crawled/9c3db8d3-6ef1-4911-8c79-4be0a8fbdf2e.png)\n\n### 词嵌入（Word Embedding）\n\n那么如何解决这种问题呢，我们介绍一种新的技术------词嵌入(Word Embedding)。Word Embedding 是一种将词汇映射到低维连续向量空间的技术，它通过在大规模文本语料上训练得到，使得语义相似的词汇在向量空间中距离相近。能够有效表示语义信息，捕捉词汇之间的语义关系，有助于提高自然语言处理任务（如文本分类、机器翻译、情感分析等）的性能。  \n![](http://localhost:9000/blog/crawled/0c29c9fd-db8c-477a-91cc-3c365e4116f6.png)\n\n文字输出\n----\n\n讲完了文字输入，我们再来看看文字输出，根据输入输出的不同情况，我们对文字输出划分三类：\n\n1、每个词都有一个输出值  \n\n  如：我=\\>代词，爱=\\>动词，你=\\>名词  \n\n2、所有词输出一个值  \n\n  如通过语句进行情感分析，你做的不错=\\>正向，哎，又emo上了=\\>负向  \n\n3、输入输出长度不对应  \n\n  如语言翻译，我爱中国=\\>I love China  \n\n我们这次着重介绍前两种方式：一对一和多对一\n\n循环神经网络（RNN）\n-----------\n\n  假如我们现在接到一个任务，要求我们对句子里的词，进行词性分析。例如我爱你，分别为名词、动词、名词，似乎每个词都有其唯一对应的词性。然而，有时候现实生活中的语句并不会这么简单。\n\n![](http://localhost:9000/blog/crawled/cf07bc0b-355a-48e9-8fa9-d7f2aff31438.png)\n\n\"这爱爱的够深？\"，这句话中，第一个\"爱\"表现为名词，而第二个\"爱\"表现为名词，但显然机器不会这么想，这明明是两个一样的词，怎么就出现了不同意思？这就需要我们根据词的上下文（前后句）进行判断，并不是对某个词孤立地分析，于是就有了我们的循环神经网络\n\n  循环神经网络（Recurrent Neural Network，RNN）是一种专门用于处理序列数据的神经网络。与传统的前馈神经网络不同，RNN 具有循环连接，能够处理具有时间序列或序列依赖关系的数据。  \n![](http://localhost:9000/blog/crawled/4634660f-a86e-4f33-a15c-8adb11109f06.png)\n\n这种记忆单元存储和传递消息，模型会根据当前输入和之前的记忆单元，来进行计算和输出。RNN通过这种记忆单元的方式处理序列数据时对前后关系。对循环神经网络的介绍我们先点到为止。\n\n长短期记忆（LSTM）\n-----------\n\n  如果语句再复杂一些呢？\"我\"与\"赛罕塔拉\"这两个词距离太远了，保存在记忆单元的信息会因为长距离的传播而稀释与丢失。遇到这些长距离的问题，记忆单元直呼臣妾做不到啊。\n\n![](http://localhost:9000/blog/crawled/87b355fd-f151-4c67-846d-731047892552.png)\n\n长短期记忆(Long short-term memory, LSTM) 可以学习需要记忆之前发生的数千甚至数百万个离散时间步长的事件的任务。LSTM 的核心是细胞状态（cell state），它是一条贯穿整个网络的信息传递路径，类似于传送带，用于保存长期记忆。细胞状态可以选择性地让信息通过，实现信息的长期保存和传递。\n\n  LSTM 引入了三个门控单元，即输入门（Input Gate）、遗忘门（Forget Gate）和输出门（Output Gate），用于控制信息的流动和更新。具体来说，LSTM 通过输入门决定哪些新信息可以进入细胞状态，遗忘门决定细胞状态中哪些旧信息可以被遗忘，输出门决定细胞状态中的哪些信息可以输出。  \n![](http://localhost:9000/blog/crawled/81d14433-c259-4e0f-b3ba-75fd50a16ff3.png)\n\n 例如，当输入 \"爱\" 这个词时，输入门会根据当前的输入和上一时刻的状态来决定是否将与 \"爱\" 相关的信息存储到细胞状态中，同时遗忘门会决定是否遗忘之前细胞状态中的某些信息，最后输出门会根据细胞状态输出相应的信息。\n\n  这种机制使得 LSTM 能够更好地处理序列数据，捕捉长期依赖关系，例如在语言模型中，LSTM 可以根据前面的词语更好地预测后面的词语，因为它能够记住前面较远位置的信息，而不像普通的 RNN 那样容易出现梯度消失或梯度爆炸问题，导致无法有效利用长期信息。\n\n  虽然RNN和LSTM能够在一定程度上解决问题，但仍存在速度慢的问题（**串行执行**），就像你读书时只能一个字一个字读，我们有没有方法能一下子看到完整文章，输出结果。\n\n注意力机制\n-----\n\n<br />\n\n  注意力机制（attention） 是人工神经网络中一种模仿认知注意力的技术。这种机制可以增强神经网络输入数据中某些部分的权重，同时减弱其他部分的权重，以此将网络的关注点聚焦于数据中最重要的一小部分。就像打王者荣耀时，当我们身为辅助时，我们将注意力更多放在射手身上，即提高射手的权重，你会根据射手的位置、状态（比如血量、是否被敌方英雄攻击等）来分配你的注意力，比如现在射手已经回城了，那我们就可以不那么关注他了。  \n\nOut=0.6∗射手+0.1∗中单+0.1∗上单+0.2∗打野\n\n### 自注意力机制（Self-Attention）\n\n例如，辅助角色会考虑自己和己方输出英雄的距离，以及敌方刺客对自己的威胁程度。每个角色都在根据和其他角色的关系（技能配合、位置关系等）来调整自己对整个团战局面的理解（权重）。这种机制叫做自注意力机制。\n\n  自注意力机制没有像注意力机制那样有一个外部给定的主要关注点（如辅助关注射手），而是每个元素（角色）自身内部去衡量和其他所有元素的关联，并且根据这种关联来更新自己的状态（比如调整自己的走位、技能释放时机等）。\n\n  注意力机制是基于一个外部给定的关注点来筛选和整合信息，而自注意力机制是序列内部的元素之间相互作用，每个元素自己去确定对其他元素的关注度，从而更新自己的表示。\n\n自注意力机制  \n\n  自注意力机制， Self-Attention，又称内部注意力机制，顾名思义，是一种将单个序列的不同位置关联起来以计算同一序列的表示的注意机制。\n\n  所以，如何让模型自己对变量的权重进行自赋值成了一个问题，这个权重自赋值的过程也就是self-attention。\n\n![](http://localhost:9000/blog/crawled/ec6cdb93-e8fd-44a1-a7ec-5f99f4b7a3e5.png)\n\n![](http://localhost:9000/blog/crawled/f27dc9ad-7384-4e48-9679-83b8823daf28.png)![](http://localhost:9000/blog/crawled/4d612cbc-7a9b-45eb-9d0c-10f738ff20bb.png)\n\n![](http://localhost:9000/blog/crawled/c28c249c-e601-40a6-90b2-08fd1fa9e7b2.png)![](http://localhost:9000/blog/crawled/88986894-22ce-4b88-b025-f327e8bab20a.png)![](http://localhost:9000/blog/crawled/cc086a09-c3bd-4ae8-8a8d-6460942f3e39.png)\n\n![](http://localhost:9000/blog/crawled/7c050017-ed05-472e-aae1-22ddf4f294c3.png)\n\n![](http://localhost:9000/blog/crawled/57f7d681-2bf6-459b-8811-3ddd766c67e9.png)\n\n![](http://localhost:9000/blog/crawled/4e4549c3-eb69-4130-80aa-ba6f84ce9930.png)\n\n![](http://localhost:9000/blog/crawled/64ea391c-795b-48b8-b342-1e4f0db116d8.png)\n\n![](http://localhost:9000/blog/crawled/5dee5cc0-e9a4-4f14-ba6f-e70553eb89b8.png)\n\n<br />\n\n**![](http://localhost:9000/blog/crawled/3a86c81b-dac2-4618-8c5b-fb54329903ff.png)**\n\n<br />\n\n![](http://localhost:9000/blog/crawled/57ad880c-b087-4314-a3c6-aaf185e460a8.png)\n\n![](http://localhost:9000/blog/crawled/d042dd1c-bbdb-4317-b680-84785ff8f19e.png)\n\n![](http://localhost:9000/blog/crawled/5e770265-3dc2-44b9-ac19-364ea1ff6f4b.png)\n\n![](http://localhost:9000/blog/crawled/68528b0b-cae5-42a2-8cf3-02fd2c5c67fd.png)\n\n![](http://localhost:9000/blog/crawled/e4e8e938-3d6b-4359-acfe-5f6088214e50.png)\n\n**每一行第一个字都是这个字对其他字的注意力**\n\n![](http://localhost:9000/blog/crawled/0d624ffb-4883-41b2-ba11-f74dc8da81e4.png)\n\n**输入输出特征维度不变**\n\n<br />\n\n### 多头自注意力机制\n\n这里继续讲解multi-head self-attention，所谓head也就是指一个a衍生出几个q , k , v ，这样就会生成多个b。它并行地进行多个独立的自注意力计算，每个计算过程都有自己独特的查询、键和值的线性变换权重。这样做的好处在于，每个头都能够从不同的角度或表示子空间去关注输入序列，捕捉到不同层次和方面的语义关系和依赖关系。最后，将这些头的输出进行拼接或其他方式的组合，再通过一个线性层进行整合，得到最终的输出。\n\n例如：我们不会让768 一起 而是 768/4 分为四块，分别进行计算 4个头得到4个输出\n\n![](http://localhost:9000/blog/crawled/635b1024-bd78-4c68-b9a3-553526fd9fcf.png)\n\n### 位置编码\n\nPosition Encoding 对于各个x来说，无论相隔多远多近，相互影响的程度是一样的，当然一些倒装句更需要pos encoding 。自注意力机制本身并不关注元素在序列中的位置，这就导致模型可能无法区分 \"我吃了一个苹果\" 和 \"苹果吃了我一个\" 这样语义上完全不同但元素相同的句子。位置编码的引入就是为了弥补这一缺陷，让模型能够理解序列中元素的顺序和位置关系，从而更准确地处理序列数据\n\n**加一个所在位置，然后直接相加**\n\n![](http://localhost:9000/blog/crawled/716bbc7e-e2d1-453e-b67b-d5af90f038d1.png)\n\n![](http://localhost:9000/blog/crawled/5c3f475d-0537-48f7-a6f2-8b5bddf22c82.png)\n\n![](http://localhost:9000/blog/crawled/93c7579c-94a3-4db6-95bd-d56d7fdadd59.png)\n\n<br />\n\n一个字或词都被成为一个token\n\nTransformer模型\n-------------\n\n  我们可将该模型分为左右两部分：左边是编码部分(encoding component)，右边是解码部分(decoding component)。本章主要介绍编码部分。\n\n![](http://localhost:9000/blog/crawled/49f2b8e4-94de-4d7c-822d-8f4922684e41.png)\n\n<br />\n\n编码部分又可分为上下两部分：Feed Forward 和Multi-Head Attention\n\n  Multi-Head Attention就是我们之前介绍过的，多头注意力机制；而Feed Forward实际上全称为Feed Forward Neural Network（前馈神经网络，缩写为 FFNN）。下面简要介绍编码部分的流程：\n\n ** 输入（Inputs）**：首先是输入数据，这些数据会经过一系列处理。例如，在自然语言处理中，输入可能是一个句子，经过分词等预处理后进入模型。\n\n  **输入嵌入（Input Embedding）**：将输入的每个元素（如单词）转换为向量表示，这个向量包含了该元素的语义信息等。比如，\"apple\" 这个单词会被映射为一个特定的向量。\n\n  **位置编码（Positional Encoding）：**由于自注意力机制本身不包含位置信息，为了让模型知道元素的顺序，会添加位置编码。位置编码是与位置相关的向量，会与输入嵌入相加。例如，\"我爱你\"\"你爱我\"，\"你\"\"我\"的位置编码是不同的，这样模型就能区分它们在句子中的位置。\n\n ** 多头注意力（Multi-Head Attention）：**这是编码器的核心部分之一。首先，将输入的向量通过线性变换分别得到查询向量（Query）、键向量（Key）和值向量（Value）。然后，计算每个查询向量与所有键向量的点积，得到注意力分数，这些分数表示了一个元素与其他元素的相关性程度。接着，对注意力分数进行归一化（通常使用 Softmax 函数），得到注意力权重。最后，根据注意力权重对值向量进行加权求和，得到该元素的输出表示。多头注意力是指同时进行多个这样的注意力计算，每个头都有自己独立的参数矩阵，然后将多个头的输出拼接起来，再通过一个线性层进行整合，得到最终的多头注意力输出。\n\n**  残差连接与层归一化（Add \\& Norm）：残差连接（Add）：** 为了避免在深度网络中出现梯度消失或梯度爆炸的问题，以及让网络能够更好地学习恒等映射，将多头注意力的输入与输出相加，即𝑂𝑢𝑡𝑝𝑢𝑡=𝐼𝑛𝑝𝑢𝑡+𝑀𝑢𝑙𝑡𝑖𝐻𝑒𝑎𝑑𝐴𝑡𝑡𝑒𝑛𝑡𝑖𝑜𝑛(𝐼𝑛𝑝𝑢𝑡)  \n\n。**层归一化（Norm）：**对残差连接后的结果进行归一化处理，使得数据的分布更加稳定，有助于加快训练速度和提高模型的性能。\n\n  **前馈神经网络（Feed Forward）：**这是一个简单的全连接前馈神经网络，它由两个线性变换和一个激活函数（如 ReLU）组成。\n\nBert\n----\n\n BERT（Bidirectional Encoder Representations from Transformers）是一个编码器， 目的是把一句话编码为特征，它采用自监督预训练获得特征，提取能力。 之后在下游任务可以提取特征后， 让特征去做分类任务。\n\n  BERT 是基于自注意力机制的强大模型，它主要是一个特征提取器。在预训练阶段有 Masked Language Model 和 Next Sentence Prediction 等任务。在结构上主要包括 embedding 层（进行词嵌入和位置嵌入）、Self - attention 层（让特征交互）和 pooler 输出层。例如在情感分类任务中，BERT 可以先对句子进行编码提取特征，然后进行分类。\n\n### Bert预训练\n\n<br />\n\n  **Masked Language Model（MLM）** 在输入文本中，随机掩盖一定比例（通常为 15%）的词语，然后让模型预测这些被掩盖的词语。例如，对于句子 \"集合推进【MASK】路\"，模型需要根据上下文信息预测 \\[MASK\\] 处的词语可能是 \"中\"\"上\"\"下\" 等。\n\n  在进行掩盖时，并不是简单地将词语替换为 \\[MASK\\] 标记，而是有以下几种处理方式：\n\n80% 的情况将词语替换为 \\[MASK\\] 标记，例如 \"集合推进【MASK】路\"  \n\n10% 的情况将词语随机替换为其他词语，例如将 \"集合推进中路\" 中的 \"中\" 随机替换为 \"上\"，变成 \"集合推进上路\"，这样可以让模型学习到词语之间的差异和语义的敏感性。  \n\n10% 的情况保持词语不变，例如 \"集合推进中路\" 中的 \"中\" 不做任何改变，这可以让模型学习到即使没有被掩盖，也需要根据上下文来理解词语的含义。  \n\n  这种方式迫使模型深入学习文本的语义和语法结构，以及词语之间的上下文关系。因为模型为了准确预测被掩盖的词，必须理解整个句子的含义，包括词语的词性、语义角色、搭配关系等，从而学习到丰富的语言特征和知识。\n\n  **Next Sentence Prediction（NSP）**：给定两个句子，让模型判断第二个句子是否是第一个句子的下一句。例如，\"敌人团灭了，集合推进中路。\" 是相邻的句子，而 \"敌人团灭了。快保护我。\" 不是相邻的句子，模型需要能够区分这种差异。通过这种任务，模型能够学习到句子之间的逻辑关系和语义连贯性。\n\n### Bert结构\n\n<br />\n\n  BERT 主要由输入层、多个编码器层和输出层组成。输入层对文本进行向量化处理，包含多种嵌入信息；编码器层基于 Transformer 架构进行特征提取与语义理解；输出层依任务不同而设计，可用于文本分类、序列标注等多种自然语言处理任务。  \n![](http://localhost:9000/blog/crawled/e54ef9ee-4f9d-49df-a87c-f94839cd9f74.png)\n\n 输入数据首先经过嵌入（embedding）层，将输入转换为向量表示，然后经过多个 BERT 层（bert layers）进行特征提取和处理，BERT 层的结构在右侧有详细展示，经过 BERT 层处理后得到的输出再经过池化器（pooler）得到池化器输出（pooler output），最后将池化器输出输入到分类器（classifier）中进行分类等任务。而其中BERT层与Transformer编码器结构类似。\n\n**Embedding 层**\n\n  将输入的文本数据（如单词、字符等）转换为向量表示。常见的嵌入方式：包括词嵌入（Word Embedding）和位置嵌入（Positional Embedding）等。词嵌入是基于大规模语料库训练得到的，能够将单词映射到一个连续的向量空间中，使得语义相近的单词在向量空间中距离较近；位置嵌入则是为了让模型能够感知输入元素的顺序，因为自注意力机制本身不包含位置信息，位置嵌入会根据元素在序列中的位置生成相应的向量，并与词嵌入相加作为最终的输入嵌入。\n\n**Pooler Output（池化器输出）**\n\n  通常是对 BERT 层最后一层的输出进行某种池化操作（如取第一个元素的向量、取所有元素向量的平均值等），得到一个固定维度的向量表示，作为整个输入序列的特征表示，用于后续的任务处理。\n\n**Classifier（分类器）**\n\n  根据具体的任务，在池化器输出的基础上添加一个或多个全连接层等组件，构成分类器。例如，在文本分类任务中，分类器可以是一个简单的线性层加上 Softmax 函数，将池化器输出映射到类别数的维度，并通过 Softmax 得到每个类别的概率，从而实现对输入文本的分类。\n\n### **Bert输入**\n\n<br />\n\n  在BERT中，输入的向量是由三种不同的embedding求和而成，在以下所举的例子中，每个单词都表示为一个768维的向量。具体形式如下图：\n\n![](http://localhost:9000/blog/crawled/63eb39b4-29b6-4db9-a17e-35ba467e99d9.png)\n\n分别是Token嵌入层，Segment嵌入层和Position嵌入层，以下是对其介绍\n\n  词嵌入，Token，它将文本中的每个词映射到一个高维向量空间中，使得语义相似的词在向量空间中距离较近。这其中会有一些特殊的Token，例如开头的\\[ELS\\]和结尾的\\[SEP\\]。与开头讲到的Word Embedding类似\n\n  分段嵌入，Segment，用于区分输入的不同句子。在 BERT 中，输入可以是单个句子，也可以是两个句子拼接在一起（例如用于句子对的任务，如判断两个句子的语义关系）。对于每个词，会根据它所在的句子分配一个特定的分段嵌入。通常，第一个句子中的词的分段嵌入为 0，第二个句子中的词的分段嵌入为 1。\n\n  位置嵌入，Position，为了让模型能够理解输入序列中词的顺序，BERT 引入了位置嵌入。位置嵌入是一个与输入序列长度相同的向量序列，每个位置对应一个特定的向量，这些向量是通过学习得到的。位置嵌入会根据词在句子中的位置添加到词嵌入上，从而为模型提供了词的顺序信息。\n\n### Bert输出\n\n<br />\n\n  面对不同任务，我们会采取不同的输出操作，以达到突出关键特征、适配任务需求、降低数据维度等目的  \n![](http://localhost:9000/blog/crawled/14dd3c30-4dfb-4ebb-a42e-dbd1da6cff8f.png)\n\n1、只输出CLS （最常用）\n\n2、平均池化\n\n3、最大池化\n\n4、其他\n\n<br />\n\n<br />\n\n\n\n---\n\n> 本文转载自：[https://blog.csdn.net/qq_73463843/article/details/157399541?spm=1000.2115.3001.10524](https://blog.csdn.net/qq_73463843/article/details/157399541?spm=1000.2115.3001.10524)',1,'published',0,'2026-02-10 00:58:37','2026-02-10 00:58:37'),(21,5,'马斯克周末血裁xAI 500人','什么情况，帮马斯克训练大模型的人说失业就失业了？\n\n上周四晚，xAI 内部上演了一场突袭测试，还要求员工必须在第二天早上之前完成并提交。\n\n这可不是一次简单的随堂测试------\n\n截至目前，本次 xAI 内部测试的淘汰率高达 33%，已有**超过 500 名员工**被通知卷铺盖走人。\n\n![](http://localhost:9000/blog/crawled/21d87c57-2e82-4848-9c57-157a7040cd64.jpg)\n\n马斯克裁员式考核\n--------\n\n数据标注团队曾是 xAI 最大的团队，在 Grok 的开发过程中发挥了关键作用。他们的工作是标记、分类并将原始数据置于特定语境中，从而教会 AI 如何更好地理解世界。\n\n自 xAI 成立以来，数据标注团队的规模一直在持续增长。\n\n**与大多数人工智能公司不同，xAI 的许多数据标注员都是直接聘请的，而非外包**。通过这种方式，可以让公司对模型训练拥有更多的控制权，更好的隐私。\n\n但相应的，成本也更高。\n\n今年 2 月份，xAI 披露计划雇用数千人来帮助训练 Grok，并在半年内新增了约 700 名数据标注员。\n\n![](http://localhost:9000/blog/crawled/850e4c5e-d2e8-4495-9e6b-790ec21a0893.jpg)\n\n然而 9 月初，Linkedin 页面显示，负责管理数据标注团队的十几名经理中，**至少已有 9 位被解雇**。\n\n这次不太寻常的人事变动，为即将到来的剧烈动荡埋下了种子。\n\n之后一段时间内，xAI 开始与数据标注团队的部分员工开展**一对一的谈话**。\n\n在交流过程中，这些员工被要求展示他们的工作成果以及他们能如何为 xAI 创造价值。\n\n山雨欲来风满楼，据部分员工表示，这一系列约谈在 xAI 内部营造了一种 \"恐慌感\"。\n\n不出所料，上周四晚，xAI 在 Slack_（一个类似于飞书的团队协作工具）_上发布了公告：\n> 请部分员工放下手头工作，在明早之前至少参加一次测试，以确定你们未来在公司的角色。\n\n据悉，测试涵盖了传统领域，如 STEM、编程、金融和医学，也包括一些较为另类的方向，比如 Grok 的 \"个性与模型行为\" 以及\"段子手和沉迷刷屏者\"。\n\n除此之外，还有面向提升 chatbot 安全性的测试。\n\n公告发布后，超过 100 名员工在 Slack 上表示不解，一名员工直言对测试的时间安排感到不满。\n> 在人们下班回家后做这种事，真是见不得人。\n\n![](http://localhost:9000/blog/crawled/008413d2-00a0-411e-a25a-2059f269711d.jpg)\n\n可反抗并没有起到什么作用，更没有阻止噩耗传来------\n\n测试结束不久，周五晚，许多数据标注员收到了解雇邮件，宣告其在 xAI 的旅途到此结束。\n\n解雇邮件中这样写道：\n> 在全面审查了我们的人力数据工作后，我们决定加快数据标注员的扩张和优先级排序，同时减少对普通 AI 数据标注员职位的关注。  \n>\n> 这一战略转变将立即生效。作为此次重点转变的一部分，我们不再需要大多数普通数据标注员职位，您在 xAI 的雇佣关系也将终止。\n\n*（ps：xAI 的数据标注团队主要由两部分组成：一部分是负责 STEM、编程、金融、法律和媒体等垂直领域的专业数据标注员；另外很大一部分是负责视频标注、音频标注、写作等任务的通用数据标注员。）*\n\n根据 Slack 聊天室上的人数统计，数据标注团队的成员已从 1500 名下滑至 1000 多人，即接近三分之一的员工被裁。\n\n与之形成鲜明对比的，是 xAI 的全新招聘启事：\n\n该公司计划将**专业数据标注员的规模扩展现有基础上的 10 倍**。\n\n![](http://localhost:9000/blog/crawled/b3d5c125-1f61-450c-a96d-5ce6c305bf61.jpg)\n\n马斯克转舵：押注垂直领域 AI\n---------------\n\n长期以来，人们一直认为数据越多越好。\n\n然而，此次 xAI 从通用数据标注员向专业数据标注员的大角度倾斜，可能反映出马斯克恰恰押注于相反的观点------**质量重于数量**。\n\n这样做的好处是，可以提升 Grok 在特定领域的能力和可信度。\n\n但缺点也很明显，依赖较小的专家库可能会限制模型看到的数据的多样性，人工智能系统依赖于多样性而蓬勃发展，过度缩小训练数据可能会带来盲点。\n\n对模型厂商来说，重点在于**如何在约束条件改变的情况下，重新在质与量之间找到新的平衡**。\n\n自互联网上的高质量语料消耗殆尽后，Scaling Law 迎来边际效应递减的拐点，模型训练成本快速攀升，大模型的发展也随之进入平台期。\n\n![](http://localhost:9000/blog/crawled/a13a7456-18e4-410a-b00b-9d38eab133a7.jpg)\n\n此外，通用模型虽然具备更强的广度，但在金融、医疗、法律等行业，参数量相对较小的垂直模型反而更容易保证准确性与合规性。\n\n在此背景下，过去想象中大一统通用模型的画像越来越模糊，垂直场景却百花齐放。\n\n马斯克或许正是看中了这一点。\n\n因此，这次 xAI 裁员可能并非一次简单的团队重组，而是瞄准垂直行业 AI 蓝海而下的一笔巨额赌注。\n\n如果成功，Grok 有望在行业垂直应用领域建立优势。\n\n但若失败，硅谷钢铁侠之队可能会在 Scaling Law 这条赛道上失速，被 OpenAI 和 Anthropic 甩在身后。\n\n为什么马斯克爱裁员？\n----------\n\n众所周知，马斯克如此大刀阔斧地拆解公司团队并不是新鲜事。\n\n在 Model 3 产能地狱时期，愤怒老马 2 年内便裁掉了 7000 多人，这还仅仅是特斯拉公开披露的数字。\n\n那段时间，除非迫不得已，特斯拉员工不会轻易经过马斯克的办公桌，以免引起老马的注意，一个不小心就危及他们的职业生涯。\n\n曾深受其害的特斯拉员工们甚至专门为此创造了一个术语------**Elon 的愤怒解雇**。\n\n这个技能，马斯克从特斯拉到𝕏，再到现在的 xAI，都在持续释放。\n\n2022 年，老马刚接手 Twitter 的时同样开启了 \"愤怒 Elon\" 模式，不到一周时间就开掉了 3700 名 Twitter 老员工，一度使得 Twiiter 多个部门瘫痪。\n\n马斯克为什么这么喜欢开人？\n\n这与他的**硬核理念**密不可分------\n\n**喜欢带领精悍的团队作战，格外强调性能与效率，受不了高强度工作或者拿不出成绩就滚蛋**。\n\n![](http://localhost:9000/blog/crawled/2cd5e856-e6eb-4166-bcdf-ff82252a6c95.jpg)\n\n具体来说，马斯克更喜欢技术能力较强的小团队，他坚决抵制扩大团队规模，认为规模较小但能力强且积极进取的团队通常比规模大得多的团队表现更好，主要有 3 点理由：\n\n第一，小团队能调动的人力资源更少，反而会因此变得更有创意、更贪婪、更忙碌。\n\n第二，小团队几乎不需要中层管理人员，更方便拿到一手信息，沟通效率更高。\n\n第三，小团队的运行速度更快，能大大缩短迭代周期。\n\n而经过老马严选留下来的员工也并非永远安全。\n\n马斯克非常强调性能与效率，对低绩效者的容忍度低，特斯拉前人工智能负责人 Andrej Karpathy 提到他有时候甚至要 **\"fight to keep some people\"**。\n> 大多数硅谷公司都 \"宠爱\" 员工，而马斯克则倾向于 \"强迫\" 员工拼尽全力，表现不佳的人很快就会被从团队中除名，我需要很努力才能说服他让一些人留在团队中。\n\n![](http://localhost:9000/blog/crawled/7383be7d-8e11-49e4-9cf5-072bc2a42c1e.jpg)\n\n2022 年末，马斯克在午夜用电子邮件中向原 Twitter 员工发出了类似的最后通牒，\"专注于硬核文化，否则，请带着遣散费离开\"。\n> 展望未来，要构建突破性的 Twitter 2.0 并在竞争日益激烈的世界中取得成功，我们需要非常硬核，这意味着长时间高强度工作，只有出色的表现才能称得上是及格。\n\n但事实证明，这种方式的确有助于激发团队潜力。\n\n所以这次 xAI 的裁员，会让 Grok Great 起来吗？\n\n参考链接：  \n\n\\[1\\][economictimes.indiatimes.com/news/intern...](https://link.juejin.cn?target=https%3A%2F%2Feconomictimes.indiatimes.com%2Fnews%2Finternational%2Fus%2Fmass-layoffs-at-elon-musks-xai-500-data-workers-axed-as-grok-chatbot-faces-big-changes%2Farticleshow%2F123870379.cms \"https://economictimes.indiatimes.com/news/international/us/mass-layoffs-at-elon-musks-xai-500-data-workers-axed-as-grok-chatbot-faces-big-changes/articleshow/123870379.cms\")  \n\n\\[2\\][www.businessinsider.com/xai-managem...](https://link.juejin.cn?target=https%3A%2F%2Fwww.businessinsider.com%2Fxai-management-shakeup-data-annotation-team-2025-9 \"https://www.businessinsider.com/xai-management-shakeup-data-annotation-team-2025-9\")  \n\n\\[3\\][x.com/xai/status/...](https://link.juejin.cn?target=https%3A%2F%2Fx.com%2Fxai%2Fstatus%2F1966677385056841884 \"https://x.com/xai/status/1966677385056841884\")  \n\n\\[4\\][www.theguardian.com/technology/...](https://link.juejin.cn?target=https%3A%2F%2Fwww.theguardian.com%2Ftechnology%2F2025%2Fmay%2F05%2Felon-musk-doge-federal-government \"https://www.theguardian.com/technology/2025/may/05/elon-musk-doge-federal-government\")  \n\n\\[5\\][www.wired.com/story/elon-...](https://link.juejin.cn?target=https%3A%2F%2Fwww.wired.com%2Fstory%2Felon-musk-tesla-life-inside-gigafactory%2F \"https://www.wired.com/story/elon-musk-tesla-life-inside-gigafactory/\")  \n\n\\[6\\][www.theverge.com/2022/11/16/...](https://link.juejin.cn?target=https%3A%2F%2Fwww.theverge.com%2F2022%2F11%2F16%2F23462026%2Felon-musk-twitter-email-hardcore-or-severance \"https://www.theverge.com/2022/11/16/23462026/elon-musk-twitter-email-hardcore-or-severance\")  \n\n\\[7\\][medium.com/the-low-end...](https://link.juejin.cn?target=https%3A%2F%2Fmedium.com%2Fthe-low-end-disruptor%2Felon-musks-leadership-style-424343fe6cb3 \"https://medium.com/the-low-end-disruptor/elon-musks-leadership-style-424343fe6cb3\")\n\n**欢迎在评论区留下你的想法！**\n\n--- **完** ---\n\n\n---\n\n> 本文转载自：[https://juejin.cn/post/7550466215790968847](https://juejin.cn/post/7550466215790968847)',1,'published',4,'2026-02-10 01:03:17','2026-02-10 01:03:17'),(23,5,'宝塔面板部署 Spring Boot +Vue 前后端项目教程','宝塔面板部署 Spring Boot+ Vue 前后端项目教程\n-------------------------------\n\n本教程适用于在 Linux 云服务器上，通过宝塔面板部署 Vue 前端 + Spring Boot 后端 + MySQL 数据库的前后端分离项目。  \n\n内容涵盖 Spring Boot 项目部署、Vue 前端打包上线、Nginx 反向代理配置及 MySQL 环境准备，适合用于学习实践、课程设计及初级线上部署。\n\n### 一、准备阶段\n#### 1. 云服务器推荐\n* **阿里云服务器** ：[阿里云轻量应用服务器](https://url.cn/dbkMLhXg)\n\n* **零零壹云计算** （推荐）：[零零云计算](https://www.001yun.net/) 9.9 元/月，国外服务器无需备案，适合练手部署单体项目  \n  ![](http://localhost:9000/blog/crawled/1dd871e2-9c89-4495-9c61-1534995de10c.png)  \n  ![](http://localhost:9000/blog/crawled/2f943730-9997-4bfd-80d9-ea3853f7f7d8.png)\n\n#### 2. 系统选择\n建议选择 Linux 系统，如 CentOS / Ubuntu / Debian（轻量、兼容性好）。Windows Server 亦可用，但不推荐。  \n![在这里插入图片描述](http://localhost:9000/blog/crawled/07c62bf8-a967-4fe0-83bf-9babea7b60b8.png)\n\n#### 3. 域名准备（可选）\n* 推荐使用普通域名 + 云服务器绑定\n\n* 国内域名需备案，可备注为\"个人学习项目\"，通过率高\n\n### 二、安装宝塔面板\n#### 1.前往 宝塔官网 获取安装命令，建议选择 Linux 面板。\n![在这里插入图片描述](http://localhost:9000/blog/crawled/09ce0e7a-f420-4d33-b2d7-c2dfa5232341.png)\n\n#### 2.选择安装套件\n![在这里插入图片描述](http://localhost:9000/blog/crawled/a821a5f0-baa4-48ff-85b9-59eb626e033c.png)\n\n#### 3.等待 5-10 分钟，安装完成后记录面板地址、用户名和密码。\n![在这里插入图片描述](http://localhost:9000/blog/crawled/2cfedfbb-9d6f-4159-9281-c14eca6d968b.png)\n\n#### 4.服务器开放端口（访问宝塔面板）\n* 如上图宝塔面板安装在该服务器22端口，则需要在服务器的防火墙处开放该端口才能进行公网访问，如果使用的是零零壹云计算云服务器，不需要此操作，默认端口都是开放的。\n* 同时注意，开放面板端口时，同时开放8888，888，443，20，21端口，以及3306（MySql的使用端口），6379（Redis的使用端口）  \n  ![在这里插入图片描述](http://localhost:9000/blog/crawled/f926357a-ec6e-4cce-9975-eb3c2103537d.png)  \n  ![在这里插入图片描述](http://localhost:9000/blog/crawled/0453cb26-27cd-41f7-821f-828396cede85.png)\n\n#### 5. 进入宝塔面板，访问面板地址，并输入用户名和密码。之后还需要同意协议和绑定手机号\n![在这里插入图片描述](http://localhost:9000/blog/crawled/5f5b512a-cfaf-4f79-8c20-85682c96113a.png)\n\n### 三、宝塔的基础配置\n#### 1.进入宝塔后，看一下对应软件是否安装\n![在这里插入图片描述](http://localhost:9000/blog/crawled/ddc61ef9-9da1-46d3-98ed-3cd89b1498c6.png)\n\n#### 2.宝塔端口放行\n* 后端：  \n  8082端口（**`这是我后端运行的端口，根据自己的项目选择，Spring Boot 应用的默认端口为8080`**）\n* 前端：  \n  80 端口，  \n  443端口：如果配置了 HTTPS，需要放行。\n* 宝塔面板自身：  \n  8888 端口：宝塔面板的默认访问端口（如果未修改）。  \n  888 端口：宝塔面板的文件管理端口。\n* 数据库（如果需要远程访问）  \n  3306 端口：MySQL 数据库默认端口。  \n  6379 端口：Redis 数据库默认端口\n\n### 四、部署前准备工作\n在正式部署项目前，需做好以下配置和准备：\n\n#### 1. 修改前端请求地址\n在 `src/utils/request.js` 中配置 baseURL，确保前端能正确访问后端接口：\n\n    const isProd = true;\n    const baseURL = isProd ? \'http://你的公网IP:8082\' : \'http://localhost:8082\';\n\n说明：\n\n* `isProd` 表示是否为生产环境；\n\n* 本地开发阶段使用 localhost，部署上线后使用公网 IP。\n\n### 2. Spring Boot 多环境配置\n为实现开发与生产环境的隔离，Spring Boot 推荐采用多环境配置：\n\n##### 配置文件结构：\n在 `resources/` 目录下创建如下配置文件：\n\n    application.yml             # 公共配置入口\n    application-dev.yml         # 开发环境配置\n    application-prod.yml        # 生产环境配置\n##### application.yml 示例：\n    spring:\n      profiles:\n        active: prod  # 指定当前激活环境\n##### 配置说明：\n* `application-dev.yml`：配置本地数据库、调试日志、跨域策略等；\n\n* `application-prod.yml`：配置生产数据库、禁用调试日志、收紧跨域权限等。\n\n##### 启动原理：\nSpring Boot 启动时将：\n\n1. 加载 `application.yml`，根据 `active` 字段确定当前环境；\n\n2. 自动引入对应环境配置文件；\n\n3. 若存在配置冲突，以具体环境配置为准。\n\n> ✅ 多环境配置有助于提升部署安全性、减少环境冲突问题。\n\n### 五、前后端打包\n#### 1. Vue 前端打包\n使用如下命令对 Vue 项目进行打包：\n\n    npm run build\n\n成功后会在项目根目录下生成 `dist/` 目录，该目录为最终部署静态资源。\n\n* 将 `dist` 目录下所有文件上传至宝塔面板中创建的网站根目录（如 `/www/wwwroot/your-site/`）。\n\n![在这里插入图片描述](http://localhost:9000/blog/crawled/f096ec2f-571c-4755-a8b4-d708d5476fe2.png)  \n![在这里插入图片描述](http://localhost:9000/blog/crawled/10b0977e-d7d8-4a3e-ad48-0dc7c8d61273.png)\n\n#### 2. Spring Boot 后端打包\n确保 Maven 已正确配置\n\n在idear中点击maven图标，点击package进行打包，执行成功后会在 `target/` 目录生成 `.jar` 包\n\n![在这里插入图片描述](http://localhost:9000/blog/crawled/d9a26f92-378d-404e-b29d-0214e0ea9c68.png)  \n![在这里插入图片描述](http://localhost:9000/blog/crawled/edaae6aa-b184-412b-a0b6-5a1ee961572c.png)\n\n### 六、部署打包文件上传\n![在这里插入图片描述](http://localhost:9000/blog/crawled/18a561a3-20c7-4acb-819f-9cc520b893c5.png)  \n![在这里插入图片描述](http://localhost:9000/blog/crawled/bde16c26-8373-465e-859a-7b1a77fdf749.png)  \n![在这里插入图片描述](http://localhost:9000/blog/crawled/3e4af3c6-8408-4235-86cb-b27ce15f6d84.png)  \n![在这里插入图片描述](http://localhost:9000/blog/crawled/20bf99a5-407c-4d1b-a5a5-ba828a97d902.png)\n\n### 七、部署前端服务（Vue）\n#### 1. 添加 Vue 网站项目\n* 在【网站】中创建HTML项目，绑定域名或 IP\n\n* 选择 `dist` 文件夹的的路径至网站根目录\n\n![在这里插入图片描述](http://localhost:9000/blog/crawled/223e2d2c-c162-466f-af18-fa653761bc0d.png)\n\n#### 2. 配置 nginx 静态路由\n在【设置】-【配置文件】中添加：\n\n    location / {\n        try_files $uri $uri/ /index.html;\n    }\n\n![在这里插入图片描述](http://localhost:9000/blog/crawled/07a0f4d5-f7b0-4533-a430-dde52e91e738.png)\n> 保存后重启 nginx 服务\n\n### 八、部署后端服务（Spring Boot）\n#### 1. 安装 Java 环境\n* 【网站】的java项目中点击java环境管理，安装 OpenJDK（推荐 8 或 17）\n\n![在这里插入图片描述](http://localhost:9000/blog/crawled/d2f7ad1e-d567-4418-974f-b65d7c8752a9.png)\n\n#### 2. 添加 Java 项目\n* 点击添加java项目，选择springboot项目，项目路径为之前jar包上传保存的路径，端口为后端项目的端口  \n  ![在这里插入图片描述](http://localhost:9000/blog/crawled/c7ae29ee-ac5b-4abe-bbf3-5437b1eea621.png)\n\n### 九、配置数据库\n#### 1. 创建MySQL数据库\n![在这里插入图片描述](http://localhost:9000/blog/crawled/aec8db25-9f04-49fa-93ea-d7b23d4dc090.png)  \n![在这里插入图片描述](http://localhost:9000/blog/crawled/b8801d84-0dcf-4f5c-937c-3eb49be8f281.png)\n\n#### 2. 导入 SQL 文件：\n* 在idear中导出sql文件  \n  ![在这里插入图片描述](http://localhost:9000/blog/crawled/eb0ade0d-6e92-413b-9e3d-329c8de6de82.png)  \n  ![在这里插入图片描述](http://localhost:9000/blog/crawled/4b4f2a85-75c9-4974-a304-ea5936d032d5.png)  \n  ![在这里插入图片描述](http://localhost:9000/blog/crawled/fb9d43e4-a1b8-478f-9ad7-321c98c195ef.png)\n\n* 通过 phpMyAdmin导入项目 SQL 文件  \n  ![在这里插入图片描述](http://localhost:9000/blog/crawled/28a70775-580a-4a0a-b461-d3aff148a1e8.png)  \n  ![在这里插入图片描述](http://localhost:9000/blog/crawled/b08bb445-6592-401a-8ea2-902a67433a60.png)\n\n### 十、完成部署\n1. 确保端口全部放行（服务器和宝塔）\n\n2. 重启后端项目、nginx 服务\n\n3. 浏览器访问：\n\n* 前端访问：`http://你的域名或公网IP`\n\n* 后端接口调试：`http://你的域名:8082/api/...`\n\n> 至此，前后端分离项目部署完毕，可访问测试。\n\n如果你觉得这篇文章对你有帮助，欢迎点赞收藏 ❤️  \n\n也可以关注我，一起交流成长，后续会持续分享前后端开发、部署实战和项目经验～💻✨\n\n\n---\n\n> 本文转载自：[blog.csdn.net](https://blog.csdn.net/2401_83496204/article/details/148017336)',NULL,'published',6,'2026-03-03 22:16:40','2026-03-03 22:16:40'),(24,5,'36岁程序员被曝复工当晚猝死出租屋内','昨晚刷视频，看到一条消息手抖了一下。\n\n米哈游一位36岁的程序员，春节复工第二天，倒在出租屋的浴室里。同事说他初八状态还挺好，谁也不知道那是最后一面。\n\n说实话，这种新闻我见得不算少。上一个上热榜的是**广州32岁程序员周末晕倒后猝死，抢救期间曾被拉入工作群，死亡后还收到工作消息...**\n\n![image-20260301143042244](http://localhost:9000/blog/crawled/98d5f3aa-1c4e-4f94-b259-10909855bf00.png)\n\n但这一次，我盯着屏幕愣了很久。\n\n![image-20260301143259528](http://localhost:9000/blog/crawled/53e1af24-6acc-4a9f-94ed-bc0523bf1531.png)\n\n![image](http://localhost:9000/blog/crawled/82583ccf-54d4-49be-b240-af884ff8fe49.png)\n\n不是因为大厂光环，而是因为那个数字------**36岁** 、**32岁**。\n\n这个年纪，本该是技术最纯熟、经验最丰富、最能扛事的时候。也是上有老下有小，房贷车贷压得喘不过气的年纪。更是那个\"再拼几年就财务自由\"的执念，最深的年纪。\n\n**一、我们这一行，早就把\"拼命\"写进了代码里**\n\n刚入行那会儿，我也觉干我们这行哪有不熬夜的，996那不是家常便饭。\n\n凌晨12点的公司大楼，保安都认识我们几个熟面孔。外卖软件里收藏的全是24小时营业的店，工位下面常备折叠床和毛毯。\n\n体检报告？那是每年最不想打开的文件。\n\n我们管这叫\"福报\"，叫\"成长\"，叫\"趁年轻多积累\"。\n\n可没人告诉我们，身体是有利息的。你透支的每一分钟，它都默默记了账。\n\n那位离世的程序员，家属说他\"工作表现出色极度聚焦\"，\"即便工作强度已经远超常人也默默坚守从不抱怨\"。\n\n这段话我读了好多遍。太熟悉了，这不就是我们身边那个最靠谱的同事吗？从不甩锅，从不喊累，需求来了就接，bug来了就修，像一台永动机。\n\n**可人是血肉做的，不是机器。**\n\n**二、那些被我们忽略的身体信号**\n\n去年体检，我身边三个同事查出了甲状腺结节，两个脂肪肝，一个心律不齐。大家拿着报告互相调侃：\"没事，程序员标配。\"\n\n真的没事吗？\n\n那位程序员倒在浴室里，脸紫得发黑。医生说可能是心源性猝死。这种死亡往往没有预兆，或者说，**我们把预兆都当成了\"太累了，睡一觉就好\"**。\n\n胸闷？肯定是久坐导致的。  \n\n头疼？大概是没睡好。  \n\n眼前发黑？低血糖吧，吃点东西就行。\n\n我们太擅长给自己找借口了，因为项目要上线，因为需求要变更，因为\"这个bug今晚必须修完\"。\n\n可你有没有想过，那个bug明天修，世界不会毁灭。但你倒下了，你的世界就塌了。\n\n**三、那个\"再拼几年\"的幻觉**\n\n逝者家属提到，他本打算\"再干三年合同期结束，拿平时积攒的钱回湖南陪父母\"。\n\n这句话像根刺，扎得人心疼。\n\n我们总以为来日方长。等这个项目结束，等股票解禁，等房贷还完，等孩子大一点......我们给自己画了一个又一个饼，却忘了生命不是无限循环的代码，不能回滚，不能debug。\n\n之前在网上认识一个前辈，42岁，技术大牛，年薪百万。去年心梗，支架装了三个。\n\n出院后他发了一条朋友圈：\"以前觉得996是奋斗，现在觉得能正常拉屎都是幸福。\"\n\n黑色幽默，但字字泣血。\n\n**四、公司可以换你，家人不能**\n\n这件事发生后，网上有很多讨论。有人在说公司责任，有人在说行业环境，有人在说赔偿金额。\n\n这些都很重要，但我想说说另一个角度。\n\n那位程序员在公司六年，从29岁到36岁，把最好的年华都留在了工位上。公司说会妥善处理善后，有商业保险，有安置金。\n\n可对于他的父母来说，这些换不回那个儿子。\n\n我们这一代人，太习惯用\"有用\"来衡量自己。代码写得漂亮，KPI完成得漂亮，升职加薪快，就是有价值。\n\n**但你对家人的价值，从来不需要用工资条来证明。**\n\n你活着，对他们来说就是全部的意义。**人不是老了才会死，而是随时都会死。**\n\n**五、写给你们，也写给我自己**\n\n写到这里，我想给自己，也给看到这篇文章的同行们，列几个小建议。不是什么养生鸡汤，都是血泪教训：\n\n**第一，学会\"自私\"一点。**\n\n需求做不完就做不完，会议不参加就不参加。你的身体不是公司的资产，是你自己的。\n\n那个总让你加班的领导，不会在你手术同意书上签字。\n\n**第二，定期体检，认真看报告。**\n\n不要像对待测试环境的bug一样对待体检异常项。那些红色箭头，是身体在报警。\n\n**第三，培养一个与工作无关的爱好。**\n\n钓鱼、跑步、打游戏都行。人需要一些\"无用\"的时间，来证明自己是活着的，而不只是运转的。\n\n**第四，给家里打个电话。**\n\n别等到\"等忙完这阵\"。父母老了，等不起。\n\n**最后**\n\n那位程序员走后，他工位上的多肉植物大概还在，代码仓库里还有他写的注释，只是那个位置再也不会亮灯到深夜了。\n\n公司会招新人，项目会继续跑，世界照常运转。\n\n**只有那个出租屋的浴室，和湖南某个家庭的年夜饭，永远缺了一个人。**\n\n所以啊，今晚早点下班吧。去吃点好的，给爸妈打个电话，好好睡一觉。\n\n**你写的代码很重要，但你自己，更重要。**\n\n\n---\n\n> 本文转载自：[www.cnblogs.com](https://www.cnblogs.com/xiezhr/p/19657470)',NULL,'published',14,'2026-03-03 22:18:28','2026-03-03 22:18:28'),(25,5,'Cookie，Session，Token，JWT都是些什么？什么情况下用什么？','[一、它们的分类](#classification)  \n[二、各种方案的实现](#realize)  \n[三、企业主流的三种方案对比](#main)\n\n### 一、它们的分类\n![在这里插入图片描述](https://iblog-forum.oss-cn-beijing.aliyuncs.com/crawled/1dc869fc-79bd-4878-b983-a31254dddc86.png)  \n\n而Token,又称为令牌，又分为三种：\n\n1. Seesion ID:属于引用型\n2. Opaque Token：属于引用型\n3. JWT：属于自包含型，自身就携带证明自己身份的信息，最大的好处是后端是无状态的(内存和数据库不需要存储信息)  \n   ![在这里插入图片描述](https://iblog-forum.oss-cn-beijing.aliyuncs.com/crawled/012a75db-a489-4904-af3b-782ec0af8f7b.png)\n\n### 二、各种方案的实现\n<a id=\"realize\"></a>\nHttp是无状态的，也就是说前一次请求和后一次请求是完全独立的，当用户前一次请求登录后，再次请求该如何维持登录状态呢？\n\n以下针对该问题的各种方案，介绍它们的实现以及优缺点：\n\n![在这里插入图片描述](https://iblog-forum.oss-cn-beijing.aliyuncs.com/crawled/0fe6f291-e472-4c3f-8453-bcf12b6f9ad5.png)  \n**第一** ，如果不使用任何手段，那么只能像上图所示：**第一次**请求到后端时输入用户名和密码，然后后端判断正确，将用户名和密码返回给前端，接下来每一次请求前端都携带该用户名和密码保持登录的状态。毫无疑问，此方案不安全\n\n**第二**，使用cookie。第一次请求到后端时输入用户名和密码，然后后端判断正确，将用户名返回给前端，接下来每一次请求前端都携带该用户名在请求头的cookie中，然后后端解析cookie，得到用户名，被动地根据用户名以维持登录的状态。因为cookie保存在前端，用户可以直接篡改cookie的信息，比如将张三(非VIP)改为李四(VIP)，仍有安全问题。\n\n#### 企业常用方案1\n**第三**，使用cookie和session。第一次请求到后端输入用户名和密码，然后后端判断正确，将该用户需要的相关信息(可以是对象,故可以存储该用户的很多信息)存储在后端内存中，然后返回一个sessionID给前端，后续前端每次自动在Header的cookie中携带sessionID，后端就拿着这个sessionID去内存中找。\n\n##### 该方案解决了只使用cookie导致的安全问题\n1. sessionID是一长串随机、无意义的字符串，用户难以猜测有效的sessionID\n2. sessionID保存在服务端，难以篡改\n\n**优点：**\n1. 有现成的框架，浏览器自动搬运，无需手动写代码去设置Header\n2. 失效策略简单，直接在内存中删除即可\n\n**问题：**\n1. cookie的默认大小4kb\n2. 用户可以禁用cookie\n3. 跨域问题。连接后端的还有小程序端，安卓端，苹果端，就会有跨域，而cookie不能跨域传播\n4. 服务器集群问题。因为session只保存在某一台服务器中，当服务器集群部署时，前端请求可能被负载均衡到另一台服务器中，此时该服务器未保存该sessionID，就需要重新登录\n5. 后端有状态。后端存储大量session，难以水平扩展\n\n**适用场景：**\n简单单体项目\n\n#### 企业常用方案2\n**第四**，使用Opaque Token + Redis。第一次请求到后端输入用户名和密码，然后后端判断正确，将该用户需要的相关信息(可以是对象,故可以存储该用户的很多信息)存储在Redis中，然后返回一个自己生成的随机字符串（可以是UUID）给前端，后续前端每次自动在Header的Authorization属性中携带该随机字符串，后端就拿着这个字符串去Redis中找。\n\n**优点：**\n1. 解决了服务器集群的问题，因为信息存在Redis中，每台服务器验证的时候是去Redis验证的\n2. 失效策略简单，直接在Redis中删除即可\n3. 摆脱了cookie的问题\n\n**问题：**\n1. 没有现成的框架，需手动实现所有流程\n2. 强烈依赖Redis高可用，一旦Redis挂掉，整个服务都瘫痪\n\n#### 企业常用方案3\n**第五**，使用JWT，让后端彻底无状态。前两个方案都需要在后端存储信息，此方案中，传递的Token(JWT)自身就携带信息，好比身份证。\n\n我们先来看看JWT的数据结构：\n\n![在这里插入图片描述](https://iblog-forum.oss-cn-beijing.aliyuncs.com/crawled/b8a37a35-107e-43fb-946b-4f390cfb9b36.png)\n\n* Header：存储加密算法和Token的类型\n* Payload：需要传递的数据就存储在此处。存储图中的7个属性，可加上自己定义的属性。  \n  时间线 iat-\\>nbf-\\>exp  \n  jti JWT的唯一标识\n* Signature：解决传递的安全问题。\n\n**需要注意的是Header和Payload是采用的Base64URL编码方式，即可以编码和反编码\nSignature是采用的加密，即不可被解密**\n\n现在我们来看看JWT是怎么生成和验证的？\n\n后端生成JWT：首先根据信息生成Header和Payload，然后将他们进行Base64URL编码，以\'.\'拼接得到一个字符串(这里标记为str)。接着就是生成Signature的过程，将str根据加密算法和密钥(只有服务端自己知道)加密，得到一个字符串(这里标记为oldstr)，然后再以\'.\'拼接得到最终的JWT。形式类如eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1c2VyX2lkIjoxMjMsInVzZXJuYW1lIjoiemhhbmdzYW4iLCJleHAiOjE3MTAwMDAwMDB9.xxxx\n\n将JWT返回给前端，小程序端...，以后每次请求都携带JWT。\n\n后端验证JWT：拿到一段JWT\n\n* 根据\'.\'拆分JWT为Header、Payload、Sigture三部分\n* Base64URL解码Header和Payload，获取加密算法和过期时间\n* 用相同的密钥和加密算法，重新计算Header+Payload的签名，与JWT中的Signature对比\n* 同时检查Payload的exp字段，确认未过期\n* 如果计算出来的Signature和传递的Signature一样，则通过\n* 处理Payload中的数据，处理请求\n\n**优点：**\n1. 微服务架构下，一次解析JWT，多次运用JWT中Payload中的数据\n2. 没有服务器集群以及跨域的问题\n3. 有现成的框架\n\n**问题：**\n1. 令牌不可失效，只能等过期。因为后端是无状态的，\"只认令牌不认人\"，好比你给一个人发了一个游乐园的7天游玩票，但是第二天他的票掉了被别人捡到了，那么无法阻止那个人进入\n2. 当JWT中信息过多，需消耗大量流量传递\n\n**JWT扩展方案：**\n使用双令牌+Refresh Token的Redis白名单以解决令牌不可失效的问题。事实上其实添加此解决方案已经绕回了有状态，适合于对JWT携带信息的优点的强需求场景\n\n* 使用双令牌+Refresh Token的Redis白名单：一个短期令牌15分钟(Access Token)，一个长期令牌7天(Refresh Token)存储在Redis白名单。  \n\n  当短期令牌过期，就去Redis查询Refresh Token，在白名单中且没过期则分发一个新Access Token  \n\n  当需要失效时，只需在Redis白名单中删除Refresh Token，那么该非法用户就只能使用15分钟的Access Token了，下次再请求刷新时因为Redis白名单没有就失败了\n\n* 在Redis中存储短期令牌黑名单：如果安全性需强保证，比如金融场景，则在Redis白名单中删除Refresh Token时，同时把相应的Access Token加入Redis黑名单，那么15分钟都使用不了了。这个会牺牲高性能，因为每次使用Access Token时都要去Redis看看是不是黑名单里面的\n\n### 三、企业主流的三种方案对比\n<a id=\"main\"></a>\n![在这里插入图片描述](https://iblog-forum.oss-cn-beijing.aliyuncs.com/crawled/df1f9e6c-f683-49c3-b9b3-af6b0e959a41.png)\n\n\n---\n\n> 本文转载自：[blog.csdn.net](https://blog.csdn.net/w_shixian/article/details/158805424?spm=1000.2115.3001.10524)',NULL,'published',38,'2026-03-12 19:27:31','2026-03-12 19:27:31');
