INSERT INTO `questions` VALUES (11,2,'single','Java中哪个关键字用于定义类？','[\"A. function\",\"B. class\",\"C. def\",\"D. struct\"]','\"B\"','Java使用class关键字定义类',0),(12,2,'single','下列哪个不是Java的基本数据类型？','[\"A. int\",\"B. boolean\",\"C. String\",\"D. double\"]','\"C\"','String是引用类型，不是基本数据类型',1),(13,2,'multiple','以下哪些是Java的访问修饰符？','[\"A. public\",\"B. private\",\"C. static\",\"D. protected\"]','[\"A\",\"B\",\"D\"]','public、private、protected是访问修饰符，static是非访问修饰符',2),(14,2,'multiple','以下哪些是面向对象的特性？','[\"A. 封装\",\"B. 继承\",\"C. 编译\",\"D. 多态\"]','[\"A\",\"B\",\"D\"]','面向对象三大特性：封装、继承、多态',3),(15,2,'judge','Java是一种面向对象的编程语言',NULL,'true','Java是纯面向对象的编程语言',4),(16,2,'judge','Java中的数组长度可以动态改变',NULL,'false','Java数组一旦创建，长度固定不可变',5),(17,2,'short','请简述Java中抽象类和接口的区别',NULL,'\"1. 抽象类可以有构造方法，接口不能；2. 抽象类可以有普通成员变量，接口只能有常量；3. 一个类只能继承一个抽象类，但可以实现多个接口；4. 抽象类可以有非抽象方法，接口的方法默认是抽象的（Java8后可以有default方法）\"','抽象类更适合作为基类提供通用实现，接口更适合定义行为规范',6),(18,2,'short','什么是Java的垃圾回收机制？',NULL,'\"Java的垃圾回收（GC）是JVM自动管理内存的机制，它会自动识别和回收不再被引用的对象所占用的内存空间，程序员无需手动释放内存。\"','GC主要算法包括标记-清除、复制、标记-整理等',7),(19,2,'single','Java程序的入口方法是？','[\"A. start()\",\"B. main()\",\"C. run()\",\"D. init()\"]','\"B\"','Java程序从main方法开始执行',8),(20,2,'judge','接口中的方法默认是public abstract的',NULL,'true','接口中的方法默认是public abstract修饰',9),(1689,15,'judge','软件开发要遵循软件工程原则。',NULL,'true','软件工程原则为软件开发提供了系统化、规范化的指导。',0),(1690,15,'single','软件工程是指导软件开发的工程学科,其核心三要素是( )','[\"A) 建模、方法和过程\",\"B) 建模、方法和工具\",\"C) 定义、方法和过程\",\"D) 方法、工具和过程\"]','\"D\"','软件工程三要素是方法、工具和过程，三者相互依赖、相互支持。',1),(1691,15,'single','软件可分为系统软件、支撑软件与应用软件,下列选项中属于支撑软件的是()','[\"A) 数据库管理系统\",\"B) 携程\",\"C) 程序开发环境\",\"D) Linux操作系统\"]','\"C\"','支撑软件是协助开发与维护的工具与环境，如开发环境、测试工具等。',2),(1692,15,'single','开源软件以源代码开放、自由传播为核心特征,下列选项中不属于开源软件的是( )','[\"A) Ubuntu\",\"B) MySQL\",\"C) Junit\",\"D) Office\"]','\"D\"','Office是商业闭源软件，其余均为开源软件。',3),(1693,15,'single','20世纪60年代以来,软件危机成为行业面临的重要挑战,以下哪项不属于软件危机的表现?( )','[\"A) 软件需求增长迅速且容易满足\",\"B) 软件开发成本和进度难以控制\",\"C) 软件维护困难\",\"D) 软件质量难以保证\"]','\"A\"','软件危机的表现之一是需求增长迅速且难以满足，而非容易满足。',4),(1694,15,'single','CASE工具功能丰富,可大幅提升开发效率,下列哪个选项不属于CASE工具的主要功能( )','[\"A) 项目管理\",\"B) 自动生成代码\",\"C) 替代开发人员完成所有工作\",\"D) 辅助进行需求分析\"]','\"C\"','CASE工具辅助开发，但不能完全替代开发人员完成所有工作。',5),(1695,15,'multiple','程序质量直接决定软件可用性与维护成本,下列选项中属于程序质量保证方法的是( )','[\"A) 程序设计方法\",\"B) 程序编码风格\",\"C) 程序测试\",\"D) 代码重用\"]','[\"A\",\"B\",\"C\",\"D\"]','程序设计方法、编码风格、测试和代码重用都是程序质量保证的重要手段。',6),(1696,15,'multiple','开源软件生态的发展离不开多方推动,下列选项中属于开源软件推动者的是()','[\"A) 软件开发者\",\"B) IT企业\",\"C) 政府组织\",\"D) 开源组织\"]','[\"A\",\"B\",\"C\",\"D\"]','开源软件的生态由开发者、企业、政府、开源组织等多方共同推动。',7),(1697,15,'single','SonarQube是主流的代码质量分析工具,下列不属于其可分析的质量问题的是( )','[\"A) 是否违反编码规则\",\"B) 是否存在重复代码\",\"C) 软件测试覆盖率\",\"D) 判断软件体系结构设计是否合理\"]','\"C\"','SonarQube主要用于静态代码分析，包括编码规则、重复代码等，但不直接判断体系结构设计是否合理。',8),(1698,15,'judge','确保程序质量是编码的首要工作。',NULL,'true','编码过程中应始终关注程序质量，避免引入缺陷。',9),(1699,15,'judge','程序本质上是对数据的处理。',NULL,'true','程序的核心功能是输入数据、处理数据、输出结果。',10),(1700,15,'multiple','作坊式软件开发以小规模、非标准化为特点,存在诸多待解决问题,下列选项中属于作坊式软件开发需要解决的问题的是( )','[\"A) 缺乏系统化方法\",\"B) 缺乏文档管理\",\"C) 质量难以保证\",\"D) 进度难以控制\"]','[\"A\",\"B\",\"C\",\"D\"]','作坊式开发常缺乏系统性方法、文档、质量控制与进度管理。',11),(1701,15,'single','CASE工具是软件开发的重要支撑,其主要用于支持哪个阶段的软件工程活动?( )','[\"A) 需求分析\",\"B) 测试与维护\",\"C) 编码实现\",\"D) 整个软件生命周期\"]','\"D\"','CASE工具可支持从需求、设计、编码、测试到维护的全过程。',12),(1702,15,'single','在质量分类中,以下选项中,不属于程序外部质量要求的是( )','[\"A) 正确性\",\"B) 可维护性\",\"C) 可靠性\",\"D) 友好性\"]','\"B\"','可维护性属于内部质量属性，其余属于外部质量属性。',13),(1703,15,'single','人工审查代码是传统代码质量管控手段,下列不属于人工审查代码特点的是()','[\"A) 自动化程度高\",\"B) 难发现深层次问题\",\"C) 难全面系统性分析\",\"D) 效率低\"]','\"A\"','人工审查依赖人工，自动化程度低。',14),(1704,15,'judge','软件项目的失败不等同于软件的失败。',NULL,'true','项目失败可能因管理、资源等问题，软件本身可能仍有价值或可复用。',15),(1705,15,'single','软件是生活中不可或缺的组成部分,下列选项中,不属于软件构成部分的是( )','[\"A) 环境\",\"B) 数据\",\"C) 文档\",\"D) 程序\"]','\"A\"','软件包括程序、数据和相关文档，环境属于外部因素。',16),(1706,15,'judge','编写文档的目的之一是为了发现问题。',NULL,'true','编写文档有助于梳理逻辑、发现不一致或遗漏的问题。',17),(1707,15,'judge','软件开发是一项工程。',NULL,'true','软件开发需遵循工程化方法，系统化、规范化地进行。',18),(1708,15,'single','随着技术发展,多种技术与方法推动软件工程不断进步,下列哪项技术或方法对软件工程的发展产生了深远影响?( )','[\"A) 瀑布模型\",\"B) 人工智能\",\"C) 面向对象编程\",\"D) 以上都是\"]','\"D\"','瀑布模型、人工智能、面向对象编程等均对软件工程发展有重要影响。',19),(1709,15,'single','为缓解软件危机,行业逐步探索标准化、工程化的开发模式,以下哪项措施有助于缓解软件危机?( )','[\"A) 忽视软件文档的编写\",\"B) 依赖个人英雄主义进行软件开发\",\"C) 引入标准化的软件开发过程\",\"D) 减少软件开发人员的数量\"]','\"C\"','引入标准化的开发过程有助于提升可控性、质量和效率。',20),(1710,15,'multiple','代码重用是提升开发效率、降低成本的重要手段,下列选项中属于程序代码重用的是( )','[\"A) 软构件重用\",\"B) 代码片段重用\",\"C) 类重用\",\"D) 函数重用\"]','[\"A\",\"B\",\"C\",\"D\"]','代码重用可体现在软构件、片段、类、函数等多个层面。',21),(1711,15,'single','代码质量分析是保障软件可靠性的关键环节,下列不属于代码质量分析常用方法的是( )','[\"A) 程序测试\",\"B) 自动生成代码\",\"C) 自动化分析\",\"D) 人工审查\"]','\"B\"','自动生成代码属于开发辅助手段，不是质量分析方法。',22),(1712,15,'multiple','McCall软件质量模型从用户与开发视角构建质量体系,下列选项中属于该模型内容的是( )','[\"A) 产品设计\",\"B) 产品运行\",\"C) 产品转移\",\"D) 产品修正\"]','[\"B\",\"C\",\"D\"]','McCall模型从产品运行、产品转移、产品修正三个维度定义质量属性。',23),(1713,15,'judge','软件开发等于软件创作加软件生产。',NULL,'true','软件开发是创作（设计）与生产（实现、测试）的结合。',24),(1714,15,'judge','源代码可直接运行。',NULL,'false','源代码需经编译或解释才能执行。',25),(1715,15,'single','开源软件在开发与使用中具有诸多优势,下列选项中不属于开源软件优势的是( )','[\"A) 源代码自由传播\",\"B) 免费使用\",\"C) 无法对软件进行修改\",\"D) 快速开发构建系统\"]','\"C\"','开源软件允许用户自由修改源代码，这是其核心优势之一。',26),(1716,15,'judge','软件质量是软件的生命线。',NULL,'true','质量直接影响软件的可用性、可靠性和用户满意度。',27),(1717,15,'judge','软件是产品。',NULL,'true','软件是一种逻辑产品，具有使用价值和经济价值。',28),(1718,15,'single','软件工程通过核心原则保障开发质量与效率,以下哪项不属于软件工程的核心原则?( )','[\"A) 模块化\",\"B) 抽象\",\"C) 一致性\",\"D) 最大化代码量\"]','\"D\"','软件工程强调简洁、高内聚、低耦合，而非盲目追求代码量。',29),(1719,16,'multiple','需求分析工程师确定软件需求优先级时,可参考哪些因素？','[\"A) 需求的规模大小\",\"B) 需求对应的功能点数量\",\"C) 用户对需求的紧急程度\",\"D) 需求对系统核心价值的贡献度\"]','[\"C\",\"D\"]','需求优先级通常基于用户紧急程度和对核心价值的贡献，而非规模或功能点数量。',0),(1720,16,'single','常见的软件需求获取方法有哪些？','[\"A) 向软件利益相关方发放业务调查问卷\",\"B) 与软件利益相关方进行面谈或召开需求会议\",\"C) 开发人员主动构思软件需求\",\"D) 开发人员亲身体验业务流程\"]','\"A,B,C,D\"','需求获取方法多样，包括问卷、面谈、会议、构思、体验等。',1),(1721,16,'judge','开发人员与客户共同创建用例,目的是帮助软件团队了解有多少类型的最终用户会使用这些功能。',NULL,'false','共同创建用例的主要目的是理解用户与系统的交互过程，而非统计用户类型数量。',2),(1722,16,'single','需求获取过程中,下列哪项不属于常见难题？','[\"A) 用户存在认知偏差\",\"B) 用户需求频繁变化\",\"C) 用户过度干预需求定义\",\"D) 对专业知识理解存在障碍\"]','\"B\"','用户需求变化是常态，但不属于“难题”范畴；认知偏差、过度干预、专业障碍更常见。',3),(1723,16,'judge','在用户需求分析阶段观察用户手工操作流程,并非为了模拟该流程,而是为了获取第一手资料,并从中提取有价值的需求。',NULL,'true','观察的目的是理解实际业务流程，提取需求，而非直接模拟。',4),(1724,16,'judge','UML 行为模型中的交互图,通常用于描述单个用例的典型场景。',NULL,'true','交互图（如顺序图、通信图）常用于描述用例的具体交互场景。',5),(1725,16,'judge','后期需求分析阶段聚焦于构建系统解决方案,因此以软件系统为核心,重点分析系统的内部功能及与外部环境的交互,是对系统功能细节的深入剖析。',NULL,'true','后期分析更关注系统内部结构、交互与实现细节。',6),(1726,16,'single','下列不属于UML行为模型的是？','[\"A) 顺序图\",\"B) 状态图\",\"C) 用例图\",\"D) 类图\"]','\"D\"','类图属于结构模型，而非行为模型。',7),(1727,16,'judge','用例的内容仅包含正常流程,不涵盖异常流程。',NULL,'false','完整的用例应包括正常流程、异常流程和替代流程。',8),(1728,16,'single','软件原型作为高效的需求收集手段,其核心优势体现在？','[\"A) 易于挖掘用户遗漏或难以表述的“隐性”需求\",\"B) 能在大规模用户群体中快速收集需求信息及统计结果\",\"C) 可尽早向用户展示系统的外观与行为特征\",\"D) 便于探讨特殊场景及异常处理的细节\"]','\"A\"','原型能帮助用户直观感受系统，从而发现未明确表达或遗漏的需求。',9),(1729,16,'single','需求规格说明书主要描述了？','[\"A) 系统的功能、性能及相关约束条件\",\"B) 软件体系结构的组成元素\",\"C) 系统仿真所需的时间\",\"D) 各指定系统的具体实现方式\"]','\"A\"','需求规格说明书的核心是定义系统应具备的功能、性能及约束。',10),(1730,16,'judge','成功的需求获取工作,不仅要求每一次具体的获取行为有效执行,还需妥善处理多次获取行为之间的关联。',NULL,'true','需求获取是一个迭代过程，需要保持一致性、可追溯性和整体协调。',11),(1731,16,'single','在需求分析过程中,如何确保所有相关方对需求达成共识？','[\"A) 编写详细的技术文档\",\"B) 延长开发时间以减少误解\",\"C) 组织需求评审会议\",\"D) 依靠测试发现需求不一致问题\"]','\"C\"','需求评审是各方沟通、确认需求并达成共识的关键活动。',12),(1732,16,'single','下列哪项不属于需求评审的目标？','[\"A) 发现并减少需求中的错误\",\"B) 提升需求的质量\",\"C) 验证需求的准确性\",\"D) 设计测试用例\"]','\"D\"','设计测试用例是测试阶段的任务，不是需求评审的直接目标。',13),(1733,16,'single','使用 UML(统一建模语言)开展需求分析时,哪种图表最适合用于用例分析的交互模型？','[\"A) 顺序图\",\"B) 状态图\",\"C) 用例图\",\"D) 类图\"]','\"A\"','顺序图常用于描述用例中对象之间的交互顺序。',14),(1734,16,'judge','软件需求分析的关键在于为现实问题构建模型,即问题域建模。',NULL,'true','需求分析的核心是理解并建模问题域，明确系统要解决什么问题。',15),(1735,16,'single','可行性分析是系统开发初期的关键论证工作,它决定着系统是否需要开发,因此必须给出什么样的结论？','[\"A) 技术是否可行\",\"B) 经济是否可行\",\"C) 操作是否可行\",\"D) 明确的是否可行的结论\"]','\"D\"','可行性分析必须给出明确的是否可行的结论，以决定项目是否启动。',16),(1736,16,'multiple','获取软件需求的难点主要体现在哪些方面？','[\"A) 软件利益相关方缺乏领域知识,导致无法提出有效需求\",\"B) 软件利益相关方无法清晰表述需求内容\",\"C) 软件利益相关方未投入足够时间整理与构思需求\",\"D) 软件利益相关方难以区分需求与非需求\"]','[\"A\",\"B\",\"C\",\"D\"]','需求获取的难点包括知识缺失、表述不清、投入不足、需求边界模糊等。',17),(1737,16,'single','软件需求分析的任务不包含？','[\"A) 采用结构化程序设计方法\",\"B) 构建系统的逻辑模型\",\"C) 保障系统的可靠性与安全性\",\"D) 对问题进行拆解\"]','\"A\"','结构化程序设计方法是设计阶段的任务，不属于需求分析范畴。',18),(1738,16,'single','基于 UML 的软件需求模型,通常可能包含哪些UML图？','[\"A) 用例图、顺序图、类图、部署图\",\"B) 用例图、顺序图、类图、构件图\",\"C) 用例图、通信图、类图、部署图\",\"D) 顺序图、类图、状态图\"]','\"D\"','需求模型常用顺序图、类图、状态图等描述行为与结构。',19),(1739,16,'multiple','获取软件需求需开展哪些方面的工作？','[\"A) 对收集的需求进行分析,排查其中的不一致与矛盾之处\",\"B) 尽可能清晰地描述每一项已获取的需求\",\"C) 开展业务调研,明确软件开发的目标与动机,即确定软件需解决的问题\",\"D) 运用多种方式与手段,从软件利益相关方处梳理并构思需求\"]','[\"B\",\"C\",\"D\"]','需求获取包括明确目标、运用多种手段获取、清晰描述需求；分析不一致属于后续分析活动。',20),(1740,16,'judge','需求确认过程中,评审需求模型的目的是确保其技术可行性。',NULL,'false','需求评审的主要目的是确认需求是否正确、完整、一致，而非技术可行性（后者属于可行性分析）。',21),(1741,16,'single','UML 中的状态图主要用于构建？','[\"A) 用户视图\",\"B) 系统结构\",\"C) 数据流程\",\"D) 对象的状态变化\"]','\"D\"','状态图用于描述对象在其生命周期内状态的变化。',22),(1742,16,'multiple','软件需求分析的任务包括？','[\"A) 问题识别\",\"B) 分析与综合\",\"C) 编制需求文档\",\"D) 需求确认\"]','[\"A\",\"B\",\"C\",\"D\"]','需求分析包括识别问题、分析综合、编制文档、确认需求等任务。',23),(1743,16,'single','系统需求开发的最终成果会记录在？','[\"A) 前景与范围文档\",\"B) 可行性研究报告\",\"C) 需求规格说明书\",\"D) 用户需求说明书\"]','\"C\"','需求规格说明书是需求开发阶段的主要交付物。',24),(1744,16,'single','经济可行性研究的核心内容包含？','[\"A) 效益分析\",\"B) 风险分析\",\"C) 开发工具\",\"D) 开发过程\"]','\"A\"','经济可行性主要关注成本与效益分析。',25),(1745,16,'single','采用观察法收集需求的主要原因是？','[\"A) 用户数量较多\",\"B) 客户需求变化频繁\",\"C) 事件具有情景关联性\",\"D) 存在默认未明确的知识\"]','\"C\"','观察法适用于理解与具体场景紧密相关的业务流程。',26),(1746,16,'judge','单个用例仅描述系统的部分功能,将所有用例按一定关系组织形成用例模型,即可完整描述系统的全部功能。',NULL,'true','用例模型通过一组用例共同描述系统的完整功能范围。',27),(1747,16,'single','软件需求分析的核心工作是？','[\"A) 确定软件开发各阶段适用的工具\",\"B) 为原始问题及目标软件构建物理模型\",\"C) 清晰界定软件的功能需求与非功能需求\",\"D) 既要明确目标系统“做什么”,也要解决“怎么做”问题\"]','\"C\"','需求分析的核心是明确系统“做什么”，即功能与非功能需求。',28),(1748,16,'judge','应用型软件分析阶段的核心目标是明确用户使用软件的原因与目的,找出软件需解决的问题,理解应用环境中的领域知识,确保功能的模拟性。',NULL,'true','应用型软件分析重在理解用户动机、问题域和领域知识，确保功能贴合实际。',29),(1749,17,'single','在敏捷开发方法体系中，不属于极限编程(XP)核心编程习惯的是( )','[\"A) 以测试驱动开发流程(先写测试用例,再开发功能)\",\"B) 强调代码集体所有，团队成员可共同修改优化代码\",\"C) 对团队成员进行定期绩效评估,以评估结果划分工作任务\",\"D) 通过持续集成频繁合并代码，及时发现集成问题\"]','\"C\"','极限编程的核心实践包括TDD、集体代码所有、持续集成等，但强调合作与团队自主管理，而非定期的个人绩效评估与任务分配。',0),(1750,17,'single','瀑布模型又称经典生命周期模型，其核心特征是( )','[\"A) 和迭代式开发的模型\",\"B) 增量式交付的模型\",\"C) 线性顺序推进的模型\",\"D) 重点强调设计环节的模型\"]','\"C\"','瀑布模型的核心特征是阶段间严格的、线性的顺序关系，各阶段依次进行，通常没有回溯。',1),(1751,17,'judge','软件生存周期模型是对软件从需求提出、开发实现、部署运行到退役消亡的全生命周期中，所有过程、活动与任务的结构化组织与规范化定义。( )',NULL,'true','软件生存周期模型定义了软件开发、运行、维护直至废弃的全过程中应遵循的流程框架和活动规范。',2),(1752,17,'single','非功能性需求是软件需求的重要组成部分，其包含的需求类型有( )','[\"A) 软件性能需求\",\"B) 软件结构需求\",\"C) 软件质量需求\",\"D) 软件行为需求\"]','\"A,C\"','非功能性需求主要描述系统的质量属性（如性能、可靠性、安全性）和约束条件，而非具体的功能行为。软件结构需求属于设计层面的约束，软件行为需求属于功能需求范畴。',3),(1753,17,'single','SCRUM方法中，敏捷框架中，时间周期较短的迭代开发单元被称为( )','[\"A) Phases\",\"B) Sprints\",\"C) Milestones\",\"D) Steps\"]','\"B\"','在Scrum框架中，Sprint（冲刺）是一个固定时长的迭代周期，通常为1-4周，用于完成一组可交付的产品增量。',4),(1754,17,'single','在软件需求体系中，( )是从技术、业务、用户体验等多维度对系统施加的约束条件，体现了应用场景对软件质量与特性的额外要求。','[\"A) BARR\",\"B) 功能需求\",\"C) 业务需求\",\"D) 非功能需求\"]','\"D\"','非功能需求是对系统质量属性（如性能、可靠性、可用性等）以及各种约束（如技术、合规、业务规则）的要求，它定义了系统运行的“好坏”标准。',5),(1755,17,'multiple','下列关于瀑布模型的表述，正确的有( )','[\"A) 瀑布模型仅允许获取方(如客户)与用户参与需求阶段和运行维护阶段,设计、编码、测试等中间阶段完全由开发团队独立完成，不允许外部参与\",\"B) 瀑布模型对需求的稳定性要求极高,需在项目初始阶段就明确、完整地定义所有需求，避免后续需求变更对项目进度造成大幅影响\",\"C) 瀑布模型的核心特点之一是“文档驱动”，每个开发阶段结束后需产出标准化文档\",\"D) 瀑布模型必须严格按照“需求→设计→编码→测试→集成→维护”的固定路径推进，任何情况下都无法从后续阶段回溯到前序阶段修正问题\"]','[\"B\",\"C\"]','瀑布模型强调需求早期确定性和文档驱动，但并非完全排斥外部参与中间阶段（如设计评审），也允许在严格管控下进行有限回溯。A和D的说法过于绝对。',6),(1756,17,'multiple','下列实践方法中，属于极限编程(XP)核心有效实践的有( )','[\"A) 短交付周期\",\"B) 结对编程\",\"C) 持续集成\",\"D) 代码集体所有\"]','[\"A\",\"B\",\"C\",\"D\"]','极限编程（XP）的核心实践包括短迭代周期（短交付）、结对编程、持续集成、集体代码所有权、测试驱动开发（TDD）等，旨在提升质量与响应变化的能力。',7),(1757,17,'single','在一套分层数据流图(DFD)中，若某一层图包含 N 个加工(数据处理环节)，则该层图允许包含的子图数量范围是( )。','[\"A) 0-N\",\"B) 1-N\",\"C) 0\",\"D) 1\"]','\"B\"','在分层数据流图中，父图中的一个加工（处理过程）如果需要进一步分解，则应该对应且仅对应一张子图。因此，包含N个加工的图，其子图数量最少为1（至少一个加工被分解），最多为N（所有加工都被分解）。',8),(1758,17,'single','在需求工程领域，“涉众(Stakeholder)”的定义是( )','[\"A) 负责项目统筹的管理人员\",\"B) 负责验证功能的测试人员\",\"C) 参与软件编码的开发人员\",\"D) 所有可能影响软件开发方向或受软件运行结果影响的个人与团体\"]','\"D\"','涉众（或干系人）是一个广泛的概念，包括任何与系统有利益关系或会受到系统影响的个人、团体或组织，如用户、客户、开发者、管理者、监管机构等。',9),(1759,17,'multiple','在典型的敏捷开发团队中，常见的核心角色包括( )','[\"A) 项目经理(Project Manager):负责统筹项目资源,协调跨团队沟通，把控项目整体进度与风险\",\"B) 开发团队(Development Team):跨职能团队，包含开发、测试、设计等成员，共同负责需求的实现与交付\",\"C) 敏捷教练(或 Scrum Master):负责引导团队遵循敏捷原则,移除团队协作障碍,保障敏捷流程有效落地\",\"D) 产品负责人(Product Owner):负责梳理需求优先级,维护产品待办列表(Backlog),代表用户与业务方利益\"]','[\"A\",\"B\",\"C\",\"D\"]','在敏捷团队中，角色划分强调协作与责任。产品负责人负责业务价值，Scrum Master负责过程引导，开发团队负责交付，而传统项目经理的职责可能在敏捷环境中被拆分或整合。题目描述覆盖了敏捷环境中常见的角色定义。',10),(1760,17,'single','下列活动中，不属于需求工程核心环节的是( )','[\"A) 需求规格说明\",\"B) 编码实现\",\"C) 需求分析\",\"D) 需求获取\"]','\"B\"','需求工程主要包括需求获取、需求分析、需求规格说明、需求验证等活动。编码实现是软件开发阶段的任务，不属于需求工程的范畴。',11),(1761,17,'single','数据流图 (DFD) 是软件需求分析阶段常用的建模工具，下列绘图方法中，属于行业主流实践的是 ( )。','[\"A) 全是\",\"B) 自顶向下逐层分解\",\"C) 自底向上逐步汇总\",\"D) 两者都有\"]','\"B\"','数据流图（DFD）的主流绘制方法是“自顶向下，逐层分解”。即从顶层上下文图开始，将复杂的加工过程逐步细化成多层次的子图，以清晰地展示系统的数据流动和处理逻辑。',12),(1762,17,'judge','需求工程是所有与需求相关的处理活动的总和,主要包含需求开发和需求管理两个核心部分。( )',NULL,'true','需求工程是一个系统工程，它涵盖了从需求获取、分析、规格说明、验证（需求开发）到需求变更控制、跟踪和状态管理（需求管理）的全过程。',13),(1763,17,'single','关于螺旋模型，下列表述错误的是( )','[\"A) 开发过程划分为多轮迭代周期，每轮迭代均会产出一个可交付的软件版本\",\"B) 将软件开发活动与风险管理深度融合，通过周期性风险评估与应对实现风险管控\",\"C) 虽然原型的演化贯穿软件全生命周期，但完全不具备原型模型快速验证需求的核心特点\",\"D) 适用于规模庞大、业务逻辑复杂且风险较高的大型软件项目\"]','\"C\"','螺旋模型融合了瀑布模型的系统性和原型模型的迭代性。它的每个迭代周期都包含风险分析、原型开发、评估等环节，旨在通过快速构建原型来验证假设、规避风险，因此它恰恰具备原型模型快速验证需求的核心特点。C项说法错误。',14),(1764,17,'single','在软件需求的分类中，( )具体描述了用户使用产品时必须完成的业务任务，可通过用例模型或场景脚本进行详细说明。','[\"A) 业务需求\",\"B) 用户需求\",\"C) 非功能需求\",\"D) 功能需求\"]','\"D\"','功能需求定义了系统必须提供的具体服务或功能，即“系统能做什么”。它通常描述用户为了完成某项业务任务而与系统进行的交互，可以使用用例、用户故事或场景脚本等形式来描述。',15),(1765,17,'single','需求工程的核心目标是( )','[\"A) 通过测试验证软件功能是否满足需求\",\"B) 全面收集用户对软件的需求，并通过分析梳理形成清晰、可落地的需求文档\",\"C) 确定软件每个功能模块的具体实现逻辑\",\"D) 将需求转化为可执行的计算机代码\"]','\"B\"','需求工程的核心在于理解和定义系统需要“做什么”，而不是“怎么做”。其目标是系统化地获取、分析、记录和验证用户需求，最终形成一份完整、一致、可验证的需求规格说明，作为后续设计和开发的基础。',16),(1766,17,'single','敏捷开发方法最适配的项目类型是( )','[\"A) 团队成员数量庞大、层级复杂的项目\",\"B) 对系统安全性、可靠性、关键性有极高标准要求的项目\",\"C) 需求长期稳定且边界清晰的项目\",\"D) 需求变化频繁、范围难以早期完全确定的项目\"]','\"D\"','敏捷方法的核心优势在于应对变化和不确定性。它最适合需求不明确、易变或需要快速响应市场的项目。对于需求稳定、对形式化过程要求极高的项目（如安全关键系统），传统的计划驱动模型可能更合适。',17),(1767,17,'judge','DFD 的 0 层图通常被用来作为整个系统的功能概览图。( )',NULL,'true','在分层数据流图中，顶层图（Context Diagram，有时称为0层图）展示了系统与外部实体之间的数据交互，定义了系统的边界。而1层及以下的图则是对系统内部加工的逐层分解。0层图确实提供了最高层级的功能概览。',18),(1768,17,'judge','非功能需求无法独立存在，必须依附于功能需求。( )',NULL,'true','非功能需求（如性能、可用性、安全性）是对系统质量属性的要求，它们总是针对特定的功能或整个系统而言的。例如，“登录操作的响应时间应小于2秒”这个性能需求，就依附于“登录”这个功能需求。',19),(1769,17,'judge','敏捷开发法是以团队为核心，采用“自底向上、增量和迭代”的开发方式。( )',NULL,'false','敏捷开发强调以团队为核心，并采用“增量”和“迭代”的方式。但“自底向上”不是敏捷的典型特征。敏捷通常是从一个高层次的产品愿景或路线图开始（可视为“自顶向下”的规划），然后通过迭代增量地实现。',20),(1770,17,'single','下列需求描述中，属于性能需求的是( )','[\"A) 系统在网络中断时需自动保存用户操作数据，恢复网络后提示用户续操作\",\"B) 系统界面需符合人体工学设计，按钮尺寸、字体大小便于用户操作\",\"C) 系统需遵循 HTTPS 协议进行数据传输\",\"D) 系统需支持同时在线并发访问用户数不低于 5000 人\"]','\"D\"','性能需求定义了系统在特定条件下（如负载、数据量下）的响应速度、吞吐量、资源利用率等指标。D选项明确规定了并发用户数这一性能指标。A属于可靠性，B属于可用性/易用性，C属于安全性或约束。',21),(1771,17,'judge','软件生存周期的本质是指软件会经历“开发→上线→更新→淘汰”的周期性循环，每隔固定时间就需要推出新版本进行功能更新。( )',NULL,'false','软件生存周期描述的是软件从概念提出到最终退役的整个过程，它包括一系列阶段（如需求、设计、实现、测试、部署、维护、退役）。它不是一个固定时长的循环，更新频率取决于项目需求、市场变化和技术发展，而非固定周期。',22),(1772,17,'single','精准界定“软件系统必须实现哪些核心功能”是软件开发生命周期中( )的核心任务。','[\"A) 测试阶段\",\"B) 设计阶段\",\"C) 实现阶段\",\"D) 需求分析阶段\"]','\"D\"','需求分析阶段的主要任务就是深入理解和定义用户和系统的需求，明确系统“必须做什么”，即确定系统的核心功能和约束条件。',23),(1773,17,'single','下列对敏捷开发方法的描述，正确的是( )','[\"A) 完全不编写任何文档，仅关注代码开发\",\"B) 以可运行代码为核心交付物，优先保障功能可实现\",\"C) 高度重视过程规范与工具选型，通过标准化流程管控项目\",\"D) 将合同谈判作为核心环节，严格按合同约定推进开发\"]','\"B\"','敏捷开发的核心价值观之一是“可工作的软件高于详尽的文档”，强调通过不断交付可运行的、有价值的软件来获取反馈。但这并不意味着不写文档，而是文档应精简、有价值。B选项准确地抓住了这一核心。A、C、D都是对敏捷的误解。',24),(1774,17,'judge','当前软件需求收集过程中，普遍存在不同客户提出的需求相互矛盾，且每个客户均坚持自身需求合理的现象。( )',NULL,'true','这是需求工程中一个常见的现实挑战。不同干系人（客户、用户、管理者等）由于立场、视角、利益不同，常常提出相互冲突的需求。需求分析的一个重要任务就是识别并协调这些矛盾，达成共识。',25),(1775,17,'judge','在数据流图(DFD)中，所有外部实体共同构成软件系统的外部上下文环境；外部实体与软件系统之间的数据流即为系统与外部环境的接口，这些接口共同界定了软件系统的功能边界与数据交互范围。( )',NULL,'true','这是数据流图（DFD）的核心建模思想。顶层数据流图（上下文图）正是通过展示系统与外部实体之间的数据流，来明确系统的边界和与外界的信息交换关系。',26),(1776,17,'multiple','关于面向数据流的需求分析方法学，下列描述正确的有( )','[\"A) 在该方法学中，软件系统的功能可通过“数据对象”与“数据处理逻辑”定义，即“系统需处理哪些数据”“对这些数据执行何种操作”\",\"B) 该方法学具备全面性，既能通过数据流梳理功能需求，也能通过数据约束、处理效率要求等刻画非功能需求\",\"C) 该方法学的核心聚焦于功能需求，通过梳理数据流的产生、传递、处理、存储过程，明确软件需实现的功能，无法对非功能需求进行建模与分析\",\"D) 该方法学认为软件系统的性能可通过“数据量大小”、“数据处理速度”定义，即“处理何种数据”“处理数据的效率要求”与功能需求的定义逻辑一致\"]','[\"A\",\"C\"]','面向数据流的方法（如结构化分析）的核心是功能分解和数据流建模，它擅长描述“数据如何被处理”的功能需求（A对）。但它本身并不直接提供对非功能需求（如性能、可靠性）进行建模的图形化工具，这部分通常通过补充规格说明来描述（C对，B错）。D选项将性能需求混同为功能需求的定义逻辑，表述不准确。',27),(1777,17,'judge','需求验证是需求工程的最后一项活动。( )',NULL,'false','需求验证（确保需求规格说明正确、完整、一致）虽然是需求开发阶段的一个重要收尾活动，但需求工程还包括持续的需求管理活动，如需求跟踪、变更控制等，这些活动贯穿整个项目生命周期。因此，需求验证并非整个需求工程的“最后”一项活动。',28),(1778,18,'single','在 ES6 中，关于 `let` 和 `var` 的区别，下列描述错误的是：','[\"A. `let` 声明的变量有块级作用域， `var` 没有\",\"B. `var` 存在变量提升， `let` 不存在\",\"C. `let` 允许在同一作用域内重复声明同一个变量\",\"D. `const` 用于声明常量，一旦赋值后不能修改引用\"]','\"C\"','`let` 不允许在同一作用域内重复声明同一个变量，而 `var` 允许。选项 D 是对 `const` 的正确描述，但题干问的是 `let` 和 `var` 的区别，D项本身内容正确，但不符合比较范畴，但更直接的错误是C。',0),(1779,18,'single','下列 ES6 箭头函数的写法中，当函数体只有一行返回语句时，正确的是：','[\"A. (x) => { return x * x; }\",\"B. x => x * x\",\"C. x => { x * x }\",\"D. (x) => return x * x\"]','\"B\"','当箭头函数体只有一行且为返回值时，可以省略大括号 `{}` 和 `return` 关键字，直接写表达式即可。B正确。A语法正确但不是最简形式。C缺少`return`，会返回`undefined`。D语法错误，`return`不能出现在箭头函数简写体中。',1),(1780,18,'single','在 ES6 模块化中，使用 `export default` 导出的模块，在导入时：','[\"A. 需要使用 [ ] 包裹变量名\",\"B. 可以任意命名变量，不需要 [ ]\",\"C. 必须使用原模块定义的变量名\",\"D. 必须使用 as 语法\"]','\"B\"','`export default` 导出的模块是模块的默认导出，在导入时可以使用任意名称，且不需要使用大括号 `{}`。',2),(1781,18,'single','下列关于 ES6 解构赋值的写法，正确的是：','[\"A. `let` {a, b} = {a: 1, b: 2}\",\"B. `let` [a, b] = {a: 1, b: 2}\",\"C. `let` {a, b} = [1, 2]\",\"D. `let` (a, b) = (1, 2)\"]','\"A\"','解构赋值要求等号两边的模式匹配。A是对象解构，正确。B是数组解构用于对象，错误。C是对象解构用于数组，错误。D语法错误，不是有效的解构语法。注意：题干中 `let` 后的反引号应为笔误，应为 `let {a, b} = ...`。',3),(1782,18,'single','在 ES6 类（Class）定义中，用于初始化对象属性的方法名是：','[\"A. `init`\",\"B. `constructor`\",\"C. `main`\",\"D. `create`\"]','\"B\"','ES6 类中的 `constructor` 方法是类的构造方法，用于创建和初始化一个类的对象实例。',4),(1783,18,'single','MyBatis 中，为了防止 SQL 注入，在传递普通参数（非表名/列名）时，应优先使用：','[\"A. ${param}\",\"B. #{param}\",\"C. &{param}\",\"D. @{param}\"]','\"B\"','`#{}` 是预编译占位符，MyBatis会将其替换为 `?`，然后使用 PreparedStatement 的参数安全设置，能有效防止SQL注入。`${}` 是字符串拼接，存在SQL注入风险，通常用于动态表名、列名等非值参数。',5),(1784,18,'single','在 MyBatis 的 XML 映射文件中，根元素是：','[\"A. <configuration>\",\"B. <mapper>\",\"C. <sqlMap>\",\"D. <mybatis>\"]','\"B\"','MyBatis 映射文件（Mapper XML）的根元素是 `<mapper>`。`<configuration>` 是 MyBatis 核心配置文件的根元素。',6),(1785,18,'single','在 MyBatis 关联查询中，用于处理“多对一”或“一对一”关系的标签是：','[\"A. <collection>\",\"B. <association>\",\"C. <list>\",\"D. <map>\"]','\"B\"','`<association>` 用于处理对象间的“一对一”或“多对一”关系（一个学生对应一个班级）。`<collection>` 用于处理“一对多”或“多对多”关系（一个班级对应多个学生）。',7),(1786,18,'single','在 MyBatis 中，用于遍历集合（如实现 IN 查询）的动态 SQL 标签是：','[\"A. <if>\",\"B. <choose>\",\"C. <foreach>\",\"D. <set>\"]','\"C\"','`<foreach>` 标签用于遍历集合或数组，常用于构建 IN 条件 (`... WHERE id IN <foreach>...`) 或批量插入。',8),(1787,18,'single','MyBatis 执行插入操作时，若希望将数据库自动生成的主键回填到实体对象中，应配置：','[\"A. useGeneratedKeys=\\\"true\\\" keyProperty=\\\"id\\\"\",\"B. autoResult=\\\"true\\\"\",\"C. returnKey=\\\"true\\\"\",\"D. selectKey=\\\"true\\\"\"]','\"A\"','在 `<insert>` 标签中配置 `useGeneratedKeys=\"true\"` 和 `keyProperty=\"实体类主键属性名\"`，可以将数据库自增主键的值回填到传入的实体对象中。',9),(1788,18,'single','MyBatis 映射文件（Mapper XML）中，namespace 属性的主要作用是：','[\"A. 定义缓存策略\",\"B. 绑定对应的 Mapper 接口\",\"C. 指定数据库连接池\",\"D. 配置事务管理器\"]','\"B\"','`namespace` 属性用于指定该映射文件对应的 Mapper 接口的全限定名，是实现 XML 与接口绑定的关键。',10),(1789,18,'single','MyBatis 中，用于定义可重用的 SQL 片段（如列名列表）的标签是：','[\"A. <sql>\",\"B. <part>\",\"C. <block>\",\"D. <define>\"]','\"A\"','`<sql>` 标签用于定义可重用的 SQL 代码片段，然后通过 `<include>` 标签在其他地方引用。',11),(1790,18,'single','Spring 容器中，默认的 Bean 作用域是：','[\"A. prototype (原型)\",\"B. singleton (单例)\",\"C. request (请求)\",\"D. session (会话)\"]','\"B\"','Spring 容器中 Bean 的默认作用域是 `singleton`，即整个 Spring 容器中只存在该 Bean 的一个实例。',12),(1791,18,'single','若希望一个 Bean 在每次被请求时都创建一个新的实例，应将其作用域设置为：','[\"A. singleton\",\"B. prototype\",\"C. globalSession\",\"D. application\"]','\"B\"','`prototype` 作用域的 Bean 在每次通过容器获取时，都会创建一个新的实例。',13),(1792,18,'single','在 Spring 基于 Java 的配置（JavaConfig）中，用于定义 Bean 的注解是：','[\"A. @Component\",\"B. @Bean\",\"C. @Service\",\"D. @Autowired\"]','\"B\"','在配置类（`@Configuration` 标注的类）的方法上使用 `@Bean` 注解，可以将该方法的返回值定义为一个 Spring Bean。`@Component`、`@Service` 等是用于标注类本身的注解，属于组件扫描范畴。',14),(1793,18,'single','下列关于 Spring 依赖注入（DI）的说法，错误的是：','[\"A. 构造器注入要求在创建对象时提供依赖\",\"B. Setter 注入可以在对象创建后动态设置依赖\",\"C. DI 增加了组件之间的耦合度\",\"D. Spring 支持基于注解的自动装配\"]','\"C\"','依赖注入（DI）的核心思想是**降低**组件之间的耦合度，将依赖关系的创建和管理从组件内部转移到外部容器（如 Spring）。A、B、D 都是对 DI 和 Spring 的正确描述。',15),(1794,18,'single','当有多个同类型的 Bean 时，配合 @Autowired 使用，用于指定注入 Bean 名称的注解是：','[\"A. @Resource\",\"B. @Qualifier\",\"C. @Named\",\"D. @Inject\"]','\"B\"','`@Qualifier` 注解可以与 `@Autowired` 结合使用，通过指定 Bean 的名称（id）或限定符来消除自动装配的歧义。`@Resource` 是 JSR-250 标准，默认按名称装配。',16),(1795,18,'single','Spring AOP 中，@Around（环绕通知）的参数类型通常是：','[\"A. JoinPoint\",\"B. ProceedingJoinPoint\",\"C. Pointcut\",\"D. Advice\"]','\"B\"','环绕通知（@Around）是功能最强大的通知类型，它可以控制目标方法的执行。其参数类型必须是 `ProceedingJoinPoint`（它是 `JoinPoint` 的子类），通过调用其 `proceed()` 方法来执行目标方法。',17),(1796,18,'single','Spring AOP 的核心实现原理是：','[\"A. 继承\",\"B. 封装\",\"C. 动态代理\",\"D. 多态\"]','\"C\"','Spring AOP 默认使用 JDK 动态代理（针对接口）或 CGLIB 动态代理（针对类）来创建目标对象的代理对象，从而在运行时将横切逻辑（通知）织入到目标方法中。',18),(1797,18,'single','在 Spring 中，用于标注“初始化方法”的注解是（JSR-250标准）：','[\"A. @Init\",\"B. @Start\",\"C. @PostConstruct\",\"D. @PreDestroy\"]','\"C\"','JSR-250 标准定义了 `@PostConstruct` 和 `@PreDestroy` 注解，分别用于标注 Bean 的初始化方法和销毁方法。Spring 支持这两个注解。',19),(1798,18,'single','Spring MVC 的核心前端控制器是：','[\"A. FacesServlet\",\"B. DispatcherServlet\",\"C. ActionServlet\",\"D. SpringServlet\"]','\"B\"','`DispatcherServlet` 是 Spring MVC 的核心，它接收所有的 HTTP 请求，并根据配置将请求分发给相应的处理器（Controller）。',20),(1799,18,'single','在 Spring MVC 中，用于将控制器方法的返回值直接写入 HTTP 响应体（通常用于返回 JSON）的注解是：','[\"A. @RequestBody\",\"B. @ResponseBody\",\"C. @ModelAttribute\",\"D. @ResponseStatus\"]','\"B\"','`@ResponseBody` 注解表明该方法的返回值应该直接写入 HTTP 响应体，而不是被解析为视图名称。通常配合消息转换器（如 `MappingJackson2HttpMessageConverter`）用于返回 JSON/XML 数据。',21),(1800,18,'single','组合了 @Controller 和 @ResponseBody 功能的注解是：','[\"A. @Service\",\"B. @Component\",\"C. @RestController\",\"D. @Repository\"]','\"C\"','`@RestController` 是 Spring 4.0 引入的注解，它本身被 `@Controller` 和 `@ResponseBody` 注解，用于标记一个类中的所有方法都默认返回数据（如 JSON/XML）而不是视图。',22),(1801,18,'single','在 Spring MVC 中，若要获取 URL 路径参数（如 /user/{id}），应使用：','[\"A. @RequestParam\",\"B. @PathVariable\",\"C. @RequestHeader\",\"D. @CookieValue\"]','\"B\"','`@PathVariable` 用于将 URL 模板变量（如 `{id}`）绑定到控制器方法的参数上。`@RequestParam` 用于获取查询参数（`?key=value`）。',23),(1802,18,'single','Spring MVC 中，负责将逻辑视图名解析为具体 View 对象（如 JSP、Thymeleaf）的组件是：','[\"A. HandlerMapping\",\"B. HandlerAdapter\",\"C. ViewResolver\",\"D. MultipartResolver\"]','\"C\"','`ViewResolver`（视图解析器）根据控制器返回的逻辑视图名（如 `\"user_list\"`）解析为具体的 `View` 对象（如 `InternalResourceView` 对应 JSP），用于渲染响应。',24),(1803,18,'single','Spring MVC 中，用于处理文件上传的接口是：','[\"A. File\",\"B. MultipartFile\",\"C. InputStream\",\"D. UploadItem\"]','\"B\"','Spring MVC 提供了 `MultipartFile` 接口来接收上传的文件，它封装了文件内容、文件名、大小等信息。通常与 `@RequestParam` 一起使用。',25),(1804,18,'single','在 Spring MVC 中，若要实现一个拦截器，通常需要实现哪个接口？','[\"A. Filter\",\"B. HandlerInterceptor\",\"C. ControllerAdvice\",\"D. WebBindingInitializer\"]','\"B\"','Spring MVC 的拦截器需要实现 `HandlerInterceptor` 接口（或继承 `HandlerInterceptorAdapter`）。`Filter` 是 Servlet 规范中的过滤器，作用范围更广（在 DispatcherServlet 之前）。',26),(1805,18,'single','Spring Boot 的核心启动类注解 @SpringBootApplication 不包含下列哪一个？','[\"A. @SpringBootConfiguration\",\"B. @EnableAutoConfiguration\",\"C. @ComponentScan\",\"D. @EnableTransactionManagement\"]','\"D\"','`@SpringBootApplication` 是一个复合注解，它包含 `@SpringBootConfiguration`（本质是 `@Configuration`）、`@EnableAutoConfiguration` 和 `@ComponentScan`。`@EnableTransactionManagement` 是用于开启声明式事务管理的注解，不包含在内。',27),(1806,18,'single','Spring Boot 默认支持的配置文件格式是：','[\"A. .xml 和 .json\",\"B. .properties 和 .yml\",\"C. .ini 和 .conf\",\"D. .txt 和 .cfg\"]','\"B\"','Spring Boot 默认支持 `application.properties` 和 `application.yml`（或 `application.yaml`）两种格式的配置文件。YAML 格式因其层次结构更清晰而常用。',28),(1807,18,'single','在 Spring Boot 的 application.yml 中，缩进的规范是：','[\"A. 使用 Tab 键\",\"B. 使用 2 个或 4 个空格\",\"C. 不允许缩进\",\"D. 任意空白字符\"]','\"B\"','YAML 语法严格依赖缩进来表示层级关系，并且规定缩进只能使用空格，不能使用 Tab 键。通常使用 2 个或 4 个空格作为一级缩进。',29),(1808,18,'single','Spring Boot 提供的用于生产环境监控（如健康检查、指标收集）的模块是：','[\"A. Spring Boot Actuator\",\"B. Spring Boot DevTools\",\"C. Spring Boot Admin\",\"D. Spring Boot Test\"]','\"A\"','Spring Boot Actuator 提供了一系列用于监控和管理生产环境 Spring Boot 应用的功能端点（endpoints），如 `/actuator/health`、`/actuator/metrics`。',30),(1809,18,'single','Spring Boot 中，Maven 依赖管理通常继承自：','[\"A. spring-framework-parent\",\"B. spring-boot-starter-parent\",\"C. spring-mvc-parent\",\"D. java-ee-parent\"]','\"B\"','`spring-boot-starter-parent` 是一个特殊的 Starter，它提供了合理的 Maven 默认配置（如 Java 版本、编码、依赖版本管理等），简化了 Spring Boot 项目的 Maven 配置。',31),(1810,18,'single','所谓“约定优于配置”（Convention over Configuration），在 Spring Boot 中的体现是：','[\"A. 开发者必须配置所有细节\",\"B. 只有 XML 配置才生效\",\"C. 框架提供合理的默认配置，仅需在特殊情况自定义\",\"D. 不允许任何配置文件\"]','\"C\"','Spring Boot 的核心思想之一就是“约定优于配置”。它为大量常见的开发场景（如数据源、Web服务器、日志等）提供了开箱即用的默认配置，开发者只有在需要覆盖默认行为时才需要进行显式配置。',32),(1811,18,'single','若要在 Spring Boot 中激活名为 `dev` 的配置文件（application-dev.yml），可以在 application.yml 中配置：','[\"A. spring.profiles.active=dev\",\"B. spring.config.name=dev\",\"C. server.profile=dev\",\"D. boot.mode=dev\"]','\"A\"','通过 `spring.profiles.active` 属性可以指定当前激活的配置文件。可以同时激活多个，用逗号分隔。',33),(1812,18,'single','关于 Spring Boot 的 Web 开发，下列说法正确的是：','[\"A. 必须部署到外部 Tomcat\",\"B. 内置了 Tomcat/Jetty 等容器，可直接运行\",\"C. 不支持 JSP\",\"D. 以上都不对\"]','\"B\"','Spring Boot Web 应用默认内嵌了 Tomcat 服务器（也可选择 Jetty 或 Undertow），因此可以直接通过 `java -jar` 运行独立的 JAR 包，无需部署到外部容器。它支持 JSP，但需要额外的配置，且不是官方推荐的首选模板引擎。',34),(1813,18,'single','在 Spring 事务管理中， @Transactional 注解默认回滚的异常类型是：','[\"A. Exception (所有异常)\",\"B. RuntimeException (运行时异常)\",\"C. SQLException\",\"D. IOException\"]','\"B\"','`@Transactional` 默认只在抛出运行时异常（`RuntimeException` 及其子类）和 `Error` 时回滚事务。受检异常（checked exception）默认不会导致回滚。可以通过 `rollbackFor` 属性自定义。',35),(1814,18,'single','在 RESTful 风格中，通常用于“删除资源”的 HTTP 方法是：','[\"A. GET\",\"B. POST\",\"C. PUT\",\"D. DELETE\"]','\"D\"','RESTful API 中，HTTP 方法通常与 CRUD 操作对应：GET（查）、POST（增）、PUT（改，全量）、DELETE（删）。',36),(1815,18,'single','HTTP 状态码 404 表示：','[\"A. 请求成功\",\"B. 没有任何授权\",\"C. 服务器内部错误\",\"D. 请求的资源未找到\"]','\"D\"','404 Not Found：客户端请求的资源在服务器上未找到。401 表示未授权/需要认证，403 表示禁止访问，500 表示服务器内部错误。',37),(1816,18,'single','HTTP 状态码 500 表示：','[\"A. 请求参数错误\",\"B. 服务器内部错误\",\"C. 禁止访问\",\"D. 资源重定向\"]','\"B\"','500 Internal Server Error：服务器遇到了一个未曾预料的情况，导致其无法完成对请求的处理。通常是服务器端代码错误。',38),(1817,18,'single','Spring MVC 中， ModelAndView 对象的主要作用是：','[\"A. 仅封装视图\",\"B. 仅封装数据\",\"C. 既封装数据也封装视图信息\",\"D. 仅用于异常处理\"]','\"C\"','`ModelAndView` 对象持有模型数据（`ModelMap`）和视图信息（视图名或视图对象），方便控制器方法一次性返回数据和视图。',39),(1818,18,'single','ES6 中，用于拼接字符串并支持嵌入变量的符号是：','[\"A. 单引号\",\"B. 双引号\",\"C. 反引号\",\"D. 井号\"]','\"C\"','ES6 引入的模板字符串使用反引号（`）定义，可以在其中使用 `${expression}` 语法嵌入变量或表达式。',40),(1819,18,'single','Spring Boot 测试类通常使用哪个注解来加载 Spring 上下文？','[\"A. @Test\",\"B. @SpringBootTest\",\"C. @Run\",\"D. @ContextConfiguration\"]','\"B\"','`@SpringBootTest` 是 Spring Boot 提供的测试注解，它会加载完整的应用程序上下文，用于集成测试。它内部整合了 `@ExtendWith(SpringExtension.class)` 和 `@ContextConfiguration` 等功能。',41),(1820,18,'single','MyBatis 中，用于执行 SQL、获取 Mapper 接口及管理事务的核心接口是：','[\"A. SqlSessionFactory\",\"B. Configuration\",\"C. SqlSession\",\"D. Executor\"]','\"C\"','`SqlSession` 是 MyBatis 中用于执行 SQL、提交/回滚事务以及获取 Mapper 接口代理对象的核心接口。每个线程都应该有它自己的 `SqlSession` 实例。',42),(1821,18,'single','Spring AOP 中，表达式 execution(* com.example.service.*.*(..)) 的含义是：','[\"A. 拦截 com.example.service 包下所有类的所有方法\",\"B. 仅拦截 public 方法\",\"C. 仅拦截返回值为 void 的方法\",\"D. 仅拦截无参数的方法\"]','\"A\"','切入点表达式 `execution(* com.example.service.*.*(..))` 解析：第一个 `*` 表示任意返回类型；`com.example.service.*` 表示该包下的任意类；第二个 `.*` 表示任意方法；`(..)` 表示任意参数。因此它匹配该包下所有类的所有方法（默认包括 public 方法）。',43),(1822,18,'single','Spring MVC 中，若希望方法执行后重定向到另一个 URL，返回的字符串应以什么开头？','[\"A. forward:\",\"B. redirect:\",\"C. goto:\",\"D. send:\"]','\"B\"','在控制器方法中返回以 `\"redirect:/path\"` 开头的字符串，Spring MVC 会发起一个客户端重定向（302 响应）。`\"forward:/path\"` 表示服务器端转发。',44),(1823,18,'single','关于 MyBatis Mapper 接口中的方法重载，描述正确的是：','[\"A. 支持\",\"B. 不支持（MyBatis 依据方法名寻找 SQL）\",\"C. 仅支持参数个数不同的重载\",\"D. 仅支持返回值不同的重载\"]','\"B\"','MyBatis 的 Mapper 接口不支持方法重载。因为 MyBatis 是通过方法名（全限定名 + 方法名）来映射到 XML 中的 SQL 语句 ID 的。如果存在重载，会导致映射关系不明确。',45),(1824,18,'single','在 Spring 中，@Value(\"${server.port}\") 的作用是：','[\"A. 注入 Bean 对象\",\"B. 注入配置文件中的属性值\",\"C. 注入系统环境变量\",\"D. 注入当前的日期时间\"]','\"B\"','`@Value(\"${property.name}\")` 注解用于从 Spring 的环境（Environment）中注入属性值，这些属性可以来自配置文件（如 `application.properties`）、JVM 系统属性、环境变量等。',46),(1825,18,'single','Spring中，ApplicationContext 接口与 BeanFactory 接口的关系是：','[\"A. ApplicationContext 是 BeanFactory 的子接口，功能更强大\",\"B. BeanFactory 是 ApplicationContext 的子接口\",\"C. 两者没有继承关系\",\"D. ApplicationContext 已经废弃\"]','\"A\"','`ApplicationContext` 是 `BeanFactory` 的子接口，它在 `BeanFactory` 基础之上，增加了更多企业级功能，如国际化、事件发布、AOP 集成、更方便的资源访问等。通常我们直接使用 `ApplicationContext`。',47),(1826,18,'single','Spring中，通常用于标注数据访问层（DAO）组件的注解是：','[\"A. @Controller\",\"B. @Service\",\"C. @Repository\",\"D. @Component\"]','\"C\"','`@Repository` 是 `@Component` 的特化，用于标注数据访问层（DAO）组件，除了组件扫描，它还支持将数据访问异常转换为 Spring 统一的数据访问异常体系。',48),(1827,18,'single','在 Spring MVC Controller 方法中，若需要获取原生 HttpServletRequest 对象，应如何操作？','[\"A. 无法获取\",\"B. 通过 @Autowired 注入\",\"C. 直接在方法参数中声明 HttpServletRequest request\",\"D. 必须创建一个新的 Servlet\"]','\"C\"','Spring MVC 支持在控制器方法参数中直接声明许多原生 Servlet API 对象（如 `HttpServletRequest`、`HttpServletResponse`、`HttpSession` 等），框架会自动注入。不推荐在类级别通过 `@Autowired` 注入 Servlet 对象，因为其不是线程安全的。',49),(1828,18,'single','在 Maven 项目中，用于将项目打包成 JAR 或 WAR 文件的命令是：','[\"A. mvn compile\",\"B. mvn test\",\"C. mvn package\",\"D. mvn install\"]','\"C\"','`mvn package` 命令会执行编译、测试，并根据 `pom.xml` 中 `<packaging>` 的配置（如 jar 或 war）将项目打包到 `target/` 目录下。`mvn install` 除了打包，还会将生成的包安装到本地 Maven 仓库。',50),(1829,18,'single','Spring Boot 应用启动时，默认监听的 HTTP 端口号是：','[\"A. 80\",\"B. 8080\",\"C. 3306\",\"D. 6379\"]','\"B\"','Spring Boot 内嵌 Web 服务器的默认端口是 `8080`。可以通过 `server.port` 属性进行修改。',51),(1830,18,'single','HTTP 协议中，表示请求成功处理的常见状态码是：','[\"A. 200\",\"B. 302\",\"C. 400\",\"D. 500\"]','\"A\"','200 OK：表示请求已成功处理。302 Found 表示临时重定向，400 Bad Request 表示客户端请求错误，500 Internal Server Error 表示服务器内部错误。',52),(1831,18,'single','在 JSON 数据格式中，用于表示“对象”的符号是：','[\"A. [ ]\",\"B. { }\",\"C. ( )\",\"D. < >\"]','\"B\"','JSON 中，对象（Object）使用花括号 `{}` 包裹，表示无序的键值对集合。数组（Array）使用方括号 `[]` 包裹。',53),(1832,18,'single','MyBatis 中，用于引用已定义的 SQL 代码片段（<sql> 标签定义）的标签是：','[\"A. <import>\",\"B. <ref>\",\"C. <include>\",\"D. <copy>\"]','\"C\"','`<include>` 标签用于引用通过 `<sql>` 标签定义的 SQL 片段，通过 `refid` 属性指定片段的 ID。',54),(1833,18,'single','在 Spring 基于 Java 的配置中，标注一个类为配置类（替代 XML 配置文件）的注解是：','[\"A. @Config\",\"B. @Configuration\",\"C. @Setting\",\"D. @Bean\"]','\"B\"','`@Configuration` 注解标记一个类为 Spring 的配置类，它替代了传统的 XML 配置文件。在该类中可以定义 `@Bean` 注解的方法来声明 Bean。',55),(1834,18,'single','Spring MVC 中，@GetMapping(\"/list\") 等价于：','[\"A. @RequestMapping(value=\\\"/list\\\", method=RequestMethod.GET)\",\"B. @RequestMapping(value=\\\"/list\\\", method=RequestMethod.POST)\",\"C. @RequestMapping(value=\\\"/list\\\", method=RequestMethod.PUT)\",\"D. @RequestMapping(value=\\\"/list\\\", method=RequestMethod.DELETE)\"]','\"A\"','`@GetMapping`、`@PostMapping`、`@PutMapping`、`@DeleteMapping` 等是 Spring 4.3 引入的组合注解，它们分别等价于 `@RequestMapping` 加上对应的 `method` 属性。',56),(1835,18,'single','数据库事务的四大特性（ACID）不包括：','[\"A. 原子性 (Atomicity)\",\"B. 一致性 (Consistency)\",\"C. 隔离性 (Isolation)\",\"D. 分布式 (Distributed)\"]','\"D\"','事务的四大特性是：原子性（Atomicity）、一致性（Consistency）、隔离性（Isolation）、持久性（Durability），简称 ACID。“分布式”不是事务的核心特性，分布式事务是事务在分布式系统中的延伸。',57),(1836,18,'single','Spring Boot 中，通过 server.servlet.context-path 属性主要用于配置：','[\"A. 服务器端口\",\"B. 应用的上下文路径（项目访问路径）\",\"C. 会话超时时间\",\"D. 数据库连接地址\"]','\"B\"','`server.servlet.context-path` 属性用于设置 Spring Boot 应用的上下文路径。例如，设置为 `/myapp` 后，所有应用的端点（如 `/hello`）都将以 `/myapp/hello` 的形式访问。',58),(1837,18,'single','关于 HTTP 中 GET 和 POST 请求的区别，下列描述错误的是：','[\"A. GET 请求参数显示在 URL 中，POST 放在请求体中\",\"B. GET 请求通常用于获取数据，POST 用于提交数据\",\"C. GET 请求的数据长度通常受限于浏览器/服务器限制，POST 理论上没有限制\",\"D. GET 请求比 POST 请求更安全，适合传输敏感数据\"]','\"D\"','D 选项错误。GET 请求的参数直接暴露在 URL 和浏览器历史、服务器日志中，而 POST 请求参数在请求体中，相对更隐蔽一些。但无论是 GET 还是 POST，如果未使用 HTTPS 加密，传输内容都不安全，都不适合直接传输敏感数据（如密码）。安全应依赖于 HTTPS 等加密协议，而非 HTTP 方法本身。',59),(1989,31,'single','Spring IoC容器初始化时,会对哪种作用域的Bean进行实例化()','[\"prototype\",\"session\",\"singleton\",\"request\"]','\"C\"','singleton作用域的Bean在容器初始化时就会被实例化(默认饿汉式);prototype作用域的Bean在每次获取时才实例化;request和session是Web环境下的作用域，在Web请求/会话创建时实例化。',0),(1990,31,'single','在Spring中,若要获取IoC容器中的Bean实例,可通过哪个接口的getBean()方法()','[\"None of the above\",\"ApplicationContext\",\"BeanFactory\",\"Both A and B\"]','\"D\"','ApplicationContext和BeanFactory都是Spring IoC容器的核心接口,均提供getBean()方法获取Bean;ApplicationContext是BeanFactory的子接口,功能更丰富(如事件发布、国际化支持)。',1),(1991,31,'single','Spring MVC中,ViewResolver的主要作用是()','[\"拦截请求并添加额外处理逻辑\",\"将控制器方法返回的逻辑视图名解析为物理视图路径\",\"执行控制器方法并返回结果\",\"处理HTTP请求参数的绑定\"]','\"B\"','ViewResolver通过配置的前缀(prefix)和后缀(suffix),将逻辑视图名(如\"index\")转换为物理路径(如\"/WEB-INF/views/index.jsp\");拦截请求是Interceptor的作用;执行控制器方法是HandlerAdapter的作用;处理参数绑定是数据绑定组件的作用。',2),(1992,31,'single','下列注解中,用于标识一个类为Spring MVC控制器的是()','[\"@Component\",\"@Controller\",\"@Repository\",\"@Service\"]','\"B\"','@Controller专门用于标识Spring MVC的控制器类,负责处理HTTP请求;@Service用于业务层,@Repository用于数据访问层,@Component是通用Bean标识,三者均不直接关联请求处理。',3),(1993,31,'judge','Spring MVC和Spring Boot中的MVC功能完全相同,Spring Boot只是简化了Spring MVC的配置。()',NULL,'true','Spring Boot的MVC功能基于Spring MVC核心组件,仅通过自动配置(如默认DispatcherServlet、视图解析器)简化了开发,核心功能(请求映射、数据绑定、视图解析等)与Spring MVC一致。',4),(1994,31,'single','下列关于MyBatis二级缓存的描述,正确的是()','[\"二级缓存开启后,不同SqlSession无法共享缓存数据\",\"二级缓存默认开启,作用域为SqlSession\",\"二级缓存需手动开启,作用域为SqlSessionFactory(全局)\",\"实体类无需实现Serializable接口,即可存入二级缓存\"]','\"C\"','二级缓存默认关闭,需通过配置开启,作用域为SqlSessionFactory,不同SqlSession可共享;存入二级缓存的实体类必须实现Serializable接口,否则会报错;一级缓存默认开启,作用域为SqlSession。',5),(1995,31,'single','Spring Boot中,@Value注解的用法正确的是()','[\"@Value(\\\"${app.name:default}\\\") private String appName;(默认值为\\\"default\\\")\",\"@Value(\\\"${app.name}\\\") private String appName;\",\"@Value(\\\"app.name\\\") private String appName;\",\"@Value(\\\"#{app.name}\\\") private String appName;\"]','\"A\"','@Value注入配置属性需用${key}格式,A正确且带有默认值语法;B缺少默认值;C缺少${}符号;D是SpEL表达式(#{}),用于Bean属性引用,而非配置注入。',6),(1996,31,'judge','MyBatis的< foreach>标签中,collection属性用于指定要遍历的集合参数名,当参数为List时,默认collection值为“list”;当参数为数组时,默认值为“array”。 ()',NULL,'true','<foreach>的collection属性需与参数类型匹配,List默认用“list”,数组默认用“array”;若通过@Param命名参数,则用命名值作为collection属性值。',7),(1997,31,'single','Spring中,@Qualifier注解的作用是()','[\"当存在多个同类型Bean时,指定注入的Bean名称\",\"声明事务属性\",\"标识类为Bean\",\"定义AOP切入点\"]','\"A\"','@Qualifier常与@Autowired配合使用,当多个Bean类型相同(byType匹配失败)时,通过@Qualifier(\"beanName\")指定Bean名称;声明事务用@Transactional;标识类为Bean用@Component等;定义AOP切入点用@Pointcut。',8),(1998,31,'judge','MyBatis中,#{}会将参数值拼接为字符串并添加单引号,${}会将参数作为占位符预编译,因此#{}比${}更安全。 ()',NULL,'false','逻辑颠倒。#{}是预编译占位符,自动处理符号和类型,防止SQL注入;${}是直接字符串替换,无预编译,有注入风险,因此#{}更安全。',9),(1999,31,'single','Spring事务管理中,默认的事务传播行为是()','[\"REQUIRES_NEW\",\"NESTED\",\"SUPPORTS\",\"REQUIRED\"]','\"D\"','REQUIRED是默认传播行为:如果当前存在事务,则加入该事务;如果不存在,则创建新事务;SUPPORTS表示支持当前事务,无事务则以非事务方式执行;REQUIRES_NEW总是创建新事务;NESTED嵌套在当前事务中。',10),(2000,31,'single','Spring MVC的拦截器()的执行顺序中,下列哪个方法在控制器方法执行后、视图渲染前执行()','[\"preHandle()\",\"init()\",\"afterCompletion()\",\"postHandle()\"]','\"D\"','Interceptor的三个方法:preHandle()(控制器方法执行前,返回true放行)、postHandle()(方法执行后,视图渲染前)、afterCompletion()(视图渲染后);init()是初始化方法,非拦截逻辑。',11),(2001,31,'single','Spring Boot中,用于指定应用端口号的配置是()','[\"spring.port=8080\",\"tomcat.port=8080\",\"server.port=8080\",\"app.server.port=8080\"]','\"C\"','server.port是Spring Boot指定嵌入式服务器端口的标准配置,默认8080;其他选项均为非标准配置,无法生效。',12),(2002,31,'single','Spring Boot中,@EnableAutoConfiguration注解的作用是()','[\"禁用所有自动配置\",\"仅用于测试环境\",\"扫描指定包下的组件\",\"根据类路径依赖自动配置Bean(如引入spring-boot-starter-web则自动配置DispatcherServlet)\"]','\"D\"','@EnableAutoConfiguration是自动配置的核心注解,通过SpringFactoriesLoader加载META-INF/spring.factories中的自动配置类,根据类路径依赖判断是否生效,实现“按需配置”。',13),(2003,31,'single','在MyBatis动态SQL中,标签配合和使⽤,其功能类似于Java中的哪种语句()','[\"for循环\",\"switch-case-default\",\"if-else if-else\",\"try-catch-finally\"]','\"B\"','<choose>标签下的<when>按顺序判断条件,满足则执行对应SQL,不继续判断;所有<when>不满足时,执行<otherwise>的SQL,逻辑与switch-case-default一致;<if>对应if-else if-else;<foreach>对应for循环;无对应try-catch-finally的动态标签。',14),(2004,31,'judge','@PathVariable注解的required属性默认值为true,即URL路径中必须包含该参数,否则会报错。()',NULL,'true','@PathVariable默认要求路径中必须包含对应参数,若参数可缺省,需设置required=false(如@PathVariable(required = false) Long id),此时URL可不带该参数。',15),(2005,31,'judge','@Controller注解标识的类中,所有方法的返回值都会被解析为视图名。()',NULL,'false','若方法被@ResponseBody注解修饰,或类被@RestController修饰,返回值会被转换为响应体(如JSON),而非视图名;仅未加@ResponseBody的方法返回字符串时,默认解析为视图名。',16),(2006,31,'single','Spring Boot的自动配置原理中,@Conditional系列注解的作用是()','[\"根据条件判断是否生效(如类存在、配置存在等)\",\"仅用于测试环境的配置\",\"关闭所有自动配置\",\"强制开启自动配置\"]','\"A\"','@Conditional是条件注解的根注解,衍生出@ConditionalOnClass(类存在时生效)、@ConditionalOnProperty(配置存在时生效)等,自动配置类通过这些注解判断是否需要生效,实现“按需配置”。',17),(2007,31,'judge','Spring MVC中,@PathVariable注解用于接收URL路径中的参数,如“/user/{id}”中的id值。()',NULL,'true','@PathVariable用于绑定URL模板变量到方法参数,例如@RequestMapping(\"/user/{id}\")配合public User getUser(@PathVariable(\"id\") Long id)可获取路径中的id。',18),(2008,31,'single','Spring Boot中,默认的配置文件名称是()','[\"springboot.yml\",\"config.properties\",\"bootstrap.properties\",\"application.properties或application.yml\"]','\"D\"','Spring Boot默认加载application.properties或application.yml作为主配置文件;bootstrap.properties是启动阶段配置文件(优先级更高,通常用于配置中心)。',19),(2009,31,'single','Spring Boot默认的嵌入式Web服务器是()','[\"Tomcat\",\"Nginx\",\"Undertow\",\"Jetty\"]','\"A\"','Spring Boot的spring-boot-starter-web默认引入Tomcat作为嵌入式服务器;若需更换,可排除Tomcat依赖并引入Jetty或Undertow的starter(如spring-boot-starter-jetty)。',20),(2010,31,'single','在Spring MVC中,若要接收URL路径中的参数,如/user/123中的123,应使用哪个注解()','[\"@ModelAttribute\",\"@RequestBody\",\"@PathVariable\",\"@RequestParam\"]','\"C\"','@PathVariable用于绑定URL路径中的模板变量(如@RequestMapping(\"/user/{id}\")配合@PathVariable(\"id\") Long id);@RequestParam接收请求参数(如?id=123);@RequestBody接收请求体数据;@ModelAttribute用于数据绑定到模型。',21),(2011,31,'single','下列关于Spring Boot和Spring关系的说法,正确的是()','[\"Spring Boot不支持Spring的AOP、IoC等核心特性\",\"使用Spring Boot必须放弃XML配置\",\"Spring Boot是Spring的替代框架\",\"Spring Boot基于Spring核心功能,简化了配置\"]','\"D\"','Spring Boot是Spring的“脚手架”,基于Spring的IoC、AOP等核心功能,通过自动配置和starter简化开发,并非替代;支持XML配置(需通过@ImportResource引入)。',22),(2012,31,'single','Spring中,Bean的默认作用域是()','[\"request\",\"session\",\"singleton\",\"prototype\"]','\"C\"','Spring Bean默认作用域为singleton(单例),即IoC容器中只存在一个Bean实例;prototype为多例(每次获取创建新实例);request和session是Web环境下的作用域。',23),(2013,31,'single','Spring MVC中,若控制器方法需要接收表单提交的多个参数,并将其封装到实体类对象中,应使用哪个注解()','[\"@RequestParam\",\"@RequestBody\",\"@PathVariable\",\"@ModelAttribute\"]','\"D\"','@ModelAttribute用于将请求参数自动绑定到实体类对象(要求参数名与实体类属性名一致),并将对象存入模型;复杂JSON数据绑定用@RequestBody,简单参数用@RequestParam,路径参数用@PathVariable。',24),(2014,31,'single','Spring Boot的核心特性是()','[\"仅支持Java EE环境\",\"自动配置(Auto-configuration)\",\"基于XML的繁琐配置\",\"必须依赖外部Web服务器\"]','\"B\"','Spring Boot的核心是自动配置,通过@EnableAutoConfiguration注解根据类路径下的依赖自动配置Bean,大幅减少手动配置;提倡“零配置”或注解配置,支持独立运行的Java应用,内置Tomcat、Jetty等服务器。',25),(2015,31,'judge','Spring Boot应用必须打包为WAR文件才能部署到外部服务器,无法通过JAR文件运行。()',NULL,'false','Spring Boot默认支持打包为可执行JAR文件(内置服务器),通过java -jar命令直接运行;也可打包为WAR文件部署到外部服务器(需排除内置服务器依赖)。',26),(2016,31,'single','Spring Boot中,@ComponentScan注解的默认扫描范围是()','[\"com.springboot包\",\"所有包\",\"标注@SpringBootApplication的类所在的包及其子包\",\"不扫描任何包,需手动指定\"]','\"C\"','@SpringBootApplication包含的@ComponentScan默认扫描当前类所在的包及其子包下的@Component(含@Controller、@Service等)注解的类;若需扫描其他包,可通过basePackages属性指定。',27),(2017,31,'judge','@ResponseStatus注解可以指定控制器方法或异常处理方法返回的HTTP响应状态码。()',NULL,'true','@ResponseStatus可标注在方法或异常类上,通过code属性指定响应状态码(如@ResponseStatus(code = HttpStatus.NOT_FOUND)返回404),方便统一状态码管理。',28),(2018,31,'single','Spring MVC中,@RequestMapping注解的作用是()','[\"将方法返回值转换为JSON响应\",\"定义异常处理方法\",\"映射HTTP请求的URL和方法到控制器方法\",\"将请求参数绑定到方法参数\"]','\"C\"','@RequestMapping通过value属性指定URL路径,method属性指定HTTP方法(如GET、POST),将请求映射到对应的控制器方法;@ResponseBody将返回值转换为JSON;@ExceptionHandler定义异常处理;@RequestParam绑定请求参数。',29),(2019,31,'single','MyBatis中,下列哪个注解可直接⽤于接⼝⽅法上,指定对应的SQL语句(⽆需XML映射⽂件)()','[\"@ResultMap\",\"@Mapper\",\"@Select\",\"@Param\"]','\"C\"','@Select⽤于在接⼝⽅法上直接编写查询SQL;@Mapper⽤于标识该接⼝为MyBatis的Mapper接⼝;@ResultMap⽤于指定复⽤的ResultMap配置;@Param⽤于给⽅法参数命名,⽅便XML中引⽤。',30),(2020,31,'single','Spring中,下列哪种方式可以实现Bean的自动装配“autowiring”()','[\"以上都是\",\"使用@Autowired注解\",\"XML配置中设置autowire=\\\"byType\\\"\",\"XML配置中设置autowire=\\\"byName\\\"\"]','\"A\"','Spring支持多种自动装配方式:XML中通过autowire属性指定byName(按名称)、byType(按类型)等;注解方式通过@Autowired(按类型,可配合@Qualifier按名称)实现。',31),(2021,31,'single','下列哪个注解用于Spring MVC中,将请求URL映射到控制器方法()','[\"@Controller\",\"@RestController\",\"@RequestMapping\",\"@ResponseBody\"]','\"C\"','@RequestMapping用于映射请求URL到控制器方法,支持类级和方法级注解;@Controller标识控制器类;@ResponseBody将方法返回值直接作为响应体;@RestController = @Controller + @ResponseBody。',32),(2022,31,'judge','MyBatis注解开发中,@Insert、@Update、@Delete注解的value属性可直接编写对应的SQL语句,功能与XML中的<insert>、< update>、< delete>标签⼀致。 ()',NULL,'true','@Insert、@Update、@Delete是MyBatis注解开发的核⼼写操作注解,value属性⽤于编写SQL,作⽤与XML中的对应标签完 全⼀致,适⽤于简单SQL场景。',33),(2023,31,'single','MyBatis中,#{}和${}的主要区别是()','[\"#{}会预编译SQL(防⽌SQL注⼊),${}直接字符串替换(有注⼊⻛险)\",\"#{}只能在XML中使⽤,${}只能在注解中使⽤\",\"#{}会⾃动添加单引号,${}不会添加任何符号\",\"#{}⽤于传数值型参数,${}⽤于传字符串型参数\"]','\"A\"','#{}会将参数作为占位符预编译SQL,⾃动处理类型转换和符号添加,能防⽌SQL注⼊;${}直接将参数值拼接进SQL,⽆预编译过程,存在注⼊⻛险;⼆者均⽀持所有参数类型和XML/注解场景,符号添加并⾮核⼼区别。',34),(2024,31,'judge','Spring MVC中,视图解析器()的作用是将逻辑视图名(如“index”)解析为物理视图路径(如“/WEB-INF/views/index.jsp”)。()',NULL,'true','视图解析器通过前缀(prefix)和后缀(suffix)拼接逻辑视图名,生成物理路径,例如prefix=\"/WEB-INF/views/\", suffix=\".jsp\"时,“index”解析为“/WEB-INF/views/index.jsp”。',35),(2025,31,'single','MyBatis核⼼配置⽂件中,标签的作⽤是()','[\"设置数据库连接池参数\",\"注册Mapper接⼝或XML⽂件\",\"配置MyBatis的全局属性(如⽇志、缓存、驼峰命名映射等)\",\"定义可复⽤的SQL⽚段\"]','\"C\"','<settings>⽤于配置MyBatis全局开关和属性,如logImpl(⽇志实现)、cacheEnabled(⼆级缓存开关)、mapUnderscoreToCamelCase(驼峰命名映射);注册Mapper用<mappers>;数据库连接池在<dataSource>中配置;定义SQL片段用<sql>标签。',36),(2026,31,'judge','MyBatis的⼀级缓存默认开启,其作⽤域为SqlSession,即同⼀个SqlSession内执⾏相同SQL会复⽤缓存数据。()',NULL,'true','一级缓存默认开启,作用域为SqlSession,同一个SqlSession内执行相同SQL会复用缓存数据。当执行增删改操作或调用clearCache()方法时,一级缓存会被清空。',37),(2027,31,'single','下列关于MyBatis⼀级缓存的说法,错误的是()','[\"⼀级缓存默认开启,⽆需配置\",\"⼀级缓存的⽣命周期与SqlSession⼀致\",\"不同SqlSession之间可以共享⼀级缓存数据\",\"执⾏SqlSession的clearCache()⽅法可⼿动清空⼀级缓存\"]','\"C\"','⼀级缓存作⽤域为SqlSession,不同SqlSession的缓存相互独⽴,⽆法共享;其他选项均为⼀级缓存的正确特性。',38),(2028,31,'single','下列哪个注解用于指定控制器方法仅处理HTTP POST请求()','[\"@RequestMapping(method = RequestMethod.GET)\",\"@GetMapping\",\"@RequestMapping(method = RequestMethod.PUT)\",\"@PostMapping\"]','\"D\"','@PostMapping是@RequestMapping(method = RequestMethod.POST)的简化注解,专门处理POST请求;@GetMapping处理GET请求;@RequestMapping(method = RequestMethod.PUT)处理PUT请求。',39),(2029,31,'single','在Spring中,@Transactional注解用于声明事务,下列关于其属性的说法,正确的是()','[\"isolation属性用于设置事务的传播行为\",\"propagation属性用于设置事务的隔离级别\",\"readOnly属性默认为true,表示事务为只读\",\"rollbackFor属性用于指定哪些异常触发事务回滚\"]','\"D\"','rollbackFor指定需要回滚的异常类型(默认只回滚RuntimeException);isolation是隔离级别;propagation是传播行为;readOnly默认false,true表示只读事务(优化查询性能)。',40),(2030,31,'single','在MyBatis中,若接⼝⽅法参数为多个基本类型(如int id, String name),XML映射⽂件中引⽤参数时,正确的⽅式是()','[\"使⽤#{0}和#{1}按参数顺序引⽤(默认⽀持)\",\"直接使⽤#{id}和#{name}\",\"必须通过@Param注解给参数命名,再⽤#{参数名}引⽤\",\"只能将参数封装为实体类,再通过#{属性名}引⽤\"]','\"A\"','MyBatis默认⽀持按参数顺序(0开始)引⽤多个基本类型参数,如#{0}对应第⼀个参数,#{1}对应第⼆个;也可通过@Param注解命名后按名称引⽤;并⾮必须封装实体类或强制⽤@Param。',41),(2031,31,'single','Spring Boot中,嵌入式服务器的默认端口号是()','[\"80\",\"8081\",\"9090\",\"8080\"]','\"D\"','Spring Boot的嵌入式Tomcat默认端口为8080,可通过server.port配置修改(如server.port=8081)。',42),(2032,31,'single','Spring AOP的通知类型中,在目标方法执行后执行,无论是否抛出异常都会执行的是()','[\"后置通知(After)\",\"异常通知(AfterThrowing)\",\"前置通知(Before)\",\"返回通知(AfterReturning)\"]','\"A\"','后置通知(After)在目标方法执行完成后触发,无论是否抛出异常;前置通知(Before)在方法执行前;返回通知(AfterReturning)仅在方法正常返回后;异常通知(AfterThrowing)仅在方法抛出异常后。',43),(2033,31,'single','在MyBatis的XML映射⽂件中,若要实现“根据传⼊的参数动态拼接WHERE条件,参数为空时不拼接该条件”,应使⽤哪个动态SQL标签()','[\"< foreach>\",\"< choose>\",\"< where>\",\"< if>\"]','\"D\"','<if>标签通过test属性判断条件,满⾜时才拼接其内部SQL,可实现参数为空不拼接条件;<where>⽤于⾃动处理拼接条件时的AND/OR前缀;<choose>⽤于多条件分⽀选择;<foreach>⽤于遍历集合参数(如IN查询)。',44),(2034,31,'judge','Spring事务的传播行为REQUIRES_NEW表示:如果当前存在事务,则挂起当前事务,创建新事务执行;如果不存在,则创建新事务。()',NULL,'true','REQUIRES_NEW的特点是无论当前是否有事务,都创建新事务,原有事务(若存在)会被挂起,新事务独立提交或回滚。',45),(2035,31,'single','MyBatis中,SqlSession的作⽤是()','[\"存储MyBatis的全局配置信息\",\"创建SqlSessionFactory的⼯⼚类\",\"负责数据库连接的创建和销毁\",\"执⾏SQL语句、管理事务的核⼼接⼝\"]','\"D\"','SqlSession是MyBatis的核⼼操作接⼝,提供selectOne/selectList、insert/update/delete等⽅法执⾏SQL,同时⽀持commit/rollback管理事务;全局配置信息由Configuration存储;创建SqlSessionFactory用SqlSessionFactoryBuilder;数据库连接由DataSource负责。',46),(2036,31,'single','下列关于Spring Bean生命周期的说法,正确的是()','[\"Bean的生命周期由Bean自身管理,与IoC容器无关\",\"销毁方法(如destroy-method)在容器关闭时,针对singleton Bean执行\",\"初始化方法(如init-method)在Bean实例化后、依赖注入前执行\",\"prototype作用域的Bean会被容器调用销毁方法\"]','\"B\"','singleton Bean的销毁方法在容器关闭时执行;Bean生命周期由IoC容器管理;初始化方法在依赖注入后执行;prototype Bean的销毁由用户手动管理,容器不调用销毁方法。',47),(2037,31,'single','在MyBatis XML映射⽂件中,标签的核⼼作⽤是()','[\"给SQL语句的结果集添加额外字段\",\"定义SQL语句的查询结果与实体类属性的映射关系(解决字段名与属性名不⼀致)\",\"直接指定查询结果的返回类型(如String、实体类)\",\"动态⽣成查询结果的列名\"]','\"B\"','<resultMap>⽤于⾃定义结果映射,当数据库字段名与实体类属性名不⼀致时,通过<id>(主键映射)和<result>(普通字段映射)建⽴对应关系;指定返回类型用resultType属性;其他选项并非其核心作用。',48),(2038,31,'single','Spring MVC的核心前端控制器是()','[\"HandlerAdapter\",\"ViewResolver\",\"HandlerMapping\",\"DispatcherServlet\"]','\"D\"','DispatcherServlet是Spring MVC的核心,负责接收所有HTTP请求,协调HandlerMapping(找处理器)、HandlerAdapter(执行处理器)、ViewResolver(解析视图)等组件完成请求处理。',49),(2039,31,'single','下列关于@ResponseBody注解的说法,正确的是()','[\"用于指定跳转的视图名\",\"用于将方法返回值直接转换为JSON/XML等格式,作为HTTP响应体\",\"用于将方法返回值作为模型数据存入request域\",\"用于接收请求体中的JSON数据\"]','\"B\"','@ResponseBody告知Spring MVC无需解析视图,直接将返回值(如对象、集合)通过消息转换器(如Jackson)转换为JSON/XML,写入响应体;指定视图名是返回字符串的默认行为;存入request域是Model的作用;接收请求体JSON数据用@RequestBody。',50),(2040,31,'judge','MyBatis的Mapper接⼝可以有⽅法体(即默认⽅法或抽象⽅法的实现),⽆需仅定义抽象⽅法。()',NULL,'false','MyBatis的Mapper接⼝必须是纯抽象接⼝,仅定义抽象⽅法(⽆⽅法体),MyBatis会通过动态代理⽣成接⼝实现类;若有⽅法体(如默认⽅法),会导致动态代理失败。',51),(2041,31,'single','Spring MVC中,@RestController注解的含义是()','[\"用于定义全局异常处理类\",\"等同于@Controller + @ResponseBody,方法返回值直接作为响应体\",\"用于指定控制器的请求路径前缀\",\"仅用于标识REST风格的控制器,与普通@Controller无区别\"]','\"B\"','@RestController是组合注解,= @Controller + @ResponseBody,适用于RESTful接口开发,所有方法的返回值都会被转换为响应体,无需再单独加@ResponseBody。',52),(2042,31,'single','@SpringBootApplication注解包含的核心注解不包括()','[\"@Service\",\"@ComponentScan\",\"@Configuration\",\"@EnableAutoConfiguration\"]','\"A\"','@SpringBootApplication是组合注解,等价于@Configuration(标识配置类)+@EnableAutoConfiguration(开启自动配置)+@ComponentScan(组件扫描);@Service用于标识业务层Bean,不属于其包含的注解。',53),(2043,31,'single','Spring Boot配置文件的优先级从高到低排序正确的是()','[\"命令行参数 > application.yml > application.properties > application-dev.yml\",\"application.properties > application.yml > 命令行参数 > application-dev.yml\",\"命令行参数 > application-dev.yml > application.yml > application.properties\",\"命令行参数 > application-dev.properties > application.yml > application.properties\"]','\"D\"','Spring Boot配置优先级(从高到低):命令行参数 > 激活的profile配置(如application-dev.properties) > application.yml > application.properties(同目录下,yml和properties的优先级取决于加载顺序,通常yml略高,但命令行和profile配置更高)。',54),(2044,31,'judge','Spring的@Component注解有三个衍生注解:@Controller(用于Service层)、@Service(用于Controller层)、@Repository(用于Dao层)。()',NULL,'false','衍生注解的分层错误:@Controller用于Web层(控制器),@Service用于业务层(Service),@Repository用于数据访问层(Dao),目的是更清晰地标识Bean的用途。',55),(2045,31,'judge','Spring MVC的DispatcherServlet是前端控制器,负责处理所有HTTP请求,并将其分发给对应的处理器。()',NULL,'true','DispatcherServlet是Spring MVC的核心,作为中央调度器接收所有请求,通过HandlerMapping找到对应处理器,经HandlerAdapter执行后,再通过ViewResolver解析视图并响应。',56),(2046,31,'judge','@GetMapping注解是@RequestMapping(method = RequestMethod.GET)的简化形式,只能用于处理GET请求。()',NULL,'true','Spring 4.3+引入@GetMapping、@PostMapping等组合注解,分别对应特定HTTP方法的@RequestMapping,简化配置,@GetMapping仅处理GET请求。',57),(2047,32,'single','在 ES6 中，关于 `let` 和 `var` 的区别，下列描述错误的是：','[\"`let` 声明的变量有块级作用域，`var` 没有\",\"`var` 存在变量提升，`let` 不存在\",\"`let` 允许在同一作用域内重复声明同一个变量\",\"`const` 用于声明常量，一旦赋值后不能修改引用\"]','\"`let` 允许在同一作用域内重复声明同一个变量\"','let 不允许在同一作用域内重复声明同一个变量，而 var 允许。',0),(2048,32,'single','下列 ES6 箭头函数的写法中，当函数体只有一行返回语句时，正确的是：','[\"(x) => { return x * x; }\",\"x => x * x\",\"x => { x * x }\",\"(x) => return x * x\"]','\"x => x * x\"','当函数体只有一行且为返回值时，可以省略花括号和 return 关键字。',1),(2049,32,'single','在 ES6 模块化中，使用 `export default` 导出的模块，在导入时：','[\"需要使用 [ ] 包裹变量名\",\"可以任意命名变量，不需要 [ ]\",\"必须使用原模块定义的变量名\",\"必须使用 as 语法\"]','\"可以任意命名变量，不需要 [ ]\"','使用 default 导出时，导入时可以任意命名变量。',2),(2050,32,'single','下列关于 ES6 解构赋值的写法，正确的是：','[\"`let` {a, b} = {a: 1, b: 2}\",\"`let` [a, b] = {a: 1, b: 2}\",\"`let` {a, b} = [1, 2]\",\"`let` (a, b) = (1, 2)\"]','\"`let` {a, b} = {a: 1, b: 2}\"','对象解构使用花括号，数组解构使用方括号。',3),(2051,32,'single','在 ES6 类（Class）定义中，用于初始化对象属性的方法名是：','[\"`init`\",\"`constructor`\",\"`main`\",\"create\"]','\"`constructor`\"','constructor 是类的构造函数，用于初始化对象。',4),(2052,32,'single','MyBatis 中，为了防止 SQL 注入，在传递普通参数（非表名/列名）时，应优先使用：','[\"${param}\",\"#{param}\",\"&{param}\",\"@{param}\"]','\"#{param}\"','#{} 是预编译占位符，可防止 SQL 注入；${} 是字符串拼接，存在注入风险。',5),(2053,32,'single','在 MyBatis 的 XML 映射文件中，根元素是：','[\"<configuration>\",\"<mapper>\",\"<sqlMap>\",\"<mybatis>\"]','\"<mapper>\"','MyBatis 映射文件的根元素是 <mapper>。',6),(2054,32,'single','在 MyBatis 关联查询中，用于处理“多对一”或“一对一”关系的标签是：','[\"<collection>\",\"<association>\",\"<list>\",\"<map>\"]','\"<association>\"','<association> 用于处理多对一或一对一关系；<collection> 用于一对多或多对多。',7),(2055,32,'single','在 MyBatis 中，用于遍历集合（如实现 IN 查询）的动态 SQL 标签是：','[\"<if>\",\"<choose>\",\"<foreach>\",\"<set>\"]','\"<foreach>\"','<foreach> 用于遍历集合或数组，常用于 IN 查询。',8),(2056,32,'single','MyBatis 执行插入操作时，若希望将数据库自动生成的主键回填到实体对象中，应配置：','[\"useGeneratedKeys=\\\"true\\\" keyProperty=\\\"id\\\"\",\"autoResult=\\\"true\\\"\",\"returnKey=\\\"true\\\"\",\"selectKey=\\\"true\\\"\"]','\"useGeneratedKeys=\\\"true\\\" keyProperty=\\\"id\\\"\"','useGeneratedKeys 用于获取数据库生成的主键，keyProperty 指定回填到对象的属性名。',9),(2057,32,'single','MyBatis 映射文件（Mapper XML）中，namespace 属性的主要作用是：','[\"定义缓存策略\",\"绑定对应的 Mapper 接口\",\"指定数据库连接池\",\"配置事务管理器\"]','\"绑定对应的 Mapper 接口\"','namespace 用于指定对应的 Mapper 接口全限定名。',10),(2058,32,'single','MyBatis 中，用于定义可重用的 SQL 片段（如列名列表）的标签是：','[\"<sql>\",\"<part>\",\"<block>\",\"<define>\"]','\"<sql>\"','<sql> 标签用于定义可重用的 SQL 片段。',11),(2059,32,'single','Spring 容器中，默认的 Bean 作用域是：','[\"prototype (原型)\",\"singleton (单例)\",\"request (请求)\",\"session (会话)\"]','\"singleton (单例)\"','Spring 默认的 Bean 作用域是单例，即容器中只有一个实例。',12),(2060,32,'single','若希望一个 Bean 在每次被请求时都创建一个新的实例，应将其作用域设置为：','[\"singleton\",\"prototype\",\"globalSession\",\"application\"]','\"prototype\"','prototype 作用域表示每次请求时都创建一个新的 Bean 实例。',13),(2061,32,'single','在 Spring 基于 Java 的配置（JavaConfig）中，用于定义 Bean 的注解是：','[\"@Component\",\"@Bean\",\"@Service\",\"@Autowired\"]','\"@Bean\"','@Bean 注解用于在配置类中定义 Bean，替代 XML 中的 <bean> 标签。',14),(2062,32,'single','下列关于 Spring 依赖注入（DI）的说法，错误的是：','[\"构造器注入要求在创建对象时提供依赖\",\"Setter 注入可以在对象创建后动态设置依赖\",\"DI 增加了组件之间的耦合度\",\"Spring 支持基于注解的自动装配\"]','\"DI 增加了组件之间的耦合度\"','DI 降低了组件之间的耦合度，提高代码的可维护性和可测试性。',15),(2063,32,'single','当有多个同类型的 Bean 时，配合 @Autowired 使用，用于指定注入 Bean 名称的注解是：','[\"@Resource\",\"@Qualifier\",\"@Named\",\"@Inject\"]','\"@Qualifier\"','@Qualifier 用于指定要注入的 Bean 名称，配合 @Autowired 使用。',16),(2064,32,'single','Spring AOP 中，@Around（环绕通知）的参数类型通常是：','[\"JoinPoint\",\"ProceedingJoinPoint\",\"Pointcut\",\"Advice\"]','\"ProceedingJoinPoint\"','@Around 通知的参数类型是 ProceedingJoinPoint，可用于控制目标方法的执行。',17),(2065,32,'single','Spring AOP 的核心实现原理是：','[\"继承\",\"封装\",\"动态代理\",\"多态\"]','\"动态代理\"','Spring AOP 默认使用 JDK 动态代理或 CGLIB 实现，核心是动态代理技术。',18),(2066,32,'single','在 Spring 中，用于标注“初始化方法”的注解是（JSR-250标准）：','[\"@Init\",\"@Start\",\"@PostConstruct\",\"@PreDestroy\"]','\"@PostConstruct\"','@PostConstruct 用于标注初始化方法，在 Bean 初始化完成后执行。',19),(2067,32,'single','Spring MVC 的核心前端控制器是：','[\"FacesServlet\",\"DispatcherServlet\",\"Actionservlet\",\"SpringServlet\"]','\"DispatcherServlet\"','DispatcherServlet 是 Spring MVC 的核心前端控制器，负责请求的分发和处理。',20),(2068,32,'single','在 Spring MVC 中，用于将控制器方法的返回值直接写入 HTTP 响应体（通常用于返回 JSON）的注解是：','[\"@RequestBody\",\"@ResponseBody\",\"@ModelAttribute\",\"@ResponseStatus\"]','\"@ResponseBody\"','@ResponseBody 表示返回值直接写入响应体，常用于返回 JSON 或 XML。',21),(2069,32,'single','组合了 @Controller 和 @ResponseBody 功能的注解是：','[\"@Service\",\"@Component\",\"@RestController\",\"@Repository\"]','\"@RestController\"','@RestController 是 @Controller 和 @ResponseBody 的组合，适用于 RESTful 接口。',22),(2070,32,'single','在 Spring MVC 中，若要获取 URL 路径参数（如 /user/{id}），应使用：','[\"@RequestParam\",\"@PathVariable\",\"@RequestHeader\",\"@CookieValue\"]','\"@PathVariable\"','@PathVariable 用于获取 URL 中的路径参数。',23),(2071,32,'single','Spring MVC 中，负责将逻辑视图名解析为具体 View 对象（如 JSP、Thymeleaf）的组件是：','[\"HandlerMapping\",\"HandlerAdapter\",\"ViewResolver\",\"MultipartResolver\"]','\"ViewResolver\"','ViewResolver 负责将逻辑视图名解析为具体的视图对象。',24),(2072,32,'single','Spring MVC 中，用于处理文件上传的接口是：','[\"File\",\"MultipartFile\",\"InputStream\",\"UploadItem\"]','\"MultipartFile\"','MultipartFile 是 Spring 提供的文件上传接口。',25),(2073,32,'single','在 Spring MVC 中，若要实现一个拦截器，通常需要实现哪个接口？','[\"Filter\",\"HandlerInterceptor\",\"ControllerAdvice\",\"WebBindingInitializer\"]','\"HandlerInterceptor\"','HandlerInterceptor 是 Spring MVC 中用于实现拦截器的接口。',26),(2074,32,'single','Spring Boot 的核心启动类注解 @SpringBootApplication 不包含下列哪一个？','[\"@SpringBootConfiguration\",\"@EnableAutoConfiguration\",\"@ComponentScan\",\"@EnableTransactionManagement\"]','\"@EnableTransactionManagement\"','@SpringBootApplication 包含 @SpringBootConfiguration、@EnableAutoConfiguration、@ComponentScan，但不包含 @EnableTransactionManagement。',27),(2075,32,'single','Spring Boot 默认支持的配置文件格式是：','[\".xml 和 .json\",\".properties 和 .yml\",\".ini 和 .conf\",\".txt 和 .cfg\"]','\".properties 和 .yml\"','Spring Boot 默认支持 .properties 和 .yml（或 .yaml）配置文件。',28),(2076,32,'single','在 Spring Boot 的 application.yml 中，缩进的规范是：','[\"使用 Tab 键\",\"使用 2 个或 4 个空格\",\"不允许缩进\",\"任意空白字符\"]','\"使用 2 个或 4 个空格\"','YAML 规范要求使用空格缩进，推荐使用 2 或 4 个空格，不能使用 Tab。',29),(2077,32,'single','Spring Boot 提供的用于生产环境监控（如健康检查、指标收集）的模块是：','[\"Spring Boot Actuator\",\"Spring Boot DevTools\",\"Spring Boot Admin\",\"Spring Boot Test\"]','\"Spring Boot Actuator\"','Spring Boot Actuator 提供生产级监控和管理功能，如健康检查、指标收集等。',30),(2078,32,'single','Spring Boot 中，Maven 依赖管理通常继承自：','[\"spring-framework-parent\",\"spring-boot-starter-parent\",\"spring-mvc-parent\",\"java-ee-parent\"]','\"spring-boot-starter-parent\"','spring-boot-starter-parent 是 Spring Boot 项目的标准父 POM，提供依赖管理和默认配置。',31),(2079,32,'single','所谓“约定优于配置”（Convention over Configuration），在 Spring Boot 中的体现是：','[\"开发者必须配置所有细节\",\"只有 XML 配置才生效\",\"框架提供合理的默认配置，仅需在特殊情况自定义\",\"不允许任何配置文件\"]','\"框架提供合理的默认配置，仅需在特殊情况自定义\"','Spring Boot 提供大量默认配置，开发者只需在需要时进行覆盖或扩展。',32),(2080,32,'single','若要在 Spring Boot 中激活名为 `dev` 的配置文件（application-dev.yml），可以在 application.yml 中配置：','[\"spring.profiles.active=dev\",\"spring.config.name=dev\",\"server.profile=dev\",\"boot.mode=dev\"]','\"spring.profiles.active=dev\"','通过 spring.profiles.active 指定激活的配置文件。',33),(2081,32,'single','关于 Spring Boot 的 Web 开发，下列说法正确的是：','[\"必须部署到外部 Tomcat\",\"内置了 Tomcat/Jetty 等容器，可直接运行\",\"不支持 JSP\"]','\"内置了 Tomcat/Jetty 等容器，可直接运行\"','Spring Boot 内置了 Web 容器（如 Tomcat、Jetty），可直接运行，无需外部容器。',34),(2082,32,'single','在 Spring 事务管理中， @Transactional 注解默认回滚的异常类型是：','[\"Exception (所有异常)\",\"RuntimeException (运行时异常)\",\"SQLException\",\"IOException\"]','\"RuntimeException (运行时异常)\"','@Transactional 默认只在抛出 RuntimeException 或 Error 时回滚。',35),(2083,32,'single','在 RESTful 风格中，通常用于“删除资源”的 HTTP 方法是：','[\"GET\",\"POST\",\"PUT\",\"DELETE\"]','\"DELETE\"','DELETE 方法用于删除资源。',36),(2084,32,'single','HTTP 状态码 404 表示：','[\"请求成功\",\"没有任何授权\",\"服务器内部错误\",\"请求的资源未找到\"]','\"请求的资源未找到\"','404 表示客户端请求的资源不存在。',37),(2085,32,'single','HTTP 状态码 500 表示：','[\"请求参数错误\",\"服务器内部错误\",\"禁止访问\",\"资源重定向\"]','\"服务器内部错误\"','500 表示服务器内部发生错误，无法完成请求。',38),(2086,32,'single','Spring MVC 中， ModelAndView 对象的主要作用是：','[\"仅封装视图\",\"仅封装数据\",\"既封装数据也封装视图信息\",\"仅用于异常处理\"]','\"既封装数据也封装视图信息\"','ModelAndView 可同时封装模型数据和视图信息，便于控制器返回。',39),(2087,32,'single','ES6 中，用于拼接字符串并支持嵌入变量的符号是：','[\"单引号\",\"双引号\",\"反引号\",\"井号\"]','\"反引号\"','反引号（`）用于定义模板字符串，支持变量嵌入（${}）。',40),(2088,32,'single','Spring Boot 测试类通常使用哪个注解来加载 Spring 上下文？','[\"@Test\",\"@SpringBootTest\",\"@Run\",\"@ContextConfiguration\"]','\"@SpringBootTest\"','@SpringBootTest 用于启动 Spring Boot 上下文进行集成测试。',41),(2089,32,'single','MyBatis 中，用于执行 SQL、获取 Mapper 接口及管理事务的核心接口是：','[\"SqlSessionFactory\",\"Configuration\",\"SqlSession\",\"Executor\"]','\"SqlSession\"','SqlSession 是 MyBatis 的核心接口，用于执行 SQL、获取 Mapper 和管理事务。',42),(2090,32,'single','Spring AOP 中，表达式 execution(* com.example.service.*.*(..)) 的含义是：','[\"拦截 com.example.service 包下所有类的所有方法\",\"仅拦截 public 方法\",\"仅拦截返回值为 void 的方法\",\"仅拦截无参数的方法\"]','\"拦截 com.example.service 包下所有类的所有方法\"','execution 表达式匹配指定包下所有类的所有方法，不限访问修饰符、返回类型和参数。',43),(2091,32,'single','Spring MVC 中，若希望方法执行后重定向到另一个 URL，返回的字符串应以什么开头？','[\"forward:\",\"redirect:\",\"goto:\",\"send:\"]','\"redirect:\"','在返回值前加 \'redirect:\' 表示重定向到指定 URL。',44),(2092,32,'single','关于 MyBatis Mapper 接口中的方法重载，描述正确的是：','[\"支持\",\"不支持（MyBatis 依据方法名寻找 SQL）\",\"仅支持参数个数不同的重载\",\"仅支持返回值不同的重载\"]','\"不支持（MyBatis 依据方法名寻找 SQL）\"','MyBatis 通过方法名映射 SQL 语句，不支持方法重载。',45),(2093,32,'single','在 Spring 中，@Value(\"${server.port}\") 的作用是：','[\"注入 Bean 对象\",\"注入配置文件中的属性值\",\"注入系统环境变量\",\"注入当前的日期时间\"]','\"注入配置文件中的属性值\"','@Value 用于注入配置文件中的属性值，如 server.port。',46),(2094,32,'single','Spring中，ApplicationContext 接口与 BeanFactory 接口的关系是：','[\"ApplicationContext 是 BeanFactory 的子接口，功能更强大\",\"BeanFactory 是 ApplicationContext 的子接口\",\"两者没有继承关系\",\"ApplicationContext 已经废弃\"]','\"ApplicationContext 是 BeanFactory 的子接口，功能更强大\"','ApplicationContext 扩展了 BeanFactory，提供了更多企业级功能，如国际化、事件发布等。',47),(2095,32,'single','Spring中，通常用于标注数据访问层（DAO）组件的注解是：','[\"@Controller\",\"@Service\",\"@Repository\",\"@Component\"]','\"@Repository\"','@Repository 用于标注数据访问层（DAO）组件。',48),(2096,32,'single','在 Spring MVC Controller 方法中，若需要获取原生 HttpServletRequest 对象，应如何操作？','[\"无法获取\",\"通过 @Autowired 注入\",\"直接在方法参数中声明 HttpServletRequest request\",\"必须创建一个新的 Servlet\"]','\"直接在方法参数中声明 HttpServletRequest request\"','Spring MVC 支持在控制器方法参数中直接声明 HttpServletRequest 等原生对象。',49),(2097,32,'single','在 Maven 项目中，用于将项目打包成 JAR 或 WAR 文件的命令是：','[\"mvn compile\",\"mvn test\",\"mvn package\",\"mvn install\"]','\"mvn package\"','mvn package 用于打包项目，生成 JAR 或 WAR 文件。',50),(2098,32,'single','Spring Boot 应用启动时，默认监听的 HTTP 端口号是：','[\"80\",\"8080\",\"3306\",\"6379\"]','\"8080\"','Spring Boot 默认端口是 8080，可通过 server.port 修改。',51),(2099,32,'single','HTTP 协议中，表示请求成功处理的常见状态码是：','[\"200\",\"302\",\"400\",\"500\"]','\"200\"','200 表示请求已成功处理。',52),(2100,32,'single','在 JSON 数据格式中，用于表示“对象”的符号是：','[\"[ ]\",\"[ ]\",\"( )\",\"<>\"]','\"[ ]\"','JSON 对象使用花括号 {} 表示，此处选项描述有误，应为花括号。',53),(2101,32,'single','MyBatis 中，用于引用已定义的 SQL 代码片段（<sql> 标签定义）的标签是：','[\"<import>\",\"<ref>\",\"<include>\",\"<copy>\"]','\"<include>\"','<include> 标签用于引用 <sql> 中定义的 SQL 片段。',54),(2102,32,'single','在 Spring 基于 Java 的配置中，标注一个类为配置类（替代 XML 配置文件）的注解是：','[\"@Config\",\"@Configuration\",\"@Setting\",\"@Bean\"]','\"@Configuration\"','@Configuration 标注一个类为配置类，相当于 XML 配置文件。',55),(2103,32,'single','Spring MVC 中，@GetMapping(\"/list\") 等价于：','[\"@RequestMapping(value=\\\"/list\\\", method=RequestMethod.GET)\",\"@RequestMapping(value=\\\"/list\\\", method=RequestMethod.POST)\",\"@RequestMapping(value=\\\"/list\\\", method=RequestMethod.PUT)\",\"@RequestMapping(value=\\\"/list\\\", method=RequestMethod.DELETE)\"]','\"@RequestMapping(value=\\\"/list\\\", method=RequestMethod.GET)\"','@GetMapping 是 @RequestMapping(method=GET) 的组合注解。',56),(2104,32,'single','数据库事务的四大特性（ACID）不包括：','[\"原子性 (Atomicity)\",\"一致性 (Consistency)\",\"隔离性 (Isolation)\",\"分布式 (Distributed)\"]','\"分布式 (Distributed)\"','ACID 包括原子性、一致性、隔离性、持久性（Durability），不包括分布式。',57),(2105,32,'single','Spring Boot 中，通过 server.servlet.context-path 属性主要用于配置：','[\"服务器端口\",\"应用的上下文路径（项目访问路径）\",\"会话超时时间\",\"数据库连接地址\"]','\"应用的上下文路径（项目访问路径）\"','server.servlet.context-path 用于设置应用的上下文路径（如 /app）。',58),(2106,32,'single','关于 HTTP 中 GET 和 POST 请求的区别，下列描述错误的是：','[\"GET 请求参数显示在 URL 中，POST 放在请求体中\",\"GET 请求通常用于获取数据，POST 用于提交数据\",\"GET 请求的数据长度通常受限于浏览器/服务器限制，POST 理论上没有限制\",\"GET 请求比 POST 请求更安全，适合传输敏感数据\"]','\"GET 请求比 POST 请求更安全，适合传输敏感数据\"','GET 参数暴露在 URL 中，不如 POST 安全，不适合传输敏感数据。',59),(2107,33,'single','A common term that describes the combination of a smartphone and a tablet is.','[\"notebook computer\",\"handheld computer\",\"tablet computer\",\"Phablet\"]','\"Phablet\"','Phablet是phone和tablet的结合词，指屏幕尺寸介于智能手机和平板电脑之间的移动设备。',0),(2108,33,'single','Application-specific computers are not including the','[\"portable data terminal\",\"carputer\",\"smartphones\",\"wearable computer\"]','\"smartphones\"','专用计算机指为特定应用设计的计算机，如便携式数据终端、车载电脑、可穿戴计算机等，智能手机属于通用移动计算设备。',1),(2109,33,'single','Which of the following is not belonging to the features of Mobile Computers?','[\"portability\",\"small size\",\"wireless communication\",\"Data\"]','\"Data\"','移动计算机的特征包括便携性、体积小、无线通信等，Data（数据）是计算机处理的内容，不是设备本身的特征。',2),(2110,33,'single','Android OS, iOS, Windows Phone and BlackBerry are all examples of','[\"application software\",\"mobile operating systems\",\"browsers\",\"desktop operating systems\"]','\"mobile operating systems\"','Android OS、iOS、Windows Phone和BlackBerry都是常见的移动操作系统。',3),(2111,33,'single','Mobile apps were originally offered for general productivity and information retrieval, but don’t including .','[\"microprocessor\",\"calendar\",\"E-Mail\",\"weather informations\"]','\"microprocessor\"','早期的移动应用主要用于生产力工具和信息检索，如日历、电子邮件、天气信息等，微处理器是硬件组件，不属于应用功能。',4),(2112,33,'single','Smartphones are mobile phones with an advanced mobile operating system. Which one is not a smartphone?','[\"iPhone\",\"Xiaomi Mi4\",\"iPad\",\"Samsung Galaxy S6\"]','\"iPad\"','iPad是平板电脑，不属于智能手机范畴。',5),(2113,33,'single','Which one is the primary navigation and information “hub” on Android devices?','[\"Homescreen\",\"widgets\",\"icons\",\"Status bar\"]','\"Homescreen\"','在Android设备中，主屏幕是用户访问应用和小部件的主要导航和信息中心。',6),(2114,33,'single','The four layers of Android architecture are not including:','[\"Linux kernel\",\"libraries\",\"application\",\"hard disk\"]','\"hard disk\"','Android架构的四层分别是Linux内核、系统库、应用框架和应用层，硬盘属于存储硬件，不属于架构层。',7),(2115,33,'single','The Services of Google Play does not include','[\"Google Play Music and eBooks\",\"Google Play Worksheet and document\",\"Google Play Newstand and games\",\"Google Play Movies & TV\"]','\"Google Play Worksheet and document\"','Google Play服务包括音乐、电子书、新闻、游戏、影视等，不包含Worksheet and document（工作表与文档）服务。',8),(2116,33,'single','The lowest layer of Android architecture, Linux kernel (version 2.6), provides core system services, such as .','[\"Memory management, process management, network stack, security and driver model\",\"Activity manager, windows manager, content providers and the view system\",\"Notification manager, package manager, telephone manager and resource manager\",\"location manager and XMPP service.\"]','\"Memory management, process management, network stack, security and driver model\"','Linux内核层提供核心系统服务，如内存管理、进程管理、网络协议栈、安全和驱动模型等。',9),(2117,33,'judge','Devices that are portable, but used while stationary, are sometimes removed from the group of mobile computing devices.','[]','true','移动计算设备强调在移动中使用，如果设备便携但主要在固定位置使用，可能不被归类为典型移动计算设备。',10),(2118,33,'judge','A mobile operating system is an operating system(OS) for smartphones, tablets, PDAs and desktop computers.','[]','false','移动操作系统是为智能手机、平板电脑、PDA等移动设备设计的操作系统，不适用于台式电脑。',11),(2119,33,'judge','A typical mobile device will fit in the average adult’s hand or pocket.','[]','true','典型的移动设备设计为便于携带，通常可以放入手中或口袋中。',12),(2120,33,'judge','The term “app” is a shortening of the term “system software”.','[]','false','app是application（应用程序）的缩写，而不是system software（系统软件）的缩写。',13),(2121,33,'judge','GPS is the Global Positioning System is a time-based navigation system that provides location and time information in all weather conditions.','[]','false','GPS是基于卫星的导航系统，提供位置和时间信息，但并非完全在所有天气条件下都可靠，某些天气可能影响信号接收。',14),(2122,33,'judge','iPhone is a line of smartphones designed and marketed by Apple Inc.','[]','true','iPhone是苹果公司设计和销售的智能手机产品线。',15),(2123,33,'judge','Redmi Note is a phablet and the second smartphone in the Mi Series.','[]','false','Redmi Note是小米旗下红米系列的手机，并非小米系列的第二款智能手机。',16),(2124,33,'judge','A homescreen may be made up of several pages that the user can swipe back and forth between.','[]','true','主屏幕通常由多个页面组成，用户可以通过滑动切换页面。',17),(2125,33,'judge','Apple’s applications are available through Google Play either free of charge or at a cost.','[]','false','苹果公司的应用通过App Store分发，而不是Google Play。',18),(2126,33,'judge','Android runtime includes a set of core libraries that provides most of the functionality available in the core libraries of the Java programming language.','[]','true','Android运行时包含一组核心库，提供了Java核心库的大部分功能。',19),(2127,33,'short','A mobile computer, also known as a mobile computing device is described as a small, _ lightweight ,portable computer and containing _ wireless _ Internet access.','[]','\"lightweight; wireless\"','移动计算机是一种轻便、便携、能通过无线方式访问互联网的小型计算设备。',20),(2128,33,'short','Google Play offers an online _ music _ store with over 22 million songs.','[]','\"music\"','Google Play提供了一个在线音乐商店，拥有超过2200万首歌曲。',21),(2129,33,'short','Two major CPU architectures dominate the mobile computers market, they are ARM Holdings’ _ ARM _ architecture and Intel’s _ x86 _ architecture.','[]','\"ARM; x86\"','移动计算机市场主要被ARM架构和Intel的x86架构主导。',22),(2130,33,'short','iPhone is a line of smartphones designed and marketed by Apple Inc. and runs Apple’s _ IOS _ mobile operating system.','[]','\"IOS\"','iPhone运行的是苹果公司的iOS移动操作系统。',23),(2131,33,'short','Galaxy Note is a series of Android-based high-end _ tablets and phablets _ .','[]','\"tablets and phablets\"','Galaxy Note是三星推出的基于Android的高端平板电脑和Phablet系列。',24),(2132,33,'short','In Family Sharing, family members can share purchased apps, music, movies, TV shows, and _ books _ using the same credit card.','[]','\"books\"','在家庭共享中，家庭成员可以共享购买的应用程序、音乐、电影、电视节目和电子书。',25),(2133,33,'short','Android is a _ mobile operating system _ currently developed by _ Google _ .','[]','\"mobile operating system; Google\"','Android是由Google开发的移动操作系统。',26),(2134,33,'short','A _ smartphone _ is a mobile phone with an advanced mobile operating system which combines features of a personal computer operating system with other features useful for mobile or handheld use.','[]','\"smartphone\"','智能手机是一种配备先进移动操作系统的手机，融合了个人电脑操作系统的功能和其他适用于移动或手持设备的功能。',27),(2135,33,'short','_ Wireless _ communication is capable of accessing the Internet through Bluetooth or Wi-Fi networks.','[]','\"Wireless\"','无线通信可以通过蓝牙或Wi-Fi网络访问互联网。',28),(2136,33,'short','The three types of application-specific computers are: _ carputers _ , portable data terminal computers and wearable computers.','[]','\"carputers\"','三类专用计算机包括车载计算机、便携式数据终端计算机和可穿戴计算机。',29),(2137,34,'single',', also known as the classic life cycle, is a sequential development approach, in which development is seen as flowing steadily downwards through several phases.','[\"The incremental model\",\"The waterfall model\",\"The iterative model\",\"The spiral development\"]','\"The waterfall model\"','瀑布模型也称为经典生命周期模型，是一种顺序开发方法，开发过程被视为稳定地向下流过几个阶段。',0),(2138,34,'single','Any agile software process must be—so as to manage unpredictability that encountered in the majority of software projects.','[\"unchanged\",\"similar\",\"simple\",\"Adaptable\"]','\"Adaptable\"','任何敏捷软件过程都必须是适应性的，以管理大多数软件项目中遇到的不确定性。',1),(2139,34,'single','The goal of is to produce a list of requirements for a new or revised information system.','[\"the maintenance phase\",\"software design phase\",\"Reengineering\",\"the system analysis phase\"]','\"the system analysis phase\"','系统分析阶段的目标是为新的或修订的信息系统生成需求列表。',2),(2140,34,'single','In the design phase , will be finished for a new or revised information system.','[\"a project development plan\",\"a requirements report\",\"application specifications\",\"Document\"]','\"application specifications\"','在设计阶段，将为新的或修订的信息系统完成应用程序规范。',3),(2141,34,'single',', is the examination and alteration of a software system to reconstitute it in a new form and the subsequent implementation of the new form.','[\"System analysis\",\"Software design\",\"Reengineering\",\"Maintenance\"]','\"Reengineering\"','重构是对软件系统进行检查和修改，以新的形式重新构建，并随后实施新形式的过程。',4),(2142,34,'single','The activities of reengineering generally include inventory analysis, , forward engineering, documentation restructuring, data restructuring and data restructuring.','[\"implementation\",\"reverse engineering\",\"Software test\",\"Maintenance\"]','\"reverse engineering\"','重构活动通常包括库存分析、逆向工程、正向工程、文档重构、数据重构和代码重构。',5),(2143,34,'single',' refers to analyzing an inventory of all applications which every software organization should have.','[\"System analysis\",\"Forward reengineering\",\"Inventory analysis\",\"Data analysis\"]','\"Inventory analysis\"','库存分析指的是分析每个软件组织应该拥有的所有应用程序的库存。',6),(2144,34,'single',' generally involves extracting design artifacts and building or synthesizing abstractions that are less implementation-dependent.','[\"Software engineering\",\"Reverse engineering\",\"Software reengineering\",\"Software process\"]','\"Reverse engineering\"','逆向工程通常涉及提取设计工件和构建或合成较少依赖于实现的抽象。',7),(2145,34,'single',' occurs at different levels of abstraction and is often the first reengineering task.','[\"Reverse engineering of process\",\"Reverse engineering user interfaces\",\"Reverse engineering of data\",\"Document restructuring\"]','\"Document restructuring\"','文档重构发生在不同的抽象层次，通常是第一个重构任务。',8),(2146,34,'single','Before more detailed reverse engineering work occurs, the overall of the entire application system must be understood.','[\"system requirements\",\"system design\",\"data structure\",\"Functionality\"]','\"Functionality\"','在进行更详细的逆向工程工作之前，必须理解整个应用程序系统的总体功能。',9),(2147,34,'judge','In order to reduce the influences of software crises, the computer scientists discussed the software crises problems at international conference at German in 1960.','[]','false','关于软件危机的讨论主要发生在1968年的NATO软件工程会议上，而不是1960年的德国会议。',10),(2148,34,'judge','A software process is a collection of activities, actions, and tasks that are performed when software is to be built.','[]','true','软件过程是在构建软件时执行的活动、动作和任务的集合。',11),(2149,34,'judge','Processes and tools outweigh individuals and interactions.','[]','false','根据敏捷宣言，个体和互动胜过过程和工具。',12),(2150,34,'judge','Working software over comprehensive documentation.','[]','true','根据敏捷宣言，可工作的软件胜过全面的文档。',13),(2151,34,'judge','Producing a project development plan usually occurs in the period of the analysis phase.','[]','false','项目开发计划通常在规划阶段产生，而不是分析阶段。',14),(2152,34,'judge','Reengineering tasks are allowed to modify business functionality.','[]','false','重构任务通常不允许修改业务功能，而是改进系统的技术方面。',15),(2153,34,'judge','Software migrations are also reengineering efforts.','[]','true','软件迁移也是重构工作的一部分。',16),(2154,34,'judge','The term \"reverse engineering\" originate from the analysis of hardware.','[]','true','术语\"逆向工程\"起源于硬件分析。',17),(2155,34,'judge','Reverse engineering must start from comparative high level of abstraction.','[]','false','逆向工程可以从不同层次的抽象开始，不一定必须从较高的抽象层次开始。',18),(2156,34,'judge','There are only two subareas of Reverse engineering, redocumentation and design recovery.','[]','false','逆向工程包括多个子领域，不仅仅是重新文档化和设计恢复。',19),(2157,34,'short','There are five phases in the software development life cycle, in which encompasses planning , analysis , design, implementation ______ and maintenance phase.','[]','\"implementation\"','软件开发生命周期包括规划、分析、设计、实现和维护五个阶段。',20),(2158,34,'short','The Signal ______ model is an evolutionary software process model that couples the iterative nature of prototyping with the controlled and systematic aspects of the waterfall model.','[]','\"The Spiral\"','螺旋模型是一种演化式软件过程模型，将原型的迭代性质与瀑布模型的可控性和系统性相结合。',21),(2159,34,'short','The goal of the planning phase is to ______ create a project development plan ______.','[]','\"create a project development plan\"','规划阶段的目标是创建项目开发计划。',22),(2160,34,'short','During the implementation phase, the developers should purchase and install hardware and/or software, create applications, test applications ______ , finalize documentation, train users ______ , convert data , convert to new system.','[]','\"test applications, train users\"','在实施阶段，开发人员应购买和安装硬件/软件、创建应用程序、测试应用程序、完成文档、培训用户、转换数据、转换到新系统。',23),(2161,34,'short','______ and the introduction of the EURO ______ are two historic reengineering initiators that nearly no company was able to escape.','[]','\"The Y2K problem, the introduction of the EURO\"','千年虫问题和欧元的引入是两个历史上几乎每个公司都无法避免的重构触发因素。',24),(2162,34,'short','The goals of reverse engineering are ______ and Creating representations of the system in another form or at a higher level of abstraction.','[]','\"identify the system\'s components and their interrelationships\"','逆向工程的目标是识别系统的组件及其相互关系，并以另一种形式或在更高的抽象层次上创建系统的表示。',25),(2163,34,'short','The core of reverse engineering is an activity called extract abstractions ______ .','[]','\"extract abstractions\"','逆向工程的核心是一个称为提取抽象的活动。',26),(2164,34,'short','______ refers to transforming a legacy database according to new technical requirements, while keeping the information contents unchanged.','[]','\"Database reengineering\"','数据库重构指的是根据新的技术要求转换遗留数据库，同时保持信息内容不变。',27),(2165,34,'short','Reverse engineering to understand processing begins with an attempt to understand and then ______ represented by the source code.','[]','\"procedural abstractions\"','理解处理的逆向工程始于尝试理解源代码所表示的过程抽象。',28),(2166,34,'short','Before a user interface can be rebuilt, ______ should occur.','[]','\"reverse engineering\"','在重建用户界面之前，应该进行逆向工程。',29),(2167,34,'multiple','What is a lifecycle of software?','[\"the period of time that is needed to create new software\",\"Is called the lifecycle of software\",\"which starts from the time of problem definition\",\"The development\",\"deployment and maintenance\",\"the moment of retirement\"]','[\"the period of time that is needed to create new software\",\"Is called the lifecycle of software\",\"which starts from the time of problem definition\",\"The development\",\"deployment and maintenance\",\"the moment of retirement\"]','软件生命周期是从问题定义开始，经过开发、部署和维护，直到退役的整个时间段。',30),(2168,34,'multiple','What is the collection of software processes that are performed when software is being built?','[\"activities\",\"actions\",\"tasks\",\"publish\"]','[\"activities\",\"actions\",\"tasks\"]','构建软件时执行的软件过程集合包括活动、动作和任务。',31),(2169,34,'multiple','There are lots of software process models, including','[\"The waterfall model\",\"The Incremental model\",\"The Spiral model\",\"The Agile process\"]','[\"The waterfall model\",\"The Incremental model\",\"The Spiral model\",\"The Agile process\"]','软件过程模型包括瀑布模型、增量模型、螺旋模型和敏捷过程等。',32),(2170,34,'multiple','Which of the following are a series of activities in the analysis phase?','[\"Study the current system\",\"Determine system requirements\",\"Write requirement report\",\"Develop a project schedule\"]','[\"Study the current system\",\"Determine system requirements\",\"Write requirement report\"]','分析阶段的活动包括研究现有系统、确定系统需求和编写需求报告。',33),(2171,34,'multiple','The activities of reengineering generally includes','[\"inventory analysis\",\"reverse engineering\",\"forward engineering\",\"documentation restructuring\",\"code restructuring\",\"data restructuring\"]','[\"inventory analysis\",\"reverse engineering\",\"forward engineering\",\"documentation restructuring\",\"code restructuring\",\"data restructuring\"]','重构活动通常包括库存分析、逆向工程、正向工程、文档重构、代码重构和数据重构。',34),(2172,34,'multiple','What is reengineering?','[\"also known as both renovation and reclamation\",\"Is the examination and alteration of a software system to reconstitute it in a new form and the subsequent implementation of the new form\",\"Is also know as the classic life cycle\",\"Is the software system which developed in the past\"]','[\"also known as both renovation and reclamation\",\"Is the examination and alteration of a software system to reconstitute it in a new form and the subsequent implementation of the new form\"]','重构也称为翻新和改造，是对软件系统进行检查和修改，以新的形式重新构建，并随后实施新形式的过程。',35),(2173,34,'multiple','Which of the following are the key objectives of reverse engineering?','[\"Cope with complexity\",\"Generate alternate views\",\"Recover lost information\",\"Detect side effects\",\"Synthesize higher abstractions\",\"Facilitate reuse\"]','[\"Cope with complexity\",\"Generate alternate views\",\"Recover lost information\",\"Detect side effects\",\"Synthesize higher abstractions\",\"Facilitate reuse\"]','逆向工程的关键目标包括处理复杂性、生成替代视图、恢复丢失的信息、检测副作用、合成更高级的抽象和促进重用。',36),(2174,34,'multiple','What are the three main steps of converting a legacy system to a modern database technology?','[\"Database schema conversion\",\"Data conversion\",\"Program conversion\",\"Database conversion\"]','[\"Database schema conversion\",\"Data conversion\",\"Program conversion\"]','将遗留系统转换为现代数据库技术的三个主要步骤是数据库模式转换、数据转换和程序转换。',37),(2175,35,'single','is a database management system that primarily relies on main memory for computer data storage.','[\"A disk resident database management system\",\"DRAM\",\"A main memory database system\",\"Cache\"]','\"A main memory database system\"','主内存数据库系统是主要依赖主内存进行数据存储的数据库管理系统。',0),(2176,35,'single','In DRDBMSs, each data access has to go to the to make sure data is still in main memory.','[\"CPU\",\"buffer manager\",\"file manager\",\"data manager\"]','\"buffer manager\"','在磁盘驻留数据库管理系统中，每次数据访问都必须经过缓冲区管理器，以确保数据仍在主内存中。',1),(2177,35,'single','In DRDBMSs have traditionally been the bottleneck.','[\"CPU access\",\"disk accesses\",\"pointer access\",\"cache access\"]','\"disk accesses\"','在磁盘驻留数据库管理系统中，磁盘访问传统上是性能瓶颈。',2),(2178,35,'single','To reduce the number of disk accesses, caching is used, and special index structures, like , were developed.','[\"the B+ tree\",\"the B tree\",\"the T tree\",\"the AVL tree\"]','\"the B+ tree\"','为了减少磁盘访问次数，使用了缓存技术，并开发了特殊的索引结构，如B+树。',3),(2179,35,'single','In MMDBMSs the are used as index structures.','[\"B+ trees\",\"I+ trees\",\"B trees\",\"AVL trees\"]','\"AVL trees\"','在主内存数据库管理系统中，AVL树被用作索引结构。',4),(2180,35,'single','The is a binary search tree whose nodes contain more than one item to reduce the number of calls to the main memory management and to reduce the amount of memory consumed by pointers.','[\"B+ tree\",\"AVL tree\",\"B tree\",\"T tree\"]','\"T tree\"','T树是一种二叉搜索树，其节点包含多个项目，以减少对主内存管理的调用次数并减少指针消耗的内存。',5),(2181,35,'single','In MMDBs, one common mechanism is to besides using backup copies of the data, which can protect data in case of a failure.','[\"logging to disk\",\"checkpointing\",\"B tree\",\"cache access\"]','\"logging to disk\"','在主内存数据库中，除了使用数据备份副本外，一种常见的机制是记录日志到磁盘，这可以在发生故障时保护数据。',6),(2182,35,'single','can optimize the cache performance to achieve an additional speedup.','[\"B+ tree\",\"Cache-sensitive search trees\",\"B tree\",\"T tree\"]','\"Cache-sensitive search trees\"','缓存敏感搜索树可以优化缓存性能以实现额外的加速。',7),(2183,35,'single','One very expensive solution for a faster response time and guarantee persistence is to use .','[\"flash ROM\",\"hard disk\",\"solid-state disks\",\"floppy disk\"]','\"solid-state disks\"','固态硬盘是一种非常昂贵的解决方案，用于获得更快的响应时间并保证持久性。',8),(2184,35,'single','One commonly used mechanism is ,which can keep the time needed for a database recovery short and guarantee that the backup of database is kept up-to-date.','[\"checkpointing\",\"committing transactions\",\"pointer\",\"group committing\"]','\"checkpointing\"','检查点是一种常用机制，可以保持数据库恢复所需的时间较短，并确保数据库备份是最新的。',9),(2185,35,'judge','In MMDBMSs the situation is different: Since data is guaranteed to stay present in main memory, index structures and all the other parts of the database need to consider disk access and can be tuned for low computational cost.','[]','false','在主内存数据库管理系统中，由于数据保证驻留在主内存中，索引结构和数据库的所有其他部分不需要考虑磁盘访问，可以针对低计算成本进行优化。',10),(2186,35,'judge','In 1984, D.J.De Witt first put forward the concept of \"Main memory database\" in his paper.','[]','false','主内存数据库的概念最初由D.J. DeWitt在1984年的论文中提出。',11),(2187,35,'judge','In the time required for one single disk access, a processor can perform up to several million instructions.','[]','true','在单个磁盘访问所需的时间内，处理器可以执行多达数百万条指令。',12),(2188,35,'judge','DRDBMSs have an edge over MMDBMSs in some respects since many simplifications can be used that reduce the processing power required when data is guaranteed to be in main memory.','[]','false','在主内存数据库管理系统中，由于数据保证在主内存中，可以使用许多简化技术来减少所需的处理能力，因此MMDBMS在某些方面具有优势。',13),(2189,35,'judge','The B+ tree, a special index structures, was developed for DRDBMSs.','[]','true','B+树是一种特殊的索引结构，是为磁盘驻留数据库管理系统开发的。',14),(2190,35,'judge','A DRDBMSron data being cached in main memory.','[]','false','磁盘驻留数据库管理系统依赖数据在主内存中缓存。',15),(2191,35,'judge','MMDBMSs must not be able to support the ACID properties known from conventional at a base systems.','[]','true','主内存数据库管理系统必须能够支持传统数据库系统所知的ACID属性。',16),(2192,35,'judge','A commit in MMDB must be able to guarantee persistence.','[]','true','在主内存数据库中，提交必须能够保证持久性。',17),(2193,35,'judge','A very small block size can be used in MMDBs since small blocks can be written to disk more efficiently.','[]','true','在主内存数据库中可以使用非常小的块大小，因为小数据块可以更高效地写入磁盘。',18),(2194,35,'judge','Data in main memory is not lost after a failure of computer system and during a simple restart of the system.','[]','false','计算机系统故障后和简单重启期间，主内存中的数据会丢失，因为主内存是易失性存储器。',19),(2195,35,'short','The key difference is that in an MMDBMS the primary copy of the database lives permanently in main memory ______.','[]','\"The primary copy of the database lives permanently in main memory\"','关键区别在于，在主内存数据库管理系统中，数据库的主副本永久驻留在主内存中。',20),(2196,35,'short','Both conventional disk resident database management systems (DRDBMSs) and main memory database management systems (MMDBMSs) process data in main memory , and both keep a (backup) copy on ______.','[]','\"disk\"','传统的磁盘驻留数据库管理系统和主内存数据库管理系统都在主内存中处理数据，并且都在磁盘上保留一个（备份）副本。',21),(2197,35,'short','The main memory database characterize many excellent features, such as, ______ high throughput rate ______ and low access delay ______, parallel processing power.','[]','\"high throughput rate, low access delay\"','主内存数据库具有许多优秀特性，如高吞吐率、低访问延迟和并行处理能力。',22),(2198,35,'short','The development of MMDB goes through the ______ periods.','[]','\"three\"','主内存数据库的发展经历了三个时期。',23),(2199,35,'short','The most important optimizations in disk-based systems are to ______, to disk accesses ______, prefer sequential access, and to keep the processor busy while waiting for I/O.','[]','\"Reduce the number of disk accesses\"','基于磁盘的系统中最重要的是减少磁盘访问次数、优先顺序访问以及在等待I/O时保持处理器忙碌。',24),(2200,35,'short','In MMDBMSs, performance is only determined by ______ the CPU efficiency of the algorithms used.','[]','\"the CPU efficiency of the algorithms\"','在主内存数据库管理系统中，性能仅取决于所用算法的CPU效率。',25),(2201,35,'short','Main memory is ______ and is lost ______ in case of a power failure.','[]','\"volatile, lost\"','主内存是易失性的，在电源故障时会丢失数据。',26),(2202,35,'short','Another solution to guarantee persistence is by logging ______ using a distributed , fault-tolerant write cache.','[]','\"logging\"','保证持久性的另一种解决方案是通过使用分布式、容错的写缓存进行日志记录。',27),(2203,35,'short','In order to reduce the response time, ______ solid-state disks ______ and eliminate the disk access are used to solve this problem.','[]','\"solid-state disks, eliminate the disk access\"','为了减少响应时间，使用固态硬盘并消除磁盘访问来解决这个问题。',28),(2204,35,'short','To achieve maximum parallelism, ______ looking granularity ______ should be as small as possible.','[]','\"Locking granularity\"','为了实现最大并行性，锁定粒度应尽可能小。',29),(2205,35,'multiple','The main memory database has many excellent features, which of the following options are features of main memory databases?','[\"high throughput rate\",\"medium access delay\",\"Excellent parallel processing power\",\"High hardware dependencies\"]','[\"high throughput rate\",\"Excellent parallel processing power\"]','主内存数据库具有高吞吐率和优秀的并行处理能力等特性。',30),(2206,35,'multiple','Which three periods did MMDB go through?','[\"the period of main memory database rudiment\",\"the period of research and development for main memory database\",\"the period of products growth\",\"the period of disk resident databases\"]','[\"the period of main memory database rudiment\",\"the period of research and development for main memory database\",\"the period of products growth\"]','主内存数据库经历了萌芽期、研发期和产品成长期三个时期。',31),(2207,35,'multiple','Which of the following options belongs to the ACID properties?','[\"atomicity\",\"consistency\",\"isolation\",\"durability\"]','[\"atomicity\",\"consistency\",\"isolation\",\"durability\"]','ACID属性包括原子性、一致性、隔离性和持久性。',32),(2208,35,'multiple','Which of the following options belong to recovery tasks?','[\"Automatic uses checkpoint\",\"redo log\",\"archive/restore\",\"fault tolerant\"]','[\"Automatic uses checkpoint\",\"redo log\",\"archive/restore\"]','恢复任务包括自动使用检查点、重做日志和归档/恢复。',33),(2209,35,'multiple','What are the differences between main memory database and disk resident database?','[\"access time\",\"data storage\",\"buffer management\",\"index structure\",\"concurrency control\",\"query optimization\"]','[\"access time\",\"data storage\",\"buffer management\",\"index structure\",\"concurrency control\",\"query optimization\"]','主内存数据库和磁盘驻留数据库在访问时间、数据存储、缓冲区管理、索引结构、并发控制和查询优化等方面存在差异。',34),(2210,35,'multiple','Which of the following products belong to main memory database?','[\"Redis\",\"SQLite\",\"Oracle\",\"MySQL\"]','[\"Redis\"]','Redis是主内存数据库产品，而SQLite、Oracle和MySQL主要是磁盘驻留数据库。',35),(2281,38,'single','AI stands for','[\"Automatic Intelligence\",\"Artificial Intelligence\",\"Automatic Information\",\"Artificial Information\"]','\"Artificial Intelligence\"','AI是人工智能（Artificial Intelligence）的缩写。',0),(2282,38,'single','All of the following are examples of AI application fields, except','[\"Apple Watch\",\"Microsoft Excel\",\"Da Vinci robot\",\"YuMi\"]','\"Microsoft Excel\"','Microsoft Excel是电子表格软件，不属于AI应用领域，而Apple Watch、Da Vinci机器人和YuMi都涉及AI技术。',1),(2283,38,'single','Which one of the following questions can be solved through intuition and reasoning?','[\"Numeric\",\"Logical\",\"Unstructured\",\"Structured\"]','\"Unstructured\"','非结构化问题通常需要通过直觉和推理来解决，而数值、逻辑和结构化问题有明确的解决路径。',2),(2284,38,'single','Which one of the following is not a long-term goal of AI research?','[\"social intelligence\",\"creativity\",\"general intelligence\",\"special intelligence\"]','\"special intelligence\"','AI研究的长期目标包括社会智能、创造力和通用智能，而不是特殊智能。',3),(2285,38,'single','There are three types of machine learning, except:','[\"unsupervised learning\",\"supervised learning\",\"associate learning\",\"reinforcement learning\"]','\"associate learning\"','机器学习的主要类型包括监督学习、无监督学习和强化学习，关联学习不是主要类型。',4),(2286,38,'single','Which of the following does not pertain(适用) to an expert system?','[\"It is a type of artificial intelligence.\",\"It uses a database containing facts and rules to relate these facts.\",\"The sequence of processing is not determined by the interaction of the user and the knowledge base.\",\"It uses fuzzy logic.\"]','\"The sequence of processing is not determined by the interaction of the user and the knowledge base.\"','专家系统的处理顺序通常由用户与知识库的交互决定，而不是独立确定的。',5),(2287,38,'single','Perception system robots.','[\"act as a transportation system, like a \\\"mailmobile\\\".\",\"imitate some human senses.\",\"perform manufacturing tasks like painting cars.\",\"are another name for virtual reality.\"]','\"imitate some human senses.\"','感知系统机器人模仿人类的某些感官能力，如视觉、听觉等。',6),(2288,38,'single','May 1997, the famous \"man-machine war\", a computer defeated the world chess champion Garry Kasparov. The computer is called','[\"Deep Blue\",\"IBM\",\"Ponder\",\"Blue Sky\"]','\"Deep Blue\"','1997年，IBM的深蓝计算机击败了国际象棋世界冠军加里·卡斯帕罗夫。',7),(2289,38,'single','Duda, Stanford university, who developed expert system for geological prospecting.','[\"PROSPECTOR\",\"MYCIN\",\"DENDRL\",\"MACSYMA\"]','\"PROSPECTOR\"','斯坦福大学开发的PROSPECTOR是用于地质勘探的专家系统。',8),(2290,38,'single','Which of the following is not the application of artificial intelligence?','[\"APPLE WATCH\",\"Google Atlas5\",\"ABB\'s YuMi\",\"Galaxy No-1 supercomputer\"]','\"Galaxy No-1 supercomputer\"','天河一号超级计算机是高性能计算系统，不是专门的人工智能应用，而其他选项都涉及AI技术。',9),(2291,38,'judge','We have achieved artificial intelligence that corresponds to human intelligence.','[]','false','目前我们尚未实现与人类智能相当的人工智能，现有AI系统在通用性和理解能力上仍有局限。',10),(2292,38,'judge','Machine learning is a way to get intelligence machine.','[]','false','机器学习是实现智能机器的一种方法，但不是唯一方法，AI还包括符号推理、知识表示等其他方法。',11),(2293,38,'judge','Field of artificial intelligence research as a discipline founded in 1956.','[]','true','人工智能研究作为一个学科领域，于1956年在达特茅斯会议上正式确立。',12),(2294,38,'judge','The goal of artificial intelligence is to allow machines to think for people.','[]','true','人工智能的目标是让机器能够为人类思考，执行需要智能的任务。',13),(2295,38,'judge','The golden age of artificial intelligence is 1956-1974.','[]','true','人工智能的黄金时代是1956年至1974年，期间AI研究取得重要进展并获得大量资金支持。',14),(2296,38,'judge','Robots can replace humans in hazardous environments.','[]','true','机器人可以在危险环境中替代人类工作，如核辐射环境、深海勘探等。',15),(2297,38,'judge','Expert systems use a type of database known as a knowledge base in order to provide assistance to users.','[]','true','专家系统使用称为知识库的数据库来存储领域知识和规则，为用户提供帮助。',16),(2298,38,'judge','Artificial intelligence short-term goal is to make existing computers not only do numerical data processing in general and non-numerical information, but also are able to use knowledge processing problems and even simulate the human part of intelligent behavior.','[]','true','人工智能的短期目标是使计算机不仅能处理数值数据和非数值信息，还能使用知识处理问题，甚至模拟人类的部分智能行为。',17),(2299,38,'judge','MYCIN expert system that is made by Feigenbaum is used to assist physicians in the diagnosis of bacterial infection disease, and to provide the best prescription.','[]','true','MYCIN是由费根鲍姆等人开发的专家系统，用于协助医生诊断细菌感染疾病并提供最佳处方。',18),(2300,38,'judge','Industrial robots are used extensively in the automotive industry.','[]','true','工业机器人广泛应用于汽车制造业，执行焊接、装配、喷涂等任务。',19),(2301,38,'short','The central problems of AI research include , reasoning ______ , knowledge ______ , planning learning, _natural language processing ______ , perception and the ability to move and manipulate objects.','[]','\"reasoning, knowledge, natural language processing\"','AI研究的核心问题包括推理、知识表示、规划学习、自然语言处理、感知以及移动和操纵物体的能力。',20),(2302,38,'short','Expert system realized the artificial intelligence from ______ theory search ______ to ______ specialized knowledge application ______ , and is an important breakthrough in the history of the development of AI.','[]','\"theory search, specialized knowledge application\"','专家系统实现了人工智能从理论搜索到专业知识应用的转变，是AI发展史上的重要突破。',21),(2303,38,'short','Expert ______ systems, also known as knowledge-based systems, are a type of artificial intelligence that uses a database to provide assistance to users.','[]','\"Expert\"','专家系统，也称为基于知识的系统，是一种使用数据库为用户提供帮助的人工智能。',22),(2304,38,'short','The long-term goals in the research pertaining to artificial intelligence are ______, and general intelligence ______.','[]','\"social intelligence, creativity, general intelligence\"','人工智能研究的长期目标包括社会智能、创造力和通用智能。',23),(2305,38,'short','Knowledge-representation is the field of artificial intelligence that focuses on designing computer representations that capture information about the world that can be used to solve complex problems.','[]','\"Knowledge-representation\"','知识表示是人工智能的一个领域，专注于设计能够捕捉世界信息的计算机表示，用于解决复杂问题。',24),(2306,38,'short','Machine learning is the study of computer algorithms that improve automatically through experience ______.','[]','\"experience\"','机器学习是研究通过经验自动改进的计算机算法的学科。',25),(2307,38,'short','Regression is the attempt to produce a function that describes the relationship between inputs and outputs and predicts how the outputs should change as the inputs change.','[]','\"Regression\"','回归分析试图产生一个描述输入和输出之间关系的函数，并预测输出如何随输入变化而变化。',26),(2308,38,'short','Robotics are computer-controlled machines often used to handle dangerous and repetitive tasks.','[]','\"Robotics\"','机器人技术是计算机控制的机器，常用于处理危险和重复性任务。',27),(2309,38,'short','Atlas is a ______ which has a high degree of mobility.','[]','\"humanoid robot\"','Atlas是一个具有高度移动性的人形机器人。',28),(2310,38,'short','Leonardo\'s robot is clad in German-Italian medieval armor, and is able to make several human-like motions.','[]','\"Leonardo\'s robot\"','莱昂纳多的机器人穿着德意中世纪盔甲，能够做出几种类似人类的动作。',29),(2311,38,'multiple','Which of the following options belong to the cores or goals of AI research?','[\"reasoning and knowledge\",\"planning and learning\",\"natural language processing (communication)\",\"perception and the ability to move and manipulate objects\"]','[\"reasoning and knowledge\",\"planning and learning\",\"natural language processing (communication)\",\"perception and the ability to move and manipulate objects\"]','AI研究的核心目标包括推理和知识、规划和学习、自然语言处理（通信）、感知以及移动和操纵物体的能力。',30),(2312,38,'multiple','Which of the following options belong to the approaches to obtain these objectives of the first question?','[\"statistical methods\",\"computational intelligence\",\"traditional symbolic AI\",\"try to think\"]','[\"statistical methods\",\"computational intelligence\",\"traditional symbolic AI\"]','实现AI目标的方法包括统计方法、计算智能和传统符号AI，\"try to think\"不是具体的技术方法。',31),(2313,38,'multiple','Which of the following options belong to a large number of tools used in AI area?','[\"search\",\"mathematical\",\"optimization logic\",\"methods based on probability and economics\"]','[\"search\",\"mathematical\",\"optimization logic\",\"methods based on probability and economics\"]','AI领域使用的大量工具包括搜索、数学方法、优化逻辑以及基于概率和经济学的方法。',32),(2314,38,'multiple','The AI field is interdisciplinary:','[\"computer science and linguistics\",\"mathematics and psychology\",\"philosophy and neuroscience\",\"other specialized fields such as artificial psychology\"]','[\"computer science and linguistics\",\"mathematics and psychology\",\"philosophy and neuroscience\",\"other specialized fields such as artificial psychology\"]','AI领域是跨学科的，涉及计算机科学和语言学、数学和心理学、哲学和神经科学以及其他专业领域如人工心理学。',33),(2315,39,'single','In a 2001 research report and related lectures, Gartner defined data growth challenges and opportunities as being three-dimensional, except ______','[\"volume\",\"velocity\",\"variety\",\"veracity\"]','\"veracity\"','Gartner在2001年最初提出的大数据3V特征包括Volume（体量）、Velocity（速度）和Variety（多样性），Veracity（真实性）是后来增加的维度。',0),(2316,39,'single','This property of the data determines the value and potential of the data under consideration, and whether it can actually be considered big data or not.','[\"volume\",\"velocity\",\"variety\",\"veracity\"]','\"veracity\"','数据的真实性（Veracity）决定了所考虑数据的价值和潜力，以及是否真正能被视作大数据。',1),(2317,39,'single','The big data sets can be obtained from the physical world, such as','[\"economics\",\"sensor networks\",\"social networks\",\"transportation\"]','\"sensor networks\"','来自物理世界的大数据集可以通过传感器网络获取，如环境监测、物联网设备等。',2),(2318,39,'single','The big data sets produced by human activities are','[\"scientific experiments\",\"sensor networks\",\"social networks\",\"genome projects\"]','\"social networks\"','由人类活动产生的大数据集包括社交媒体数据，而科学实验、传感器网络和基因组项目更多属于科学或物理世界数据。',3),(2319,39,'single','Amazon uses customer data to power its recommendation engine \"you may also like ...\" based on a type of predictive modeling technique called .','[\"loyalty program\",\"tailor marketing\",\"collaborative filtering\",\"vendor-managed inventory\"]','\"collaborative filtering\"','亚马逊使用协同过滤技术为其推荐引擎\"您可能还喜欢...\"提供支持，这种预测建模技术基于用户行为和偏好相似性。',4),(2320,39,'single','Who believes that scientific discovery has experienced four paradigms.','[\"McKinsey\",\"Ginnirometry\",\"Jim Gray\",\"Alan Turning\"]','\"Jim Gray\"','Jim Gray（吉姆·格雷）提出了科学发现的四个范式理论。',5),(2321,39,'single','This is the fourth paradigm for scientific exploration.','[\"experimental science\",\"theoretical science\",\"computational science\",\"data-intensive science\"]','\"data-intensive science\"','数据密集型科学是科学探索的第四范式，强调从海量数据中发现知识和规律。',6),(2322,39,'single','Software efficiency and effectiveness have to do with','[\"size and speed of storage systems\",\"architects and algorithms\",\"CPU frequency and parallelism\",\"communication bandwidth.\"]','\"architects and algorithms\"','软件的效率和有效性与架构和算法密切相关，好的架构和算法设计能显著提升软件性能。',7),(2323,39,'single','How to cope with uncertainty, imprecision, missing values, misstatements or untruths is the challenge of','[\"volume\",\"velocity\",\"variety\",\"veracity\"]','\"veracity\"','处理不确定性、不精确性、缺失值、错误陈述或虚假信息是大数据真实性（Veracity）面临的挑战。',8),(2324,39,'single','These are feasible and effective techniques for data reduction except','[\"indexing\",\"sampling\",\"aggregation\",\"dimension reduction\"]','\"indexing\"','索引是数据组织技术，不是数据缩减技术。数据缩减技术包括采样、聚合和维度缩减等。',9),(2325,39,'judge','Big data \"size\" is a constantly moving target.','[]','true','大数据的\"大小\"是一个不断变化的目标，随着技术进步和数据增长，对大数据的定义也在不断演变。',10),(2326,39,'judge','Velocity is an indication of data integrity and the ability for an organization to trust the data and be able to confidently use it to make crucial decisions.','[]','false','Velocity指的是数据生成和处理的速度，而不是数据完整性或可信度，后者是Veracity（真实性）的特征。',11),(2327,39,'judge','Facebook currently holds more than 45 billion photos in its user database, a number that is growing daily.','[]','true','Facebook用户数据库拥有超过450亿张照片，这个数字每天都在增长，体现了大数据的体量特征。',12),(2328,39,'judge','Large companies across the globe have scored early successes in their use of big data.','[]','true','全球各大公司在大数据应用方面已取得早期成功，如亚马逊的推荐系统、沃尔玛的库存管理等。',13),(2329,39,'judge','There are notable examples of companies around the globe that are well-known for their extensive and effective use of data, including Tesco\'s loyalty program, Amazon\'s collaborative filtering, Harrah\'s tailor marketing, and Wal-Mart\'s vendor-managed inventory.','[]','true','全球有许多公司以广泛有效使用数据而闻名，如乐购的忠诚度计划、亚马逊的协同过滤、哈拉斯的精准营销和沃尔玛的供应商管理库存。',14),(2330,39,'judge','The McKinsey report pointed out that big data may give a full play to the economic function, improve the productivity and competitiveness of enterprises and public sectors.','[]','true','麦肯锡报告指出，大数据可以充分发挥经济功能，提高企业和公共部门的生产力和竞争力。',15),(2331,39,'judge','In the last few hundred years, there was theoretical science, with Kepler\'s Laws, Newton\'s Laws of Motion, Maxwell\'s equations, and so on. This is the third paradigm.','[]','false','理论科学（如开普勒定律、牛顿运动定律、麦克斯韦方程等）是第二范式，而不是第三范式。第三范式是计算科学。',16),(2332,39,'judge','\"Database machine\" is a technology specially used for storing and analyzing data.','[]','true','\"数据库机器\"是专门用于存储和分析数据的技术。',17),(2333,39,'judge','The concept of big data was first proposed on a research report titled Extracting Values from Chaos in June 2011.','[]','false','大数据概念最早可以追溯到更早的时期，2011年的报告《从混沌中提取价值》是其中重要的里程碑，但不是首次提出。',18),(2334,39,'judge','The challenge of big data veracity is how to handle multiplicity of types, sources, and formats.','[]','false','处理多种类型、来源和格式的多样性是Variety（多样性）的挑战，而不是Veracity（真实性）的挑战。',19),(2335,39,'short','Big data ______ is a broad term for data sets so large or complex that traditional data processing applications are inadequate.','[]','\"Big data\"','大数据指的是那些规模巨大或复杂到传统数据处理应用程序无法处理的数据集。',20),(2336,39,'short','Big data draws from different types of structured and unstructured data, such as transaction data, video, audio, text and log files. This is one of big data\'s four V properties called ______.','[]','\"variety\"','大数据来源于不同类型的结构化和非结构化数据，如交易数据、视频、音频、文本和日志文件，这是大数据的四个V特征之一的多样性（Variety）。',21),(2337,39,'short','Big data can be partitioned into two categories data from the physical world ______, and data from human activities.','[]','\"data from the physical world\"','大数据可以分为两类：来自物理世界的数据和来自人类活动的数据。',22),(2338,39,'short','Sensor networks consisting of large number of cheap sensors ______ have been widely used to obtained natural data.','[]','\"sensors\"','由大量廉价传感器组成的传感器网络已被广泛用于获取自然数据。',23),(2339,39,'short','Like what steam power was to the 18th century, electromagnetism to the 19th and fossil fuels to the 20th data ______, will be to the 21st.','[]','\"data\"','就像蒸汽动力对18世纪、电磁学对19世纪、化石燃料对20世纪一样，数据将是21世纪的关键资源。',24),(2340,39,'short','Originally, there was just experimental science describing natural phenomena, which is called the ______ paradigm.','[]','\"first\"','最初只有描述自然现象的实验科学，这被称为第一范式。',25),(2341,39,'short','In the third paradigm, we use simulation ______ to analyze theoretical models.','[]','\"simulations\"','在第三范式中，我们使用模拟来分析理论模型。',26),(2342,39,'short','The ______ architecture is based on the use of cluster and every machine has its own processor, storage, and disk.','[]','\"share nothing system\"','无共享（share nothing）架构基于集群的使用，每台机器都有自己的处理器、存储和磁盘。',27),(2343,39,'short','In late 1990s, the advantage of the parallel ______ database was widely recognized in the database field.','[]','\"parallel\"','20世纪90年代后期，并行数据库的优势在数据库领域得到广泛认可。',28),(2344,39,'short','The challenge of big data ______ comes with the needs to timely generate results and process arriving data.','[]','\"velocity\"','大数据的速度（Velocity）挑战来自于需要及时生成结果和处理到达的数据。',29),(2345,39,'multiple','What are the four dimensions of big data?','[\"Volume\",\"Velocity\",\"Variety\",\"Veracity\"]','[\"Volume\",\"Velocity\",\"Variety\",\"Veracity\"]','大数据的四个维度是体量（Volume）、速度（Velocity）、多样性（Variety）和真实性（Veracity）。',30),(2346,39,'multiple','Big data is ubiquitous, what two categories can it be partitioned into?','[\"Data from the physical world\",\"Data from human activities\",\"Data from the world\",\"Data from human\"]','[\"Data from the physical world\",\"Data from human activities\"]','大数据无处不在，可以分为来自物理世界的数据和来自人类活动的数据两类。',31),(2347,39,'multiple','According to Jim Gray, what are the four paradigms of scientific discovery?','[\"Experimental Science\",\"Theoretical Science\",\"Computational Science\",\"Data-intensive Science\"]','[\"Experimental Science\",\"Theoretical Science\",\"Computational Science\",\"Data-intensive Science\"]','根据Jim Gray的理论，科学发现的四个范式是实验科学、理论科学、计算科学和数据密集型科学。',32),(2348,39,'multiple','What are the challenges of big data?','[\"Data volume\",\"Big data velocity\",\"Data from various sources\",\"Data reduction\"]','[\"Data volume\",\"Big data velocity\",\"Data from various sources\"]','大数据的主要挑战包括数据体量、数据处理速度和数据来源多样性。',33),(2385,41,'single','Which one of the following is one of the first recognizably modern embedded systems?','[\"Galaxy One\",\"Apollo Guidance Computer (AGC)\",\"Shuguang Computer\",\"Zijin Computer\"]','\"Apollo Guidance Computer (AGC)\"','阿波罗制导计算机（AGC）是最早的现代嵌入式系统之一，用于阿波罗太空任务。',0),(2386,41,'single','The third Information Technology Revolution refers to .','[\"Internet\",\"Internet of Things\",\"Reading China\",\"Smart Earth\"]','\"Internet of Things\"','第三次信息技术革命指的是物联网（Internet of Things）。',1),(2387,41,'single','Which one of the following is not a feature of the Internet of Things?','[\"miniaturization\",\"low-power dissipation\",\"big density\",\"Giganticism\"]','\"Giganticism\"','物联网的特点包括小型化、低功耗、高密度，而不是巨型化。',2),(2388,41,'single','Analysts commonly describe two distinct modes of communication in the Internet of Things: thing-to-person communication, and the other one is','[\"person-to-person communication\",\"person-to-thing communication\",\"thing-to-thing communication\",\"client-and-service communication\"]','\"thing-to-thing communication\"','物联网中通常描述的两种通信模式是物与人通信和物与物通信。',3),(2389,41,'single','Which one of the following is not a WSN\'s resource constraint?','[\"low bandwidth\",\"a limited amount of energy\",\"Heterogeneity of nodes\",\"short communication range\"]','\"Heterogeneity of nodes\"','无线传感器网络的资源约束包括低带宽、有限能量和短通信距离，而节点的异构性不是资源约束，是网络特性。',4),(2390,41,'single','Which one of the following is the effect of the \"active tags\" that is different from \"passive tags\"?','[\"read/write\",\"read only\",\"write only\",\"none of them\"]','\"read/write\"','有源标签与无源标签的区别在于有源标签通常具有读写功能，而无源标签主要是只读的。',5),(2391,41,'single','The WSN is built of \"nodes\", each such sensor network node has typically several parts, except','[\"a radio transceiver\",\"a microcontroller\",\"a microprocessor\",\"an energy source, usually a battery or an embedded form of energy harvesting\"]','\"a microprocessor\"','无线传感器网络节点通常包括无线电收发器、微控制器和能源（电池或能量收集装置），但不一定包含独立的微处理器。',6),(2392,41,'single','Which one of the following is not correct about RFID?','[\"RFID is the use of a wireless non-contact system.\",\"RFID is a generic term for technologies that use radio waves to automatically identify people or objects.\",\"The purposes of RFID is passively identification and tracking.\",\"RFID uses radio-frequency electromagnetic fields to transfer data from a tag attached to an object.\"]','\"The purposes of RFID is passively identification and tracking.\"','RFID的目的不仅限于被动识别和跟踪，还包括主动识别、数据读写等多种功能。',7),(2393,41,'single','Which one of the following is not an embedded system\'s main characteristic?','[\"User interface\",\"Ready-made computer boards\",\"Reliability\",\"Security\"]','\"Ready-made computer boards\"','嵌入式系统的主要特征包括用户界面、可靠性和安全性，而现成的计算机板不是其核心特征。',8),(2394,41,'single','Which one of the following is not the hardware for RFID?','[\"reader-writer\",\"QR code (two-dimension code)\",\"antenna\",\"electronic tags\"]','\"QR code (two-dimension code)\"','RFID硬件包括读写器、天线和电子标签，二维码不是RFID硬件，是另一种识别技术。',9),(2395,41,'judge','Furthermore, as the Internet is running out of addresses, in the last few and future years it is moving to a new protocol, IPv4.','[]','false','互联网地址耗尽后，未来几年将转向IPv6协议，而不是IPv4。',10),(2396,41,'judge','Thing-to-person (and person-to-thing) encompasses technologies and applications wherein everyday objects and infrastructure interact with no human originator, recipient, or intermediary.','[]','false','物与人（以及人与物）通信涉及日常物体和基础设施与人的交互，而不是没有人类发起者、接收者或中介的交互。',11),(2397,41,'judge','The more modern WSN are single-directional, also enabling control of sensor activity.','[]','false','更现代的无线传感器网络是双向的，不仅收集数据，还能控制传感器活动。',12),(2398,41,'judge','Smart sensor nodes are low power devices equipped with one or more sensors, a processor, memory, a power supply, a radio, and an actuator.','[]','true','智能传感器节点是低功耗设备，配备一个或多个传感器、处理器、内存、电源、无线电和执行器。',13),(2399,41,'judge','An arithmetic unit is an important unit in the embedded system hardware. It is the heart of the embedded system.','[]','false','处理器（CPU）是嵌入式系统的核心，而不是算术单元。',14),(2400,41,'judge','Today RFID is a generic term for technologies that use radio waves to automatically identify people or objects. There are several methods of identification, the most common of which is to associate the RFID tag unique identifier with an object or person.','[]','true','RFID是使用无线电波自动识别人员或物体的技术的通用术语，最常见的识别方法是将RFID标签的唯一标识符与物体或人员关联。',15),(2401,41,'judge','Adoption of RFID in the medical industry has been widespread and very effective. Hospitals are among the first users to combine both active and passive RFID technology.','[]','true','RFID在医疗行业的采用广泛且非常有效，医院是最早结合使用有源和无源RFID技术的用户之一。',16),(2402,41,'judge','RFID tags for animals represent one of the oldest uses of RFID technology. Originally meant for large ranches and rough terrain, since the outbreak of mad-cow disease, RFID has become crucial in animal identification management.','[]','true','动物RFID标签是RFID技术最古老的用途之一，最初用于大型牧场和崎岖地形，自疯牛病爆发以来，RFID在动物识别管理中变得至关重要。',17),(2403,41,'judge','Nanotechnology is the creation of ever-smaller scales for mechanical, optical, and electronic products and devices. Miniaturization is a continuing trend in the production of such devices.','[]','true','纳米技术是在机械、光学和电子产品及设备中创造越来越小的尺度，小型化是这些设备生产的持续趋势。',18),(2404,41,'judge','Mobile robots and wireless smart devices will be able to seamlessly interact and communicate with the environment, thereby contributing to the efficient, secure and inclusive nature of the European societies.','[]','true','移动机器人和无线智能设备将能够与环境无缝交互和通信，从而有助于欧洲社会的高效、安全和包容性。',19),(2405,41,'short','Since that time, visionaries have seized on the phrase **Internet of Things** ______ to refer to the general idea of things, especially everyday objects, which are readable, recognizable, locatable, addressable, and/or controllable via the Internet—whether via RFID, wireless LAN, wide-area network, or other means.','[]','\"Internet of Things\"','自那时起，有远见的人开始使用\"物联网\"这个短语来指代物体（特别是日常物品）可以通过互联网（无论是通过RFID、无线局域网、广域网还是其他方式）被读取、识别、定位、寻址和/或控制的一般概念。',20),(2406,41,'short','Mobile internet is an open-ended basic telecommunications website that takes broadband IP as technical core and simultaneously provides voice, data and multimedia services.','[]','\"Mobile internet\"','移动互联网是以宽带IP技术为核心，同时提供语音、数据和多媒体服务的开放式基础电信网络。',21),(2407,41,'short','An embedded system is a computer system designed for specific control functions within a larger system, often with real-time computing constraints. It is embedded as part of a complete device often including hardware and mechanical parts.','[]','\"embedded system\"','嵌入式系统是为在更大系统中执行特定控制功能而设计的计算机系统，通常具有实时计算约束，作为完整设备的一部分嵌入，通常包括硬件和机械部件。',22),(2408,41,'short','A _WSN_ consists of spatially distributed autonomous sensors to monitor physical or environmental conditions, such as temperature, sound, pressure, etc. and to cooperatively pass their data through the network to a main location.','[]','\"wireless sensor network (WSN)\"','无线传感器网络由空间分布的自主传感器组成，用于监测物理或环境条件（如温度、声音、压力等），并通过网络协作将数据传输到主位置。',23),(2409,41,'short','ZigBee is a specification for a suite of high level communication protocols using small, low-power digital radios based on an IEEE 802 standard for personal area networks.','[]','\"ZigBee\"','ZigBee是基于IEEE 802个人局域网标准的一系列高级通信协议的规范，使用小型低功耗数字无线电。',24),(2410,41,'short','RFID is the use of a wireless non-contact system that uses radio-frequency electromagnetic fields to transfer data from a tag attached to an object, for the purposes of automatic identification and tracking.','[]','\"RFID\"','RFID使用无线非接触式系统，利用射频电磁场从附着在物体上的标签传输数据，用于自动识别和跟踪。',25),(2411,41,'short','The topology of the WSNs can vary from a simple star network to an advanced _multi-hop wireless mesh network.','[]','\"multi-hop wireless mesh network\"','无线传感器网络的拓扑结构可以从简单的星形网络到先进的多跳无线网状网络。',26),(2412,41,'short','RFID devices fall into two broad categories: those with a power supply (a battery) and those without. An RFID device that actively transmitted to a reader is known as a transponder (transmitter/responder). Unpowered passive devices are known as _tags_.','[]','\"tags\"','RFID设备分为两大类：有电源（电池）的和无电源的。主动向阅读器传输的RFID设备称为应答器，无源设备称为标签。',27),(2413,41,'short','A sensor is a converter that measures a physical quantity and converts it into a signal which can be read by an observer or by an instrument.','[]','\"sensor\"','传感器是一种转换器，用于测量物理量并将其转换为可以被观察者或仪器读取的信号。',28),(2414,41,'short','A _smart system_ has an inherent ability to gather information on its operating environment or history, to process that information in order to draw intelligent inferences from it and to act on those inferences by changing its characteristics in an advantageous manner.','[]','\"smart system\"','智能系统具有收集其操作环境或历史信息的内在能力，处理这些信息以从中得出智能推断，并通过以有利的方式改变其特性来根据这些推断采取行动。',29),(2415,41,'multiple','Select three main kinds of Internet of things technologies from the following options.','[\"Wireless Sensor Network\",\"Embedded System\",\"RFID\",\"Other Technologies\"]','[\"Wireless Sensor Network\",\"Embedded System\",\"RFID\"]','物联网的三种主要技术是无线传感器网络、嵌入式系统和RFID技术。',30),(2416,41,'multiple','Which of the following options are the main characteristics of a WSN?','[\"Power consumption constrains for nodes using batteries or energy harvesting\",\"Ability to cope with node failures\",\"Mobility of nodes and Communication failures\",\"Heterogeneity of nodes and Scalability to large scale of deployment\"]','[\"Power consumption constrains for nodes using batteries or energy harvesting\",\"Ability to cope with node failures\",\"Mobility of nodes and Communication failures\",\"Heterogeneity of nodes and Scalability to large scale of deployment\"]','无线传感器网络的主要特征包括节点功耗限制、应对节点故障的能力、节点移动性和通信故障、节点异构性以及大规模部署的可扩展性。',31),(2417,41,'multiple','Select four characteristics of embedded system from the following options.','[\"User interface\",\"Processors in embedded systems\",\"Ready-made computer boards\",\"Reliability\"]','[\"User interface\",\"Processors in embedded systems\",\"Reliability\"]','嵌入式系统的特征包括用户界面、嵌入式处理器和可靠性，现成的计算机板不是其核心特征。',32),(2418,41,'multiple','Which of the following options belong to the applications of RFID?','[\"Transportation payments\",\"Animal identification\",\"Hospitals\",\"Healthcare\"]','[\"Transportation payments\",\"Animal identification\",\"Hospitals\",\"Healthcare\"]','RFID的应用包括交通支付、动物识别、医院和医疗保健等领域。',33),(2419,41,'multiple','Which of the following areas does the Internet of things have applications?','[\"Food\",\"Health\",\"Intelligent Home\",\"Car\"]','[\"Food\",\"Health\",\"Intelligent Home\",\"Car\"]','物联网在食品、健康、智能家居和汽车等领域都有应用。',34),(2580,47,'single','What is the content of the preservation in IE favorites?','[\"Web pages\",\"Web URL\",\"The content of the page screenshots\",\"The image of a web page\"]','\"Web URL\"','IE favorites store web URLs (Uniform Resource Locators) to quickly access specific websites later, rather than storing the entire web page, screenshots, or images of the page.',0),(2581,47,'single','The role of the Outlook is .','[\"File management\",\"Network operating system\",\"E-Mail management\",\"Disk management\"]','\"E-Mail management\"','Outlook is a software primarily used for email management, including sending, receiving, and organizing emails. It is not used for file management, network operating system functions, or disk management.',1),(2582,47,'single','User to query the WWW information on the Internet, it is necessary to install and run a software called ?','[\"HTTP\",\"YAHOO\",\"Explorer\",\"WWW\"]','\"Explorer\"','To access WWW information on the Internet, users need to install a web browser such as Explorer. HTTP is a network protocol, YAHOO is a website, and WWW is the World Wide Web, not a software.',2),(2583,47,'single','We move the mouse to the web pages on the part of the content above, found that the shape of the mouse hand type, this text on the page or icon we called .','[\"Collect\",\"Hyperlink\",\"E-mail\",\"Pointer\"]','\"Hyperlink\"','When the mouse cursor changes to a hand shape on a web page, it indicates that the corresponding text or icon is a hyperlink, which can redirect to another web page or resource when clicked.',3),(2584,47,'single','What is the basic meaning of the Internet?','[\"Computer connected with the computer\",\"Computer and computer network connections\",\"The computer network and computer network connections\",\"Domestic computer connected with the international computer\"]','\"The computer network and computer network connections\"','The Internet is essentially a global network formed by connecting multiple computer networks together, enabling interconnection and communication between different networks.',4),(2585,47,'single','If you want to connect to a WWW site, should begin with to write a uniform resource locator?','[\"shttp://\",\"http:s//\",\"http://\",\"ftp://\"]','\"http://\"','The uniform resource locator (URL) for WWW sites typically starts with \'http://\' (Hypertext Transfer Protocol). \'shttp://\' and \'http:s//\' are incorrect formats, and \'ftp://\' is used for File Transfer Protocol.',5),(2586,47,'single','In the WWW service, the user’s information retrieval can search automatically from a Web service to another Web server, all technology is ?','[\"HTML\",\"HYPERLINK\",\"HYPERTEXT\",\"HYPERMEDIA\"]','\"HYPERTEXT\"','Hypertext technology allows information retrieval to automatically jump from one web server to another by linking related text resources. HTML is a markup language, HYPERLINK refers to individual links, and HYPERMEDIA extends hypertext to include multimedia.',6),(2587,47,'single','According to the WWW service, in the following sentences what is wrong?','[\"The WWW service uses the main transport protocol is HTTP.\",\"The WWW service organization network multimedia information in hypertext manner.\",\"The user can access the Web server to use unified graphical user interface.\",\"The user to access the Web server does not need to know the server URL.\"]','\"The user to access the Web server does not need to know the server URL.\"','To access a web server, the user must know the server\'s URL (e.g., www.google.com) to locate and connect to it. The other options correctly describe the WWW service: using HTTP, organizing multimedia information in hypertext, and providing a unified graphical user interface.',7),(2588,47,'single','The following about the description of the mobile Internet, which is not correct?','[\"Mobile Internet is born of mobile communication technology and Internet technology integration\",\"Mobile Internet need to implement the user in the process of moving through mobile devices anytime, anywhere access to the Internet\",\"Mobile Internet access technology, core network, the Internet service of three parts\",\"Mobile Internet refers to the Internet in the mobile\"]','\"Mobile Internet refers to the Internet in the mobile\"','Mobile Internet is not simply the \'Internet in the mobile\' but a combination of mobile communication technology and Internet technology that allows users to access the Internet anytime and anywhere via mobile devices. It consists of access technology, core network, and Internet services.',8),(2589,47,'single','In mobile Internet protocol, is used for data representation of the agreement?','[\"HTTP\",\"REST\",\"TCP/IP\",\"HTML\"]','\"HTML\"','HTML (HyperText Markup Language) is used for data representation in mobile Internet, defining the structure and content of web pages. HTTP is a transfer protocol, REST is an architectural style, and TCP/IP is a network communication protocol suite.',9),(2590,47,'judge','The current mobile Internet competitive strength of the three major focus, the entrance of the mobile Internet users is the user the first point of contact.','[]','true','In mobile Internet competition, user entrances (such as app stores, browsers, or super apps) are crucial as they are the first point of contact for users to access mobile Internet services, determining user traffic and stickiness.',10),(2591,47,'judge','Use IE browser to browse the web, enter the url in the address bar, usually is http:// can be omitted.','[]','true','When using IE browser, entering a URL in the address bar often allows omitting \'http://\' as the browser can automatically supplement it to access the website.',11),(2592,47,'judge','Browsing the web, the following may leak privacy is the Cookie.','[]','true','Cookies are small data files stored by websites on the user\'s device, which may contain user preferences, login status, and other information. If improperly used, they may lead to privacy leaks.',12),(2593,47,'judge','The distinction between mobile Web applications and native applications is anticipated to become increasingly blurred.','[]','false','With the development of technologies such as progressive web apps (PWAs), the functions and experiences of mobile Web applications and native applications are becoming more similar, and their distinction is increasingly blurred, so the original statement is incorrect.',13),(2594,47,'judge','The first access to the mobile Internet was commercially offered in Finland in 1995.','[]','false','The first commercial mobile Internet service was not launched in Finland in 1995. The actual launch time and location vary by historical records, and Finland is not the first country to offer commercial mobile Internet access.',14),(2595,47,'judge','TCP protocol called The Transmission Control Protocol.','[]','true','TCP is the abbreviation of Transmission Control Protocol, which is a connection-oriented, reliable transmission protocol in the TCP/IP protocol suite.',15),(2596,47,'judge','Location-based services (LBS) are a general class of computer program-level services that use location data to control features.','[]','true','Location-based services (LBS) utilize user location data (obtained via GPS, base stations, etc.) to provide corresponding services or control functions, such as nearby merchant searches, navigation, etc.',16),(2597,47,'judge','Some problems which may be encountered include like small screen size.','[]','true','Mobile devices (the main access terminals for mobile Internet) often have small screen sizes, which is one of the practical problems encountered in mobile Internet use, such as inconvenient browsing of large web pages.',17),(2598,47,'judge','It is estimated by mobile app install ads accounted for 30% of all mobile advertising revenue in 2015.','[]','false','According to relevant statistics, mobile app install ads did not account for 30% of all mobile advertising revenue in 2015, so the statement is incorrect.',18),(2599,47,'judge','Mobile search is an evolving branch of information retrieval services.','[]','false','Mobile search is constantly developing and evolving with the popularization of mobile Internet and technological progress, becoming an important branch of information retrieval services, so the original statement is incorrect.',19),(2600,47,'multiple','What are the benefits of mobile Internet?','[\"Convenience and portability\",\"Timeliness and accuracy\",\"Tactile sense and directionality\",\"Range and Bandwidth\"]','[\"Convenience and portability\",\"Timeliness and accuracy\",\"Tactile sense and directionality\"]','Mobile Internet offers convenience and portability (access via mobile devices anytime, anywhere), timeliness and accuracy (quick access to updated information), and tactile sense and directionality (support for touch operations and location-based services). Range and bandwidth are more about technical characteristics rather than direct benefits.',20),(2601,47,'multiple','What are the limitations of mobile Internet?','[\"Range and Bandwidth\",\"Power consumption and Transmission interferences\",\"Potential health hazards\",\"Human interface with device\"]','[\"Range and Bandwidth\",\"Power consumption and Transmission interferences\",\"Potential health hazards\",\"Human interface with device\"]','Mobile Internet has limitations such as limited range and bandwidth (affected by network coverage and signal), high power consumption of mobile devices, transmission interference (from environmental factors), potential health hazards (long-term use of mobile devices), and constraints of human-device interface (small screen, limited operation space).',21),(2602,47,'multiple','Which of the following options belongs to the mobile Internet standards?','[\"OMA Standards\",\"W3C Standards\",\"Standardization of Chinese Mobile Internet\",\"Mobile browse\"]','[\"OMA Standards\",\"W3C Standards\",\"Standardization of Chinese Mobile Internet\"]','OMA Standards (Open Mobile Alliance), W3C Standards (World Wide Web Consortium), and Standardization of Chinese Mobile Internet are all relevant standards for mobile Internet. Mobile browse is a browsing behavior or function, not a standard.',22),(2603,47,'multiple','The CCSA has worked in the fields of.','[\"WAP, Java, mobile browse\",\"Multimedia Message Service, Mobile Email\",\"push-to-talk, real-time status, XDM, Instant Messaging\",\"Secure User Plane Location, and mobile broadcast\"]','[\"WAP, Java, mobile browse\",\"Multimedia Message Service, Mobile Email\",\"push-to-talk, real-time status, XDM, Instant Messaging\",\"Secure User Plane Location, and mobile broadcast\"]','CCSA (China Communications Standards Association) is involved in formulating standards in multiple mobile Internet-related fields, including WAP, Java, mobile browse, Multimedia Message Service, Mobile Email, push-to-talk, real-time status, XDM, Instant Messaging, Secure User Plane Location, and mobile broadcast.',23),(2604,47,'multiple','Which of the following options belongs to the mobile Internet business patterns?','[\"Mobile Social\",\"Mobile Advertising\",\"Mobile Location-based Services\",\"Mobile Search\"]','[\"Mobile Social\",\"Mobile Advertising\",\"Mobile Location-based Services\",\"Mobile Search\"]','Common mobile Internet business models include Mobile Social (social interaction via mobile devices), Mobile Advertising (advertising on mobile platforms), Mobile Location-based Services (services based on user location), and Mobile Search (information search on mobile devices).',24),(2605,47,'multiple','What are the prospects for mobile Internet applications?','[\"Market reshuffle produces new winners\",\"From fun to habits:Changing business drivers\",\"Mobile Game and Mobile TV\",\"Mobile E-commerce\"]','[\"Market reshuffle produces new winners\",\"From fun to habits:Changing business drivers\",\"Mobile Game and Mobile TV\",\"Mobile E-commerce\"]','The prospects of mobile Internet applications include market reshuffling leading to new leading enterprises, business drivers shifting from entertainment to daily habits, the continuous development of Mobile Game and Mobile TV, and the vigorous growth of Mobile E-commerce.',25),(2783,54,'single','Suppose a computer wants to send a packet on Ethernet. What does the computer first wait for?','[\"Waits for its scheduled time in the predetermined transmission schedule\",\"Waits for the central Ethernet controller to signal that transmission is now permitted\",\"Waits for the recipient computer to signal that it is ready\",\"Waits for the Ethernet wire to be idle\"]','\"Waits for the Ethernet wire to be idle\"','以太网采用CSMA/CD机制，发送前先侦听链路是否空闲。',0),(2784,54,'single','For transmission, the 50 KB of the image is divided into packets. If each packet is about 1500 bytes, how many packets are needed?','[\"30\",\"34\",\"36\",\"40\"]','\"34\"','50 KB = 51 200 bytes；51 200 ÷ 1500 ≈ 34.13，向上取整得34个完整数据包。',1),(2785,54,'single','Which one is NOT a feature of Ethernet?','[\"Shared\",\"Distributed and Collaborative\",\"Secure\",\"Performance degrades with load\"]','\"Secure\"','以太网本身不提供加密或认证机制，安全性需由高层协议实现。',2),(2786,54,'single','Which of the following is NOT a valid IPv4 address?','[\"192.168.0.1\",\"10.0.0.256\",\"172.16.5.4\",\"8.8.8.8\"]','\"10.0.0.256\"','IPv4每个字节取值0-255，256超出范围。',3),(2787,54,'single','Which statement about routers is generally NOT true?','[\"Routers check a central internet-map which shows routes for all packets\",\"Routers get packets from computers and forward them on\",\"Routers continuously monitor the status of their connections\",\"Routers forward each packet one hop closer to its final destination\"]','\"Routers check a central internet-map which shows routes for all packets\"','路由器使用分布式路由协议动态计算路径，不存在全球集中式“互联网地图”。',4),(2788,54,'single','What does the ping utility do?','[\"Sends a \'who is there\' packet and gets back a description of the network\",\"Sends an \'are you there\' packet to a host and waits for an echo reply\",\"Notifies the local router that the computer wants no more packets\",\"Requests the server URL list\"]','\"Sends an \'are you there\' packet to a host and waits for an echo reply\"','Ping使用ICMP Echo Request/Reply检测主机可达性。',5),(2789,54,'single','Which of the following is the worst password?','[\"snyrk34\",\"XXagflib1\",\"XXagflib\",\"Password\"]','\"Password\"','常用字典单词且首字母大写，极易被暴力破解。',6),(2790,54,'single','Which best describes a phishing attack?','[\"Tricking the victim into logging in to a fake but realistic-looking website\",\"Continuously guessing passwords until access is gained\",\"Intercepting login packets to extract credentials\",\"Physically breaking into the victim\'s house to find written passwords\"]','\"Tricking the victim into logging in to a fake but realistic-looking website\"','钓鱼通过伪造站点诱骗用户主动输入敏感信息。',7),(2791,54,'single','Which email is most likely a Trojan attack?','[\"Please visit www.scwhab.bad-guy.ru and log in—standard page broken\",\"We detected a virus; download and install this program to clean it\",\"I have 27 million dollars in Spain; help me transfer and get 10%\",\"Important message from your bank—email us your password for verification\"]','\"We detected a virus; download and install this program to clean it\"','诱导用户运行附件或程序，是典型的木马植入方式。',8),(2792,54,'single','What is the best way to avoid attacks via software vulnerabilities?','[\"Reboot your machine every morning\",\"Avoid websites with cat pictures\",\"Keep all internet-facing software updated to the latest version\",\"Always use a fake identity on forums\"]','\"Keep all internet-facing software updated to the latest version\"','及时安装补丁可封堵已知漏洞，是基本安全实践。',9),(2793,54,'judge','Ethernet LAN can send more than one packet at the same time on the same wire.',NULL,'false','传统以太网共享介质，同一时刻只允许一个站点发送，否则产生冲突。',10),(2794,54,'judge','Wi-Fi uses a similar contention-based strategy to Ethernet.',NULL,'true','Wi-Fi采用CSMA/CA，与以太网CSMA/CD思想类似，先侦听再发送。',11),(2795,54,'judge','Every computer has a unique MAC address.',NULL,'true','MAC地址全球唯一，由厂商烧录在网卡中。',12),(2796,54,'judge','When you use a domain name, it is looked up to get an IP address for the actual connection.',NULL,'true','DNS负责将域名解析为对应IP地址。',13),(2797,54,'judge','HTTPS encrypts all packets before they are sent onto the network.',NULL,'true','HTTPS在传输层加密HTTP数据，保护通信内容不被窃听。',14),(2798,54,'fill','If each packet is 1500 bytes, a 50 KB image divides into about ___ packets.',NULL,'\"34\"','50 KB = 51 200 B；51 200 ÷ 1500 ≈ 34.13，取整34个完整包。',15),(2799,54,'fill','A Wi-Fi network uses ___ waves to transmit information.',NULL,'\"radio\"','Wi-Fi基于射频无线电波通信。',16),(2800,54,'fill','DHCP stands for Dynamic Host Configuration Protocol, which automatically configures ___ settings.',NULL,'\"network\"','DHCP自动分配IP、网关、DNS等网络参数。',17),(2801,54,'multiple','Which are features of Ethernet? (Choose all that apply)','[\"Shared medium\",\"Distributed and collaborative\",\"Insecure by default\",\"No performance degradation\"]','[\"Shared medium\",\"Distributed and collaborative\",\"Insecure by default\"]','以太网共享介质、分布式访问、无内置安全，且负载高时性能下降。',18),(2802,54,'multiple','Which of the following are good passwords? (Choose all that apply)','[\"mottens,erx\",\"Mottens,9erx\",\"MotenX,97erx\",\"abc123\"]','[\"Mottens,9erx\",\"MotenX,97erx\"]','包含大小写字母、数字和特殊字符，长度足够，强度高。',19),(2803,54,'multiple','Which are common attack categories? (Choose all that apply)','[\"Password attacks\",\"Phishing attacks\",\"Malware attacks\",\"Hardware failure\"]','[\"Password attacks\",\"Phishing attacks\",\"Malware attacks\"]','密码、钓鱼、恶意软件是三大主流网络攻击类型。',20);
